window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_008"]={"n":"陈子升","dyn":"清","poems":[{"t":"江南好","f":"古风","c":["炎夏过，夜坐迥凄清。","千个竹风摇草阁，一规桂魄浸桃笙。","多少玉关情。"]},{"t":"南柯子","f":"古风","c":["羽曲清三叠，痫弦碎六幺。","绿珠绛树总魂销。","何必凤凰台上忆吹箫。","鬓影腾蝉翼，钗光颤翠翘。","歌残眉语暗相撩。","莫负可怜人度可怜宵。"]},{"t":"杂诗","f":"古风","c":["绡帏高廓，华燄辉荧。","眷连嘉友，据于中庭。","兴仰天文，炳月回星。","流睇神简，抗衷仙灵。","盌操芳实，壶挹兰醽。","忘情宿鸟，观理飞萤。","纳气扬歌，笙箫閒声。","丽襟绚带，疏发纡缨。","矩从心欲，雅繇志成。","乐以境通，大善无名。"]},{"t":"自悼诗","f":"古风","c":["有虞之裔，曰我邦家。","世有令德，为羽为仪。","逮我曾祖，于大司空。","赞我圣朝，如岳斯崇。","祖宰于湘，谦谦君子。","德言其盛，政曷维久。","亦越我考，宰登夕郎。","隆隆琐闼，嶷嶷封章。","封章伊何，击彼珰逆。","仡冒雷霆，匪休放斥。","威圣乃思，乃复厥犹。","家门仰恩，逝命不留。","嗟我总角，哀礼莫符。","伯滞京师，仲先蜉蝣。","母也是戒，汝季而孤。","念汝所生，汝修汝图。","执经就业，兢兢不已。","爰秀一乡，渐名四海。","我之奋怀，如葩斯启。","徒掇菁英，不数粒米。","冉冉三十，始冠明经。","鸿之方渐，驾言徂征。","纷纷百粤，濛濛两京。","罔遂观光，曷错幽情。","乃如八闽，八闽有穆。","弟趰丝纶，昆遥鼎玉。","衔命趣饷，披荆度榛。","使循东路，寇逼西滨。","章贡二水，胡越万里。","我生险阻，曰维兹始。","甫解归骖，狂氛载南。","园庐易主，咫尺巉岩。","维伯念止，天地崩颓。","岂无苟生，中心弗能。","成败利钝，非逆所裁。","风云冥漠，肝脑蒿莱。","嗟我处诸，谁为之受。","嗟我窜诸，谁僝我母。","有甚漆身，胡颜之厚。","人亦有谣，变于子丑。","豫章风驶，端水云从。","翛翛垂羽，掖垣是登。","山甫补衮，曷蹑前踪。","析薪负荷，曷克以绳。","彼苍者天，莫知其极。","城复于隍，否终又来。","嗟嗟同生，馀此一身。","昔耻粱肥，今憺孤贫。","何以甘母，斯苦斯辛。","何以为人，且夭且髡。","宗族閒阔，敦于母党。","昔也同堂，各谋所往。","西河卜子，爰丧厥明。","我其奈何，母心之伤。","万乘艰难，匹夫焉据。","自国徂家，职此之故。","既平匪欣，弗陂用惧。","承我寿嘏，无谖我虑。"]},{"t":"离合","f":"古风","c":["一丘若共，稻斛方均。","矧敢多乂，糊口垂纶。","吏首化争，当串以亲。","何人高卧，阜临东津。","孔公乙夜，与斗斜邻。"]},{"t":"大墙上蒿行","f":"古风","c":["飘风无不怒号，草昧雷雨，自我天造。","衰替一何棼棼，中心独苦郁以陶。","角春飒尔商秋，今我悯默复何谋。","人生居天壤閒，歘如陨叶乘奔流，我今悯默复何谋。","择君肌肤所适，遐不探君性命所存。","冬宴曲房温密，夏当临远水清沦。","牛马作走，我将复何谋。","不及君美晰风云，鸡人唱鹤盖诣门。","上有九重不测之苍天，今我安往谒夫帝。","下有九州环流之瀛海，今我安往济所届。","遐不汎览流观，遵君所迈。","淬我玉研，今尔何为自摧藏，功德安可量。","溪飞鸲鹆，峡走羚羊。","神龙四顾，睛注中央。","圣贤所务，变化无方。","辟凶殃，醇雅致福祥。","帝鸿之篆，娲后之章。","太公之匮，宣尼之堂。","琉璃之匣，紫云之房。","传称往昔，咸自谓要且妙，曾不知君研良，雅无当。","佩长剑之陆离，犀渠为衣，冠以雄鸡。","载驱载驰敌万人，挥斥安边陲。","班生投笔，终童弃繻。","苏卿之节，伯也之殳。","亦自要妙，胡宁舍诸。","考黄钟，阐玑衡。","东储甲观，西蜀元亭。","操彤管，播金声。","咏歌王风，辞若兰馨。","知彼通塞，不出户庭。","钓巨鱼如大鹏，与真人游息蓬瀛。","奉觞北斗，有酒如渑。","今日乐，诚可称。","乐未央，为乐当自强。","富与贵，如朝霜。","何为自误，使尔心伤。"]},{"t":"短歌行","f":"古风","c":["有酒盈樽，嘉宾在门。","直须延坐，庭光已昏。","悲当用叹，唇亡齿寒。","鲁酒伊何，围彼邯郸。","瓶之罄矣，惟罍之耻。","人生何为，忧来不已。","萧萧暮风，吹我榈栊。","悲满君怀，醉颜不红。","交交好禽，枝閒好音。","胡不如鸟，人各有心。","莺娇始簧，燕狂以䀪。","断鹤续凫，云胡短长。","琴则可歌，笙则可吹。","惠而好我，与子同衣。"]},{"t":"猛虎行","f":"古风","c":["露不择狭斜室，疲不策果下骀。","果下岂难驱，下流每见推。","指远跻北地，厉驾肃舆台。","耳乱幽崖风，目惊腐草埃。","昆疑搏猛虎，子勋弃黄能。","惫流聚渔罟，诡野多猎媒。","援涕不胜言，去去陟崔嵬。","高步应龙俱，长啸鸣凤谐。","吾生既自惜，不乐睹所哀。","如彼千仞桐，何为才不才。"]},{"t":"燕歌行","f":"七言古诗","c":["朔风洌洌天汉横，岁聿云莫雁流声。","明月皎洁霜雪盈，远道万里隔关城。","念君翩翩独远征，中夜不寐仰列星。","君怀意气入帝京，贱妾无言不敢情。","不得为尘逐君行，忧来短歌引秦筝。","哀弦乱柱不能成，梅花发枝吐鲜荣。","芳草因时藉百英，南金西土各有情，妾独无端转玑衡。"]},{"t":"拟青青河畔草","f":"五言古诗","c":["疏疏原上竹，悠悠想空谷。","空谷不可想，梦寐接形象。","形接翠帐中，忽觉在遥峰。","遥峰且隔岫，躞蹀阻婚媾。","轻舟知长川，松柏知山崖。","上堂各自炫，谁肯相为期。","客从西方来，遗我双白鹰。","呼童臂白鹰，翼有细篆绫。","长跪读篆绫，绫中竟何称。","上言各努力，下言利得朋。"]},{"t":"长歌行","f":"五言古诗","c":["离离墙下桑，枝弱根何强。","春风鼓萌檗，列树争辉光。","恒惧时雨歇，蕴隆嘉谷伤。","秋水喜河伯，如何犹望洋。","少小不好学，大耋嗟面墙。"]},{"t":"梁甫吟","f":"五言古诗","c":["驱马齐西鄙，纵观聊摄城。","城中有暮燐，云是燕将灵。","念既与燕隙，终不就齐廷。","风为增慨叹，日为照幽诚。","一矢激两端，三军帅自倾。","谁能出此策，高士鲁先生。"]},{"t":"精列","f":"五言古诗","c":["精列一何细，音响越区藩。","虎啸与龙吟，云兴而风旋。","虞帝解民愠，穆穆抚五弦。","邹生吹阳律，阴谷以弗寒。","吉甫吐清风，周公悲东山。","仲尼宝弦歌，有德者有言。","德音我所慕，小言良足叹。"]},{"t":"游弦","f":"古风","c":["抽园客之丝，鸣君堂上琴。","今我要列子，泠然而御风。","居世何为自龌龊，劳生以鞠躬。","君有酒食且饮食，我乐伊何任。"]},{"t":"薤露","f":"五言古诗","c":["皇祖卜世久，所遗谁最忠。","先帝升鼎湖，数子攀厥龙。","殉死乃无穴，号呼而且从。","鼎缺于磨室，京畿置南邦。","多见以不怪，弃之如转蓬。","家衮奋海隅，树帜思得朋。","力尽躯以捐，愤怨塞苍穹。","呜呼复呜呼，岂惟汉义公。"]},{"t":"行路难 其一","f":"古风","c":["君不见上兰门前特栖鸟，一歌一啭千门晓。","南飞越鸟北征鸿，有雏自远翩来同。","相调嶰谷千竿竹，教上龙门百尺桐。","承露盘前弄明月，万年枝上舞春风。","遥遥凫雁昆明水，细细条柯馺娑宫。","曾陪储后承华侧，每见皇帝凤楼中。","朝朝夕夕共翻飞，今朝今夕不相依。","昔托字尾愿为妃，一朝两意隔房帏。","自言多姿蔑翠羽，不念比翼朝朱晖。","霍家池上鸳鸯散，梁冀门前鹤盖稀。","独怜抗志矢金石，毛羽摧藏俄见讥。"]},{"t":"行路难 其二","f":"古风","c":["我奏潇湘二妃之宝瑟，西母白云之仙谣。","易京君明之龙笛，秦台弄玉之凤箫。","君家堂中既浩侈，洞房复帐留相调。","中有一人字白雪，鸣啴两鬓凤皇翘。","未许千金韩挟弹，徒逢十八贾登朝。","宝帐三千万阿那，使君五马躞蹀骄。","珊瑚悬钩出海底，自言寡向上宫要。","妙声丝竹迭无閒，罗帐忽已从风飘。","翡翠窗疏眉语度，莲花带弱精魂摇。","繁郎区区复叩叩，荆王暮暮复朝朝。","金卮满饮称既醉，思君此事非松乔。","人生寿命当有尽，焉如灵匹望河桥。"]},{"t":"妾薄命","f":"古风","c":["靡靡复厌厌，新歌昔昔盐。","花外刍尼啼月树，镫前喜子挂春檐。","京雒三千万宝帐，庐江六七十箱帘。","不逢荀奉倩，芳年徒自淹。"]},{"t":"双镜辞","f":"五言古诗","c":["照镜欲照双，双镜莫当窗。","窗前花复柳，镜影殊难偶。","一镜见妾容，双镜见妾背。","镜尚见妾背，妾面郎安在。","双镜亦徒然，破镜飞上天。"]},{"t":"伤歌四首 其一","f":"七言古诗","c":["山有高原树有丛，人情不伦何緵緵，我欲出门谁可同。","无多结交少年雀，不因人热童子鸿。"]},{"t":"伤歌四首 其二","f":"七言古诗","c":["树有丛林山有原，人情不伦何翻翻，我欲同人愁出门。","皎皎素丝在所染，营营青蝇止于樊。"]},{"t":"伤歌四首 其三","f":"七言古诗","c":["青蝇青蝇白璧玷，投畀豺虎非所厌，入门各媚三妇艳。","迷阳迷阳伤吾行，渡河渡河为公念。"]},{"t":"伤歌四首 其四","f":"楚辞体","c":["若有人兮非世情，愿欲矫举吹云笙，天不可阶仙难名。","渔父濯之沧浪水，美人赠以琼瑶英。"]},{"t":"祀何仙姑乐章 其一 迎神","f":"楚辞体","c":["飘罗兮练浮，灵纷葩兮迁绛趺，请阿㜷兮招鲍姑。","桂馔兮猿醴，煮白石兮清水。","故宫兮归来，源源兮不可以期。"]},{"t":"祀何仙姑乐章 其二 送神","f":"楚辞体","c":["灵不可兮栖迟，丹甃湛兮云以?。","无琼食兮珍果，君不可兮奉母。","鹅笙兮鼍鼓，渺缊缊兮独不下。"]},{"t":"射鸟曲","f":"古风","c":["射鸟射鸟，何射射燕。","射中燕姐，燕妹得见。","燕能内视，我身趫健。","班班捕獭狸，饭鸭得疗饥。","有不射，射必中，细听宫中歌赤凤。"]},{"t":"李将军","f":"古风","c":["李将军，霸陵尉，我方饮归尔大醉。","尔蒙虎皮我猿臂，猿臂能射山中虎，况发北平大黄弩。","霸陵尉，莫怒呵。","李将军，尔奈何。"]},{"t":"佛山曲","f":"五言古诗","c":["莫打佛山铁，且看佛山月。","看月见天心，打铁徒苦热。","人言佛山近，我言佛山远。","西水阻重重，胜于肠九转。","佛山那见佛，神山那有神。","东望高台在，谁为魋结民。","佛山大墟口，西水浸上田，裹饭张鱼笱。"]},{"t":"飞蛾篇","f":"五言古诗","c":["飞蛾勿飞飞，我言汝可通。","高者奔月蟾，下者衔烛龙。","蚌能吐珠辉，萤能照飞蓬。","彼皆爱光辉，不知汝懵懵。","歘尔投灯来，顷刻罹厥凶。","汝智自不周，汝力自不从。","汝今勿复飞，劝汝慎先几。","飞蛾懵不服，飞飞复促促。","促促污金镫，草草笑蚊蝇。"]},{"t":"楚吟行","f":"七言古诗","c":["越王台下水泠泠，白云山高高且清。","昌华苑中飞湿萤，当年美人字素馨。","虞园古树摇孤亭，六榕虚塔风檐铃。","骞槎杳矣海上星，蒟酱虽微闻汉廷。","箫韶南播森球钘，微辞能赋骚可经。","十七八岁女妖娙，繁华之子色晶荧。","承颜悦目效体形，转喉迭齿从心铭。","幽深翕辟行复停，宛转绵邈似不宁。","洞箫相和锵玎玎，指间密语通玲玲。","石泉溅溅飘蜻蜓，苍龙向月吟沧溟。","群莺飞飞乱柳汀，孤猿立木愁山屏。","仙羊剡剡来扬灵，陆郎乘骓排芳扃。","越人楚吟君试听，澧兰沅芷非独醒。","劝君犀觥斟醁醽，舒神导气延百龄。"]},{"t":"况操","f":"古风","c":["睎予长望，森何寥莽，无艰予之况也猗。"]},{"t":"韩山操","f":"楚辞体","c":["厥山惟韩兮，夫地惟人。","夙昔矫此志兮，何逡巡乎。"]},{"t":"古意 其一","f":"五言律诗","c":["摵摵园中树，上有最枯枝。","不惜枝叶落，但伤筋骨衰。","编篱引豆根，豆生篱已摧。","人生不乘时，奄忽欲因谁。"]},{"t":"古意 其二","f":"五言古诗","c":["张乐会嘉友，四座列娇婉。","盈盈挥玉筝，袅袅吹青管。","微微溢清唱，飞飞激素霰。","此曲何所来，毋乃绵驹撰。","曲终不可得，听者宜见隽。"]},{"t":"续成语四首 其一","f":"五言古诗","c":["片玉可以琦，奚必待盈尺。","匹夫可以豪，奚必待正席。","深山一羽衣，衡门一逢掖。","高风薄丛林，清歌散泉石。","相者皆举肥，我心痛如刺。"]},{"t":"续成语四首 其二","f":"五言律诗","c":["文绣被台榭，菽粟食凫雁。","施施乐其间，飘飘观彼粲。","厥中靡所蕴，卒与牺牲豢。","寄言少年客，毋令居所慢。"]},{"t":"续成语四首 其三","f":"五言古诗","c":["日回而月周，时不与人游。","众人皆疾足，羌余独淹留。","蟋蟀入我床，鸿雁何哀愁。","友生日以远，将在东山头。","亮哉宋大夫，四序独悲秋。"]},{"t":"续成语四首 其四","f":"五言律诗","c":["平流鼓怒浪，静树振惊飙。","渺哉风动人，美恶殊相摇。","枢机在言行，天地遐不遥。","子綦隐南郭，三籁日萧条。"]},{"t":"闺意","f":"五言古诗","c":["桃水手轻盥，衫襟短欲凉。","翠芝填后结，都是可怜妆。","镜影殊难已，裴回顾四旁。"]},{"t":"合江楼禊日兰亭体二首 其一","f":"古风","c":["白鹤高峙，青牛独驯。","假言居止，怀哉暮春。","将离匪谑，忘忧是珍。","桃实难老，桂酒陶真。"]},{"t":"合江楼禊日兰亭体二首 其二","f":"五言律诗","c":["山眉脩婉黛，波縠漾轻缥。","邂逅虚异人，翱翔望珍鸟。","曾史犹弊弊，松乔讵悄悄。","欲从褰裳涉，聊向江楼眺。"]},{"t":"五逝叹 其一 方巡抚孩未 震孺","f":"五言古诗","c":["方公实忠鲠，伟业四朝显。","骢驾使枭避，熊车向鲸剪。","厉辞过暴军，缓带安疑冕。","赤乌虚几几，匪躬终蹇蹇。","苍梧魄遂升，八公云且缅。","载歌方叔诗，泪满羊公岘。"]},{"t":"五逝叹 其二 张庶常天如 溥","f":"五言古诗","c":["天如今大儒，读书究根实。","汎爱引中上，综时相文质。","世史阐天官，肇阶仅庶吉。","腹驰董相猎，家续延陵繘。","王恻珍遗文，没哀绵筑室。","湛湛江上枫，秋风自萧瑟。"]},{"t":"五逝叹 其三 姚侍御有仆 奇允","f":"五言古诗","c":["姚公激秋爽，托契亦春霭。","风流畅西陵，雨泽酣南海。","植善乐非疲，锄奷疾无待。","玉几问殊勤，輶轩风欲采。","神振霜旄动，气增云堞倍。","可怜山雨秋，狐穴窥金铠。"]},{"t":"五逝叹 其四 李给事乔之 毓新","f":"五言古诗","c":["给事始郡理，执法标潮州。","风嘘走马埒，霜肃揭阳楼。","柏台昂笔札，箐谷怖兜鍪。","多士推辨施，迅诺赴勇繇。","驾言夕琐振，溘已朝露浮。","侧身望于越，摧心惟胶投。"]},{"t":"五逝叹 其五 黎兵部美周 遂球","f":"五言古诗","c":["同衣我黎友，蔚为天下士。","精义侔易京，赋心轹文似。","芳佩总南园，彪命专东里。","勉兹彤简授，谢彼青蝇迩。","笳咽落梅弄，魂冲九牛水。","琴德斯云亡，号钟吾已矣。"]},{"t":"代山人春夜閒情","f":"楚辞体","c":["麝月窥鸿宝，春宵劳羽人。","兰舒绡帐额，粟冻玉杯唇。","仙女元名玉，仙楼况是银。","谁能徒服鍊，今夕慕横陈。","横陈自不难，芳情何繇殚。","花香三岛路，春动七星坛。","东桑八茧稚，西桃百子团。","南林正蓊蔚，北斗未阑干。","峰前神女戏，海上丱兮欢。","彩女淮南鼎，仙童魏帝丸。","似觌莲华井，如逢积玉峦。","山花胡蝶蕊，径竹凤凰竿。","竿举凤凰仪，苕鲜翡翠嬉。","鹢眸屡以运，龙驾自躨跜。","踟跦光细网，灵蔡舞神蓍。","风环音若语，云步意弥卑。","天老终来教，曼倩始甘饴。","讵愁乌兔驶，宁遵牛女期。","七宝方诸液，双鸾苏合脂。","飞遁多烦惑，君来时见治。"]},{"t":"五子咏 其一 朱王孙仲韶 统?","f":"五言律诗","c":["王孙耽历学，要妙岂汝泄。","一游忽思归，得微合明哲。","索我先辈书，蒿庐用编缀。","宝君梅花笔，至今香不灭。"]},{"t":"五子咏 其二 徐徵君巨源 世溥","f":"五言律诗","c":["尺素书频至，南州徐子情。","书中论风雅，古乐扬咸韺。","行年及四十，出处定平生。","草堂今安否，青天空月明。"]},{"t":"五子咏 其三 方简讨密之 以智","f":"五言律诗","c":["简讨慷慨人，采芳自芬馥。","得时腾贾傅，失志托张禄。","醉挝渔阳鼓，悲写清商曲。","月明怀皖城，天地渺一粟。"]},{"t":"五子咏 其四 陈处士元水 上善","f":"五言律诗","c":["元水伟虬髯，谁薄歌鱼客。","篆隶研秦汉，昆吾切玉石。","好作五言诗，直分王孟席。","醉卧越姬怀，吴音戏相惜。"]},{"t":"五子咏 其五 刘兵部及叔 鼒","f":"五言律诗","c":["西蜀辞赋地，刘生实清矫。","儒冠执使节，抱璧能誇赵。","及我同在廷，尔亦辉旟旐。","归家谁负弩，天阔蜀山小。"]},{"t":"怀白君益","f":"五言古诗","c":["燕人白君益，侠气追田剧。","谈轻白璧双，诺少黄金百。","慷慨昔扬廷，子衿犹自青。","撄鳞本孤愤，摺胁亦怀刑。","遥遥来戍越，渺渺孤弦筈。","鹑衣自沓拖，鹤盖还胶轕。","高天月与云，比翼复离群。","缓急谁能免，悲歌殊忆君。"]},{"t":"为牵牛答织女和颜特进","f":"五言古诗","c":["白允戏穷桑，吴生搴宵桂。","嗟非二哲魂，弛张感天帝。","旭日遵始旦，明星加有嘒。","扬野不独躔，匏瓜岂吾系。","徒唏大梁影，久望长河澨。","方欣素节来，恒惧奔龙逝。","伐鼓申服箱，君其保神丽。"]},{"t":"依古","f":"五言古诗","c":["旷士想鲲游，大圣循鷇食。","鸿归皋氏舂，布就朱家匿。","平生失汎爱，而我忽相得。","玄豹韬南山，紫驼奔北狄。","安得千日酒，醉彼二心客。"]},{"t":"答亡可上人","f":"五言律诗","c":["潇湘殊不远，远思在夫君。","灵洲少佳气，苍梧空碧云。","碧云日复暮，朱夏悠悠度。","何用持报君，秋风吹琼树。"]},{"t":"感遇十八首 其一","f":"五言古诗","c":["冬夜寒且慄，孤灯爆环堵。","中坐一小儒，呫哔良自苦。","咽咽苍蝇声，思为鸿鹄举。","问君何所如，苏秦学王诩。","顶踵行济世，盍先剌其股。","七雄因以争，大野纷羊虎。","黑云蔽太空，白骨相撑拄。","独向人主前，揖让摇圭组。","方复笑穷巷，终身守训诂。"]},{"t":"感遇十八首 其二","f":"五言古诗","c":["箪食奔窭人，金珠竞王公。","膻蚁还相慕，小大胡雌雄。","窃钩干国禁，三晋为周容。","得失如循环，君看塞上翁。","方悟老氏贵，栖心在虚冲。"]},{"t":"感遇十八首 其三","f":"五言古诗","c":["陆生居吴中，郁为当世师。","吐言如洪钟，奋翼比长离。","声华绍父祖，出处关兴衰。","戴渊投剑日，周处剌蛟时。","自非君子者，斯人焉取斯。"]},{"t":"感遇十八首 其四","f":"五言古诗","c":["岁星为方朔，爰侍汉廷中。","诙谐非谬理，讽谏怀至忠。","西游见金母，东涉逢木公。","归献天子寿，身与道相从。","耻为入海客，荡漾无所终。"]},{"t":"感遇十八首 其五","f":"五言古诗","c":["仆本炎峤士，畴昔游幽燕。","幽燕俨神都，宫阙与天连。","青琐复金马，簪绂何蝉联。","策骏上金台，抗手怀高贤。","行行历黍谷，慷慨将谈天。","南归三十载，此路空悠然。","岂伊道里隔，苦寒不敢前。"]},{"t":"感遇十八首 其六","f":"五言律诗","c":["百年能几时，何不逍遥游。","欲绝尘土迹，且居明月楼。","高情属遥漠，延睇舒层丘。","待我凌云翔，与子谈九州。"]},{"t":"感遇十八首 其七","f":"五言古诗","c":["信陵能折节，四体讵无骨。","乐与毛薛游，中诚为之竭。","天道直如弦，相逢且自前。","昔为贵公子，今为被褐贤。","天爵固恒在，龙性非尔便。"]},{"t":"感遇十八首 其八","f":"五言律诗","c":["墨翟造木鸢，三年乃能飞。","梓庆齐七日，削鐻侔精微。","从来绝世技，宁寂中自挥。","至妙待孤赏，甘为庸俗讥。"]},{"t":"感遇十八首 其九","f":"五言古诗","c":["家本汉台边，且谈卢城事。","晋代昔陵夷，循寇飘风至。","黑云压城堞，白刃走官吏。","赤流溢通衢，阴雨出魑魅。","龙骧虽云廉，不镇兵戈气。","虽有高墉登，射隼曾何利。","遂使江干客，年年抆愁泪。","我欲歌此曲，此曲辞未既。"]},{"t":"感遇十八首 其十","f":"五言古诗","c":["昔我思遐方，诘曲赴羊肠。","猛虎嗥我前，山魈窥我旁。","风沙乱耳目，荆棘牵衣裳。","一行复九憩，中道正彷徨。","积岁望歧路，潸然中自伤。","焉知有云术，大鸟何翱翔。","非逢羡门子，尘土空摧藏。","君今从我游，一举横八荒。"]},{"t":"感遇十八首 其十一","f":"五言古诗","c":["子羽不繇径，渡江能刺蛟。","子房若妇人，椎秦翊汉朝。","不为方有为，闇闇成昭昭。","应龙不常信，危岑无长条。","周公才至美，所贵乃不骄。"]},{"t":"感遇十八首 其十二","f":"五言古诗","c":["秦王一四海，四海复不一。","英雄各方起，使者分途出。","坑儒虐黔首，奚止长城卒。","大势已分离，犹然用权术。","观其狂且愚，曷云保已物。","独有桃花源，桑麻自森郁。"]},{"t":"感遇十八首 其十三","f":"五言古诗","c":["崇冈生椅梧，阴谷繁荆棘。","民降道已微，登庸皆邪慝。","闻有猴而冠，亦见虎而翼。","正道自悠然，多营转促逼。","积丘畏蚁穴，朽厦繇蠹蚀。","邈矣夔龙俦，天运良不测。"]},{"t":"感遇十八首 其十四","f":"五言律诗","c":["赵璧羞燕石，宋人嘲卞和。","两两不相下，涂人如之何。","一真必一伪，较若千里多。","时无哲后鉴，溟涬且同科。"]},{"t":"感遇十八首 其十五","f":"五言古诗","c":["玄蝉抱木鸣，帝江审音声。","清响殊口给，至聪非耳成。","百足蚿不蹶，无形风常征。","况乃含万象，玄机不可名。","卷不盈一掬，舒之弥八纮。","斯唯达士信，庸夫鲜不惊。"]},{"t":"感遇十八首 其十六","f":"五言古诗","c":["西方金仙化，寂灭性长存。","维摩有家室，乃入不二门。","圣贤在忧济，于此未暇论。","嗟彼猥鄙儒，讥驳徒嚣喧。","操舟苦风浪，如何笑轮辕。","儒术不自尽，如何谤世尊。"]},{"t":"感遇十八首 其十七","f":"五言律诗","c":["东家桃李颜，日日登墙笑。","西第宴歌钟，往来皆权要。","北里习化居，青蚨走相召。","谁识南山南，松风答长啸。"]},{"t":"感遇十八首 其十八","f":"五言古诗","c":["炎汉昔中圮，伤哉巨滔天。","浸淫及缙绅，冠履纷倒颠。","诗书附瞋目，舆隶高比肩。","逐臭沧海畔，攫金都市前。","何意鹓与鸾，化为鹰与鹯。","平生九鼎重，蜕弃如蛇蝉。","遂满抢攘气，宁馀仁义田。","空令独行士，愁望盈荒烟。","濯濯严光濑，垂竿方洒然。"]},{"t":"思旧诗 其一","f":"五言古诗","c":["丹山串文羽，华井骈高叶。","胶漆畴与期，幸迩乃终浃。","显允北正裔，曩臻南园业。","偶席推儒珍，偕佩蹇童韘。","同心肇有言，齐策得所挟。"]},{"t":"思旧诗 其二","f":"五言古诗","c":["挟策贵能共，诵读相与研。","崇情排末流，蕴志慕古先。","揣摩慎双爵，亦已绝韦编。","赋心合綦组，丽则俦扬班。","气越千亩根，思漂百丈泉。"]},{"t":"思旧诗 其三","f":"五言古诗","c":["泉流惟源浚，亹亹克声闻。","灵镛警逖峰，含珠纳飞晕。","讵知榆枋抢，愿恣天地运。","所与四海贤，荡鄙复袪吝。","惠而能好我，不绝瑶华问。"]},{"t":"思旧诗 其四","f":"五言古诗","c":["瑶华谁不耽，芳浦嬉以遨。","奇服自廉洁，巃嵷出兰皋。","新声不定方，雅琴中自操。","东日矢明睐，朝云谑垂髾。","谁云声色误，声色方陶陶。"]},{"t":"思旧诗 其五","f":"五言古诗","c":["陶陶未及已，连峤迭遘患。","卑洼漏蚁穴，惊浸底怀山。","公言属黄口，变态兴绮纨。","日暮登台望，风沙千里寒。","上京纷已遐，驱马游近关。"]},{"t":"思旧诗 其六","f":"五言古诗","c":["关路前致辞，劳劳子何之。","凌秋进凿凶，慷慨趋危陴。","新组行就列，旧恩良不訾。","三命等浮埃，取义终若饴。","招魂魂孰归，将丽太常旗。"]},{"t":"思旧诗 其七","f":"五言古诗","c":["旗常子有垂，绅服我徒点。","神宫邈莫僝，岂复储琬琰。","盱云怅叆䨴，睇岫怵岖崄。","知我宛昨日，蒿薤歘已敛。","一辍流波弹，凝潸激西崦。"]},{"t":"赠朱光夜","f":"五言古诗","c":["弱龄学六书，钦君契斯籀。","虽云糟粕去，亦取芳润漱。","畴昔十数公，一一驰文囿。","夹毂问君家，飞盖相先后。","闻见溯渊源，师资證纰缪。","削垩安郢容，中微专羿彀。","丹青功莫展，刀笔技聊奏。","世运沦荆榛，晨星鲜耆旧。","雷鸣皆瓦釜，相类成裸祝。","嗟君遵雅途，抱璞匪云售。","搴霞雕棐案，览月吟圭窦。","慨叹念曩踪，殷勤重今遘。","玉麈清言挥，霜钟大音叩。","共阐名山秘，振衣跻岣嵝。"]},{"t":"二鸟诗 其一 唐宫鹦鹉","f":"五言律诗","c":["人情易亡故，相背成久寒。","唐宫有鹦鹉，遥问上皇安。","感恩金殿里，甘息陇山翰。","勿谓斯言细，徽音长不刊。"]},{"t":"二鸟诗 其二 宋舟白鹇","f":"五言律诗","c":["宋室收死士，何来一白鹇。","龙舟属惨淡，乌号悲莫攀。","负天乃无翼，蹈海不知还。","忠魂附丞相，感此泪潺湲。"]},{"t":"题李太白像","f":"五言古诗","c":["词林鸟归凤，千载想斯人。","恩向汾阳重，情连云梦亲。","少陵非匹敌，小谢契精神。","甚矣吾衰也，时无贺季真。","空然对遗像，文采映千春。"]},{"t":"七哀 其一","f":"五言古诗","c":["郁郁燕赵间，荒坟远相属。","武灵非故宫，尉佗自南瞩。","翁仲款魋结，石马閟胡服。","上有黄鸟鸣，飞飞睨幽谷。","既避巨君猾，复耻群莽秃。","忽怪夷吾衽，亦伤微管牧。","两畿继芜秽，阳爻嗟在六。","禹鼎何芒芒，众司诚覆餗。","魍魉见白日，荆榛蔽玄玉。","道闻木偶言，欪哉乱心曲。"]},{"t":"七哀 其二","f":"五言古诗","c":["燕赵不可游，言遵大海南。","海南多风涛，水浊高云阴。","方舟靡所届，汤汤迷山岑。","蜃气为楼台，帝阍遐且深。","下怒吞舟鱼，上惊垂云禽。","阳侯仰天啸，渊客中夜吟。","我欲叩洪钟，蒲牢增哀音。","素女曳霓旃，为我拂剑镡。","恍惚不复见，悲风吹远林。","轻世世何极，鲁连难为心。"]},{"t":"咏尾生","f":"五言古诗","c":["浮云无特操，皦日中自持。","尾生赴梁下，誓从女子期。","敢谓断金谬，鸐立俟音仪。","不惜久延伫，所嗟子不来。","水盈何漫漫，身复安所之。","人生不失信，之死甘若饴。","梁柱有坚心，悠悠使我思。"]},{"t":"辛丑拜墓作 其一","f":"五言古诗","c":["灵洲亘南海，石门揵西山。","斯备衣冠气，而出清洌泉。","重华韬九疑，妫裔流瀛堧。","茫昧逮有宋，哲祖卜终焉。","屡分齐市宅，亦归京兆阡。","累累溯高曾，默默开云元。","表碣俨斑驳，楸梧蔚葱芊。","聚族长兹守，行道咸欲观。","如何值丧乱，动止暌故田。","奠浆封树间，垂涕翁仲前。"]},{"t":"辛丑拜墓作 其二","f":"五言古诗","c":["皇考终谏议，归根附初垄。","遥阙眷徂贞，崇冈被嘉宠。","迩天壁若挂，擢地木云拱。","吁嗟三十载，陵谷皆颓覂。","防墓罢筑室，信陵谁守冢。","殁德讵能朽，生遁苦不巩。","霜露凄以零，岁时罕一踵。","松柏摧为薪，荆榛何蘙蓊。","封堂悯今俭，飞土钦古勇。","方洒黄垆泣，畴将昊苍捧。"]},{"t":"白发三首 其一","f":"五言古诗","c":["安仁美姿容，掌珠宁忍堕。","优游散骑省，渥丹照青琐。","命驾出郊坰，流辉生炙輠。","妇人连手萦，投我以珍果。","四八欻二毛，霜茎日已夥。","无复昔遨游，况乃多轗轲。","道逢掷瓦石，何独张与左。"]},{"t":"白发三首 其二","f":"五言古诗","c":["我闻夜交藤，能使人首乌。","我发从渠白，但愿一愁无。","此藤不足宝，不若树萱草。"]},{"t":"白发三首 其三","f":"五言古诗","c":["妾有盘龙镜，为君照白发。","照发复照须，繁霜不可遏。","染之不尽黔，拔去还复发。","天运既如此，恶之殊非达。","妾发长至地，甘为老奴悦。","愿君崇明德，毋事此微屑。","囊须在船中，士龙笑欲没。"]},{"t":"赠薛剑公","f":"五言古诗","c":["东城倦昔尘，西山憺今雾。","扬镳非爽术，戢翼有恒处。","与子两世籍，爰得平生遇。","挟荚悯亡羊，析薪从所务。","妍思茂春华，贞心烱秋素。","神理掇隋卞，太音锵咸頀。","方执黄牛革，言终射雉誉。","声微群喙张，浸广颓波赴。","佳恶虽自知，方圆匪独顾。","申章对妙匠，兰言在无斁。"]},{"t":"赠友诗","f":"五言古诗","c":["高台迅风发，吹我出严城。","崎岖偶干禄，栖迟遂逃名。","广居趋此隘，巢枝谢彼营。","讵伤浮华歇，恒惧无友生。","叹川觏明月，吟泽揽芳蘅。","愿君怀妙善，崇此千秋情。"]},{"t":"咏贫士","f":"五言古诗","c":["茂树有来憩，寒枝鲜见臻。","思为千亩阴，咄嗟空本根。","土膏不独异，尝与桃李邻。","陨叶随狂飙，已冬复望春。","处约苦心志，造草非小仁。","天地有倾缺，君子宁忧贫。"]},{"t":"止酒","f":"五言古诗","c":["酒泉尝戾止，不止石与斗。","夜饮不止卯，朝饮不止酉。","清不止尧舜，浊不止桀纣。","垆不止胡姬，瑟不止赵妇。","自从止一丘，十事止八九。","所止嗟因人，敢不自止酒。","时时欲止之，既止还复否。","虽云止勿乱，不止孔之丑。","止水有明鉴，皇王止敬口。","援琴歌止息，迁莺止高柳。"]},{"t":"适吴诗送黄羽可","f":"五言古诗","c":["章甫将有资，乃从南越适。","问子适何方，泰伯古所历。","兴废奚足云，贤哲丛今昔。","文心言子秘，乐意延陵析。","被裘无妄睨，栖庑有嘉觌。","彼观隆四姓，我想驰三益。","矧我梦寐劳，匪伊朝且夕。","送送超庾关，望望弥震泽。","海气肃襟袂，秋风迅帆席。","流霞烁鸡陂，寒月皓虎石。","允与素心人，抗论通云霓。","邂逅情或对，应求理不只。","无挟玙璠姿，取笑瓴与甋。"]},{"t":"增葺居室","f":"五言古诗","c":["唐帝勤茅茨，原生乐桑枢。","宁殊贵与贱，咸以约故优。","曰予仰先世，廉洁崇厥脩。","开宅及晏子，垂貂踰秺侯。","讵悟板荡时，违彼康庄衢。","固志天山筮，怍情箕颍游。","扃林遂创关，叠阜靡资楼。","栖迟亦三稔，补苴仍一丘。","苟完师卫荆，不贷希蒙叟。","循今有逸轨，抚往无嘉猷。","恒刺丈夫怀，永与智者俦。"]},{"t":"哭容舍人","f":"楚辞体","c":["潜颖趋陵苕，春秋欻崇朝。","英年遵凤池，凤池悽泬寥。","环海既尘转，洪炉使金销。","美人减膏沐，冥思寤华宵。","宵华宵已冥，魂兮为难招。","重闱黯不处，天路空遥遥。","何以致子哀，涕泗霏寒潮。"]},{"t":"陇西客","f":"五言律诗","c":["客从陇西来，慷慨言城朔。","军行踰迅飙，阵立齐崇岳。","将军始建牙，杂种谋崩角。","谁堪夜已中，栖鸡自咿喔。"]},{"t":"赠元孝","f":"五言古诗","c":["翩翩两巢凤，巢破凤各孤。","羽仪一不作，云海空提扶。","同声复同气，我尔有是夫。","身从太丘衍，名可竹林俱。","谁能道往事，泪下凝为珠。","每感风人旨，伤哉大雅徂。","后死文未丧，先民有遗模。","愿言振高响，金石同不渝。"]},{"t":"赠梁芝五","f":"五言古诗","c":["南园忆旧社，西园见新作。","之子寤鲜荣，芳菲倚蘅若。","心轻进士举，归以骚人托。","结客多鸿冥，招予方雀跃。","于此谐素心，匪徒丽金雘。","君家昔比部，七子名辉灼。","今日西园游，中原伹寥廓。","当杯申此章，相厚不为薄。"]},{"t":"予居客馆主人养白鹇又有持山鸡至并置笼中山鸡斗击白鹇损其毛羽予怜之劝主人斥去山鸡因为白鹇作感激之辞","f":"五言古诗","c":["佳哉双白鹇，笼养君轩墀。","雄者能知白，黑者能守雌。","自违林薮愿，戢羽感恩私。","不争鸡鹜食，仍惜凤凰枝。","殊族逞嘴距，欻来将我欺。","非赖有心人，安能脱羁危。","三谢主宾意，永怀云峤期。"]},{"t":"咏西洋显微镜","f":"五言古诗","c":["大道粲中天，奇淫出穷海。","兹镜西洋来，微显义兼在。","雕棘具猴体，穿杨贯虱胸。","何如造兹镜，微妙生其中。","蚊睫焦螟巢，蜗角触蛮战。","以兹当少怪，况乃多多见。","芥子纳须弥，毛间盈海水。","微今显镜中，显却在微里。","我目有神镜，我心超离娄。","拂镜归玉匣，反观将内求。"]},{"t":"失题 其一","f":"五言古诗","c":["虎之逐人噬，得物怒则专。","妄人甚于虎，所怒恒屡迁。","薄愬忽逢彼，三反宁得悛。","知音既不存，孤我伯牙弦。","彼哉复彼哉，独为优游仙。"]},{"t":"失题 其二","f":"五言古诗","c":["我心本无争，嗟尔胡为竞。","啄腐向屠门，慕膻从赵孟。","沾沾拾锱铢，言色殊巧令。","徒劳魍魉姿，入我方诸镜。","不能畀豺虎，今日谁为政。","我将弃君去，去去存龙性。"]},{"t":"失题 其三","f":"五言律诗","c":["一世为隶胥，三生尚魑魅。","如何绅裾列，而有隶胥气。","霸陵诃李广，犹幸逢醉尉。","虚舟触褊心，不如却相避。"]},{"t":"失题 其四","f":"五言古诗","c":["阳虎善为富，多金致贤声。","诸侯敦币聘，都人望弓旌。","遂使里中儿，效尤转相倾。","俄闻怀璧夫，无罪干国刑。","乃知金踊跃，于人无定形。","不为庙中牺，必为粪上英。","寄言素封子，努力崇虚名。"]},{"t":"失题 其五","f":"五言律诗","c":["客有千金方，藏之不肯衒。","自言服食功，能令鬒不变。","解将白石煮，以奉红云殿。","一身裂地封，龟手从水战。"]},{"t":"失题 其六","f":"五言古诗","c":["平生山水趣，兼之云物情。","有客貌鲁儒，规予毋外营。","文质不相宣，茫昧求至诚。","讵知掇秋实，所植从春英。","玉洞有神龙，蜿蜒无留行。"]},{"t":"失题 其七","f":"五言古诗","c":["淹留忽白首，慷慨思平生。","年纪方秀发，天衢一何亨。","黄鹄羽初齐，裴回欲飞鸣。","致身何所期，伟迹光汗青。","追念古先业，扬镳抗群英。","得志必济世，拂衣始辞荣。","奈何抱此愿，时过竟无成。","凤衰逢接舆，却曲伤吾行。","功德属已往，立言吾奚徵。","端居发浩歌，空有金石声。"]},{"t":"别诗 其一","f":"五言古诗","c":["六合为广厦，各自开房居。","往来廊径间，焉得免行途。","我非无敝室，之子静且都。","帏帐容我寝，饮食令我腴。","三暮敛心神，凌晨拜前除。","辞毕不我拒，劝戒成芳模。","寄言同堂子，聊复充此闾。"]},{"t":"别诗 其二","f":"五言古诗","c":["居者思有行，行者思所止。","不知谁主客，对彼乃称已。","毂辘天地间，何由见真宰。","盆中环游鱼，磨上旋转蚁。","我欲穷八荒，拔山倒海水。","不就天人师，旁皇莫为理。","安得无住舍，招尔同居此。"]},{"t":"詶韩叔夜","f":"五言古诗","c":["行子极秋气，盘旋竹房清。","邑宰来相存，促膝非世情。","告我一高贤，名家自鄢陵。","永嘉行罢秩，贫胜南阳耕。","肝胆倾四海，旷若云山晴。","旅寺邻咫尺，奚容隔平生。","相见欢称诗，高谭金石声。","我观靡靡者，俗尚纷营营。","非君激新论，谁能闻典型。","愧我客临邛，如君诚长卿。","传音归故林，千里皆和鸣。"]},{"t":"赠赵双白","f":"五言古诗","c":["海底双明珠，月晕含天色。","安能久沦没，当为海人得。","一人得此珠，怀之未敢出。","一人得此珠，照乘行列国。","自然成剖符，神彩暗相射。","愿言各珍重，崇此双珠德。"]},{"t":"玄墓山探梅","f":"五言古诗","c":["寒浦入轻舟，春山引孤策。","烟开见飞鸟，雪澹无行迹。","仄径援山臂，高根逗泉脉。","旁临邓尉卑，回望阊门窄。","日照寺微绀，湖涵梅尽白。","诸天恣花供，大地成香席。","石壁张丹青，茶山啜云液。","悠然遂终日，归路思弥绎。"]},{"t":"客中咏二高士f 其一 吴门梁伯鸾","f":"五言律诗","c":["踰岭去桑梓，吴门花发时。","出门仰天笑，聊以当吾噫。","逸妻岂不恋，求友兴深思。","一过伯通桥，夫君洵我师。"]},{"t":"客中咏二高士f 其二 南州徐孺子","f":"五言律诗","c":["南州走冠盖，高士居亭亭。","吾宗不见君，悬榻甘尘冥。","千里为有道，生刍致惟馨。","我亦悦此风，旷怀翻涕零。"]},{"t":"三子赠答诗 其一","f":"五言古诗","c":["我昔游五岳，登高仰寰宇。","附孔上泰山，攀葛吟梁甫。","封禅七十二，其事在太古。","继此徒荒唐，秦皇与汉武。","绵邈予有怀，飞龙居九五。","黋炳以辉煌，圣作而物睹。","一人响圜方，百辟分茅土。","子其从我游，高名录天府。"]},{"t":"三子赠答诗 其二","f":"五言古诗","c":["万古众仙父，卓哉何巍巍。","是辟长男宫，出震凌晨曦。","烛龙衔焜曜，扶桑挺葳蕤。","下顾世民子，劳劳会瑶池。","伯阳度函关，紫气恒相随。","吾祖事皇汉，长与桃实期。","至道存玄言，馀用乃滑稽。","积小以高大，冲虚何所疑。"]},{"t":"三子赠答诗 其三","f":"五言古诗","c":["宿世随国贰，入山求正觉。","岂以元舅尊，而终縻尔爵。","仙庵对忍辱，净土崇极乐。","鹙子等诞身，迦陵鸣在壳。","幸于五人中，得度自超跃。","净名来妙喜，不二非扃钥。","龙卿勿矜庄，东方休善谑。","皈兹三世佛，诏尔无生学。"]},{"t":"述交篇送郭皋旭还平湖","f":"五言古诗","c":["君家在平湖，相识松江上。","风雪古招提，羁离两相向。","我谢孟尝舍，君将茂陵返。","携我归湖居，解衣劝加饭。","平湖先子泽，故旧情欢然。","缱绻相问遗，郭生先礼贤。","寒夜风飕飕，高斋四座稠。","腊拟吴门过，春期粤海游。","淼淼大江还，迟迟玉山度。","我老子非少，焉能任长路。","雪鬓满头白，荔枝千树红。","归人迎客子，重为说南中。","八月高凉道，山车碾秋草。","不嫌逆旅恶，惟觉诗篇好。","折尽庾关梅，还同北雁来。","未寻蓬荜地，孤负菊花杯。","我昨过庐山，白衣受僧戒。","君从胎已斋，旅食忘鲑菜。","我违五岳愿，千里归训子。","君今纳粤妾，有子从此始。","王门一曳裾，赠橐知何如。","千金何足贵，所贵真南珠。","浙水白迢迢，应通南海潮。","寄语湖中旧，音书肯寂寥。"]},{"t":"答旷圆大师罗浮见寄次韵","f":"五言律诗","c":["悠悠浊世内，屹屹青山上。","夜半观日出，空中听鸡唱。","缁衣弄大蝶，朱凤群相向。","独有水乡人，烟波坐惆怅。"]},{"t":"四臣咏 其一 丘文庄浚","f":"五言律诗","c":["琼台峙海曲，博奥穷寰宇。","史文繁复系，经义衍犹补。","论道殊耻今，多艺亦侔古。","微特崇文朝，星云灿可睹。"]},{"t":"四臣咏 其二 陈文恭献章","f":"五言律诗","c":["白沙溯洙泗，展副真儒名。","应龙能屈信，天爵谢尊荣。","居楼符碧玉，及门尽豪英。","遗范有馀仰，吟写胥神明。"]},{"t":"四臣咏 其三 梁文康储","f":"五言律诗","c":["梁公社稷臣，玉铉捧神器。","草诏可回天，归家惟隙地。","九庙鉴诚悃，万方藉元气。","远与曲江俦，心同时或异。"]},{"t":"四臣咏 其四 海忠介瑞","f":"五言律诗","c":["刚峰实无欲，奚止金百鍊。","开府肃钟山，正冠是铁面。","渡海漱波涛，昭天彻雷电。","权奸昔已惊，顽懦咸追羡。"]},{"t":"拟作贾生适长沙诗","f":"五言绝句","c":["南赴长沙路，侧身思雒阳。","我岂黄发人，用辅长沙王。"]},{"t":"进帆石门怀古","f":"五言古诗","c":["卢城伤飒沓，郁水引游衍。","虽非千里驾，发棹自成远。","郊原互盘纡，洲渚迭溶演。","水波舷下割，日影帆上转。","巀嶪开一门，澄鲜豁双眼。","层阿蔓绿萝，阴石滋斑藓。","坎流知所止，井汲当自选。","怀金泉靡堙，不易心弥显。","讵以朵颐龟，取笑饮河鼹。","亮为江海人，独契蘧生卷。"]},{"t":"听歌篇","f":"古风","c":["柔风回上座，明月鉴中庭。","主客辞方毕，惟知歌可听。","珠江渡口名家子，引商刻羽兼流徵。","合綦列锦赋家心，流水高山琴士指。","江淹梦笔笔无穷，周郎顾曲曲全美。","提纲清管与繁弦，领袖朱唇复皓齿。","皓齿朱唇初出声，何来芳气似兰蘅。","远想丹山鸣彩凤，近疑绿树流娇莺。","双眉静悄相生月，小口吹嘘自食樱。","低处看随香水泛，高时仅及画梁平。","画梁香水自高低，欲寻歌影自凄迷。","空飞柳絮沾芳陌，不语桃花烂绣闺。","莫愁本荡石城桨，夷光原住若耶溪。","绿鬓春风随处所，白头沟水莫东西。","白头绿鬓须及早，当筵一曲今宵好。","下蔡曾因处子迷，邯郸但惜才人老。","共戏田田唱采莲，人生纂纂闻歌枣。","千金一刻实相当，尺玉寸阴为君宝。","歌台舞榭且年年，歌声舞态值多钱。","遏云响绕合欢结，凌波步引双行躔。","双躔双结携双手，一斟一酌倾一斗。","门前梧子见梧桐，塘上莲花隐莲藕。","客多齐士薄吹竽，家本秦声同抚缶。","自是娇娆御枕衾，莫言臣妾亲箕帚。","箕帚甘心事所欢，裴褢歌罢一何叹。","可怜锦字秦中织，可惜琵琶塞外弹。","主人有酒盈金盌，缬眼低声送寒暖。","彩扇轻藏尚自羞，金钱历乱无人算。","鼓瑟珠宫帝女床，吹笙碧落天鹅管。","楚庭灭烛笑缨纷，秦帝卷衣怜带缓。","卷衣君更歌，缓带奈君何。","共惜知音少，歌时苦思多。","二六之车三五城，听歌车曜复城倾。","绝代佳人休独艳，劝君须识兰台英。"]},{"t":"怀芳篇寄徐子能","f":"楚辞体","c":["东吴繁绮会，南越贝珍丛。","霜雪无论异，英华且复同。","阡阡垂柳绿，坞坞发花红。","共识王孙路，俱翻少女风。","王孙少女若相望，知是君家难可忘。","时闻招客山中桂，每见停骖陌上桑。","江南曲羡田田叶，卷耳诗劳采采筐。","寻常游玩木兰楫，特地栖居文杏梁。","姑苏台上睋朝汉，海珠石望虎丘畔。","夫差勾践几兴亡，赵尉吕嘉谁治乱。","素馨骨已化，西子魂今断。","云烟响屧心，风雨花田汗。","花田古渡对羊城，无复刘王歌吹声。","皎蕊空施云髻重，清葩徒结彩灯明。","金屋调音歇鹦鹉，雕盘止妒罢鸧鹒。","红云终宴帷空树，赤帝司方日发英。","已知前迹成销烬，今日才华应叠进。","宋玉微辞或学师，马卿工赋非徒蔺。","当今郑侨百是茂先，关西孔子添杨震。","咸从郁水照衣冠，况有罗浮耸颜鬓。","罗浮海上山，珍禽相往还。","百花恣栖啄，五色自斑斓。","能歌同气鸟，知止类绵蛮。","鷾鸸称莫智，山侣定非顽。","葛稚安期寻不得，丹砂紫朮元虚色。","荷锄漫尔掘黄精，执笏真须朝紫极。","地灵风度曲江相，天花香水曹溪释。","绮思将分鲛女机，玄情每贪云母液。","佳气何氤氲，家山傍白云。","栘华时共照，兰室更相薰。","不慕灌园节，惟追运甓勤。","接舆无用避，植杖可同耘。","閒居商榷平生志，问姓通名更何事。","欲学承蜩向丈人，讵轻求马从唐肆。","自信家乡僻更僻，莫道人间易还易。","一心闭户将著书，何虑出疆难载质。","四方顾盼多佳游，同心不少向苏州。","最忆知人有皋氏，从来文学记言游。","千金带墓剑，五月取薪裘。","季鹰步兵号，元叹遂乡侯。","酒城石城随兴瞩，皋桥枫桥水平绿。","六月凉风销夏湾，百花晴日歌春曲。","杨柳芡实信云美，莼菜鲈鱼我所欲。","赤松采药已升灵，林屋取书殊不俗。","清江淡远天，荡漾采莲船。","双双悲凤管，点点匝鹍弦。","周郎今日顾，子夜昔时怜。","因兹艳二八，欢我客三千。","我所思兮吴地好，美人是处吟芳草。","偏是江南白雪多，应知岭外梅花早。","结客君怀燕蓟地，寻姝我羡邯郸道。","红尘青眼我能同，赭白斑骓君自保。","芳草长，百草芳。","萋萋路边千里月，青青河畔九回肠。","兰菊佳人怀自切，芙蓉吾子隐相将。","云字馀鸿雁，春衣袭鹔鹴。","遥同冠玉美，相和郁金堂。"]},{"t":"爱妾换马篇","f":"七言古诗","c":["桃花妆上桃花辔，飞燕身轻飞燕骑。","春风拂拂见胡天，丽影飘飘宁著地。","凌波不信水中移，响屧休惊廊上戏。","芳草轻腾一似难，花枝巧折仍何易。","公子王孙俱在旁，佳人骏马两相当。","携手舒眉相对乐，捋须脱帽众皆狂。","不誇公子金珠饰，不羡王孙锦绣装。","只看袅袅吹红污，只爱纤纤控紫缰。","须臾下马颜微赭，芳气娇情满春野。","公子执之语王孙，我有佳人尔骏马。","羊城一笑胡为乎，燕市千金何故者。","多君骐骥借人乘，应倩丹青为君写。","人生娇贵建功难，记得当年女木兰。","今夜织机啼络纬，明朝跨马泪阑干。","装刀买箭钱教尽，委线抛针衣不单。","未曾嬿婉从夫婿，已见勋名制可汗。","骥不称力称其德，未见好德如好色。","借问娇妻奉倩情，何如丑妇南阳识。","娇姬至死在同床，老骥长思悬伏枥。","请将所有易所无，此意非痴亦非激。","王孙听罢久无言，手向雕鞍不忍扪。","知音祇为逢钟子，举鼎应还有孟贲。","粉妆西泣羞新主，银勒东嘶结旧恩。","急将马去予携妾，无令长驱感懦魂。"]},{"t":"答张公亮揭阳慰予下第","f":"七言古诗","c":["丈夫身作楚人弓，照乘泣刖珠玉同。","咄嗟小儿怨秋风，迷阳不生大道中。","三年一赋灵光殿，蜃市银云看成变。","祇因错认万言书，安得齐名三语掾。","琴张先生劝莫嗟，陈孔赭白骄谁家。","蓬心待扶惟直麻，行行采采幽兰花。"]},{"t":"怀兰引","f":"七言古诗","c":["越罗织得吴蚕死，裁向青楼悬近水。","旁人劝道休洗红，请解楼西收向东。","东楼初日西栖夜，夜月照人人在下。","楼前月明常入人，楼后灯悬春自嫁。","中有一人字秀兰，不长不短千娇姹。","依稀记是广陵生，意已倾城名尚亚。","送旧迎新未一年，王孙痴迷公子颠。","颠迷态尽轻相对，不爱贵人爱优辈。","一优自言最少年，浪荡梨园专取配。","不难借债转将来，金重身轻重数倍。","沈香海青作娇客，细帻连眉边窄窄。","生涯向似棹船郎，典得铜街主人宅。","初来半月当从良，池边三十六鸳鸯。","鸳鸯别对应相避，南北东西鱼乱戏。","时嗔时喜真作俳，莫往莫来终风霾。","赌去稍卖寒衣服，穷来渐渐取金钗。","别有营间名阿满，此优捖牵情不断。","须令逼下旧时人，才与重开新样春。","变云起浪多龃龉，可怜柔脂受击楚。","朝朝暮暮太相煎，驱去觅钱换米煮。","此何窸窣彼何浓，狂且独拥娇芙蓉。","笼中鹦鹉不得脱，戏作猢狲强挑挞。","悉心向人人尽哀，客子将金欲娶回。","徒将此苦易彼乐，虚言高价无力媒。","人家流苏玳瑁床，幽窗团结龙涎香。","隐回清泪背清炬，知心问心一夜语。","三十年前张四名，人人欲死村村争。","于今子长孙善走，相代擎茶上戏棚。","冯细从良初不久，仍歌旧曲劝人酒。","忽然削发变为尼，住向南郊菜塘口。","为尼不久还作唱，双缠紧系罗包首。","世上纷纭颠倒多，参禅大将从军妇。","诸姬转徙天运然，独有秀兰人不怜。","日嗟日叹无休息，叹到将军听不得。","一朝侍坐众宾筵，缚出优来面如墨。","情甘输妇赎得生，乞娘一言高座侧。","鹯容骂尽还自羞，从此人间不相识。","秋深有客来长河，河上青沙荡白波。","车尘马迹凝秋水，如是军旌归路过。","上船武妓遮鱼贯，中有湘裙露寸半。","欲行不行怯路难，须臾众步相凌乱。","我闻客言方有怀，暗缸朦月尽安排。","白日扬声响高屋，缓声却转疑丝竹。","锵然飞雁鸣一声，客舍门虚见山木。"]},{"t":"红衲歌","f":"古风","c":["我昔登山临水高洁而光辉，君看红绫叠锦千针之衲衣。","凛秋严冬与之侣，春寒采采皆芳菲。","南中四时花不绝，披此但少雪花飞。","客谓以此远游更足以环玮，与子期乎峨眉、雁荡、芦洲与钓矶。","可怜此后触世机，出门栖栖资斧微。","就官随班强著绯，归来天地交旌徽。","今日萧条尚馀此，青云绝迹穷山里。","狐白千金徒侈耳，人间爱马筐盛矢，何为长戚自令鄙。","君不见浮丘袖阔麾烟霞，毛女衣单拾松子。"]},{"t":"越王台","f":"古风","c":["君不见越台百尺雄城阙，辇路传游百花发。","黄屋晴连汉塞云，青山晓挂秦时月。","龙川霸气日苍凉，横海楼船更渺茫。","北风吹散南枝鸟，惟见平沙牧马场。"]},{"t":"弹琴箕山秋月歌","f":"七言古诗","c":["张琴须张太古弦，七弦直溯五弦前。","太和不远阴明代，飞遁长流洗耳泉。","南河未避虞鳏晦，箕山明月斯人在。","当年帝德总如春，独有秋光澹相对。","琴音微微世莫闻，罢琴惆怅月纷纷。","琴中不见箕山月，羞向他山麋鹿群。"]},{"t":"丹青引为朱二文晖题真","f":"七言古诗","c":["芙蓉侧理瑩鹅毛，翡翠回波濯兔毫。","画成如玉应名玠，不觌甄妃讶姓曹。","拂石有声聆泗磬，种兰将采问湘皋。","名士何妨矜独立，画师惟肖羡同袍。","同袍袍色华春草，同心心结娇文褓。","待聘逢君席上珍，迷邦笑我怀其宝。","怀宝席珍从屈伸，光仪物色总传神。","扇中鸾影秦王女，阁上麟图汉代臣。","臣是素丝还绣像，女贻彤管用书绅。","奇字近耽扬子宅，微辞回动宋家邻。","宋邻扬宅才情出，花屿芗林保昭质。","谁复罗胸有众星，谁能晞发临初日。","养德曾如纪渻鸡，植根肯变淮南橘。","风流将尔乐衡门，年少何从奏宣室。","宣室兰台意不忘，琅玕绕屋坐江乡。","千秋必向青云附，什袭还看宝轴装。"]},{"t":"竹下走笔简薛二","f":"七言古诗","c":["三年种得两丛竹，疏疏映我池边屋。","安得凉生十里阴，与君来往无三伏。","君家易知复难忘，春自罗浮归草堂。","罗浮竹大堪为屋，屋上干云从更长。","僻居两两辞城邑，地阔天长莫羞涩。","时见醯鸡瓮里游，几何高士林中人。","我今怀君复畏人，欲向竹林藏此身。","君来寻我乃相见，同话三山海上尘。"]},{"t":"咏镜","f":"古风","c":["汉皇露掌分青铜，蒲萄神镜凝妆红。","照颜还照月，怜水复怜空。"]},{"t":"张山歌","f":"七言律诗","c":["偶问山名识山姓，张山若个张君命。","未见留侯松子游，今看仲蔚蓬蒿盛。","蓬蒿萧萧秋满山，长松之下水潺潺。","愿君姓名皆不著，杖屦因君忘往还。"]},{"t":"稚子弄促织放书斋中秋夜增怀便成长句","f":"七言古诗","c":["湘帘不捲知秋色，中夜萧萧闻促织。","开笼稚子戏方阑，闭户先生听不得。","仆本雕虫应律鸣，谁家懒妇及秋惊。","回旋秦锦教成字，摇落豳风别有名。","此日银河看渡鹊，此时芳醑失听莺。","爽籁遥吹蠮螉塞，寒砧不捣凤凰城。","狭室青灯隔虚旷，满床缃帙犹无恙。","歌舞人矜却月楼，诗书婢笑扶风帐。","邺客追游息雀声，刘郎起舞悬鸡唱。","那堪唧唧近床头，那遣迢迢翻枕上。","春鸟秋虫岁岁听，每怜蟾兔晃中庭。","何事芸香辟仙蠹，漫将纨扇扑流萤。"]},{"t":"为高生寿母","f":"古风","c":["高恢善事母，宛在霸陵山。","圭峰作瑶台，松际梳雪鬟。","贤母教令子，谋道不敢閒。","米从仲由负，衣待伯瑜斑。","四十犹悬干禄身，岂徒笔墨养慈亲。","只今未老居东海，还傍麻姑理钓纶。"]},{"t":"秋水轩行为吴僧六虚作","f":"古风","c":["君不见吴门文启美，爱过僧居濯秋水。","与画小幅皴细起，素楮淡墨如叠绮。","吴僧自有秋水轩，我嗜此画僧乞言。","君不见昔时卢鸿草堂能涤烦，手笔落落矶翻翻。"]},{"t":"锦石山怀陆生","f":"七言古诗","c":["汉祖当日诛狂秦，尉佗本自倔彊人。","陆生儒者持汉节，自娱黄屋遂称臣。","南粤迢迢天咫尺，佗为东道使西席。","曾同魋结汎兰舟，为祷山灵酬锦石。","使能不辱佗不疑，天心人事皆有时。","君看锦石成千古，请向山花折一枝。"]},{"t":"璅蛣行","f":"古风","c":["开君蒲萄之瓮醅，捧君鹦鹉之螺杯。","高堂促席方就饮，美味忽自江中来。","借问嘉名名璅蛣，腹蟹从来景纯说。","水经注就赋还成，岂漏熬波与积雪。","季鹰歌里想鲈鱼，谢监诗中寻海月。","丰不必啖肥脓，清不必采薇蕨。","欲食飞鱼不可期，欲脯青麟海难越。","君今璅蛣且须尝，佐以三杯高兴发。","忆昔朋从郁水洲，食如填壑饮如流。","此物时时可以致，齧妃女唇甘且柔。","右倚灵妃左浮丘，景纯游仙从我游。","试将璅蛣荐羽流，蓬莱清浅湘漓秋。","天地微茫何不有，有鸧九头龟六眸。","二虫一体相为命，璅蛣登庖蟹自愁。","啄腐吞腥累仙道，甘此未失为聃周。","进君酒，君下箸。","君不见何曾万钱不称心，江水悠悠向东去。"]},{"t":"送一灵上人出塞寻祖心禅师","f":"七言古诗","c":["曹溪学者楚臣裔，贝叶莲花卷荃蕙。","经行忽感远游章，飞锡将穷沙漠际。","极北霜多芳草无，弥天路断月明孤。","萧寺何方来白马，秦关空见落黄榆。","十载飘零祖和尚，玉门投老非为将。","化鹤难归华表前，牧羝更在天山上。","尔寻先觉岁方秋，鸿雁南宾尔北游。","莲社称诗别庐岳，梅花赠远忆罗浮。","边沙往往销金铠，布衲一肩神百倍。","到时好向故人言，知我愁心满沧海。"]},{"t":"高丽纸行","f":"古风","c":["古之朝鲜今高丽，流风犹是箕子遗。","范畴邈矣彝伦斁，天下车书空尔为。","我闻先辈曾出使，品服黄门有殊赐。","鸭绿江浮使客船，凤皇衔出天书字。","夷君稽颡献丹诚，国相称诗扬盛事。","我曾见此诗，联绵纷可异。","诗法初唐体，字得颜公意。","勿言彼地遂无人，所学堪为中国臣。","石渠虎观诚深邃，河北胶东那等伦。","此纸为笺空五色，此纸卖文能几缗。","我愧当年青琐客，沧洲閒洒墨花春。"]},{"t":"游海目山醉后怀区海目先生","f":"古风","c":["西江汇流南海潴，我家海曲甘樵渔。","四月五月荡轻桨，言游海目尝鲥鱼。","海目双峰临丙穴，江心万族归圆折。","漫投犗饵钓吞舟，且奏鸾刀沃飞雪。","君不见浮山来与罗山同，中有铁桥仙路通。","兹山亦足晞华发，行当驻颜却老明方瞳。","君不见九子山加九华号，青莲居士心所好。","海目区公擅此山，岂有才士香名人不道。","劝君高歌快意游，眼前富贵水东流。","愁来白发三千丈，醉上丹梯十二楼。"]},{"t":"崇祯皇帝御琴歌","f":"楚辞体","c":["夏后峄阳桐不贡，周王岐山久无凤。","凤去桐枯未足愁，哀弦万古堪悲恸。","悲恸兮如何，先皇琴兮小臣歌。","小臣生在南边鄙，身比爨桐心不死。","莫提长剑定三关，聊抱孤琴游万里。","瞻孝陵兮聆高庙之景钟，望煤山兮泣烈皇之遗弓。","吊金戈于漠北，翻碧简于山东。","山东济南李家名，家藏百琴倾百城。","百琴一一囊且匣，出匣开囊一琴使人惊。","钟山玉晖九寡珥，古来稀有此光晶。","腹中䥴文翔凤名，龙唇凤沼文相生。","曾经烈皇亲手抚，真龙手中翔凤舞。","甲申三月便殿中，七弦自断琴心苦。","八音遏密兆此时，四海伤心惜明主。","呜呼烈皇御极十七载，祖宗全盛金瓯在。","外图政教务严明，内览诗书备文采。","上有君兮下无臣，宫弦张兮商弦改。","闻有能琴杨太常，烈皇礼之如师襄。","承恩别有一琴赐，得与翔凤相回翔。","一自烈皇登遐去，太常抱琴山泽藏。","终身感恩成乐章，恭贮赐琴居草堂。","虞帝薰风寂蒲阪，皇英瑶瑟怨潇湘。","天下臣民如寡鹄，长卿莫奏凤求凰。","神京既不守，宝器将何依。","弦歌邹鲁近，毋乃凤凰飞。","将军披铁铠，文士拂金徽。","共苦兵戈际，谁知律吕微。","烈皇安兮琴肃肃，臣不及钧天侍宴调丝竹。","烈皇怒兮琴轰轰，臣愿得挥云拨雾扬天声。","但愿见舞阶格苗之干羽，不羡彼登楼下凤之瑶笙。","臣拜御琴长加额，归告当年碎琴客。","安得普天知此音，中和乐奏无兵革。"]},{"t":"答俗人","f":"楚辞体","c":["天苍地莽，飘然一客。","虎变龙文，鸿荒自辟。","南郭天籁，东方星谪。","鱼可钓兮为任，雀可罗兮似翟。","碎京市之胡琴，语寒山之片石。","抗往古兮论生平，君不可兮知姓名。","四百峰头春色在，荷锄独往种瑶英。"]},{"t":"赠池阳陈君","f":"古风","c":["莫求冀北马，当采江南蘋。","客来就我赤花浦，举杯先道池阳人。","池阳人客珠江久，与我同为太丘后。","十年故国满干戈，四海移家择林薮。","南武台边愿卜居，昭明楼远频回首。","丈夫慷慨辞里闾，斗大黄金当系肘。","轻裘每忆镇襄阳，剑气还看起豫章。","弯弓近抱嵩台月，击楫遥冲瀚海霜。","世间乌白马生角，书剑平生果谁学。","五十归来鬓未皤，饮醇御妇聊行乐。","排难惟思鲁仲连，诙谐颇效东方朔。","唾壶击碎金屡挥，堪笑时人皆龌龊。","我昔轻肥好浪游，黄金满腰花满头。","胸中不染似皎月，调笑往往酣青楼。","夫君此时便相识，坎壈只今同失职。","嗔目语难非我心，高山流水和雕琴。","骐骥絷足鸾凤窜，北禽日日欺南禽。","相期惟有幽兰谷，袅袅轻风吹素襟。"]},{"t":"赠表兄冯茂","f":"古风","c":["与君为兄弟，异姓复连枝。","君是大冯君，生于吾有妫。","虞帝南巡下韶石，南天家世斯辉赫。","言陪八伯共赓歌，向尔商瞿先学易。","学易精思还草玄，赋成吾欲献甘泉。","甘泉烽火来万里，俄看荆棘上参天。","晓漏滴残鳷鹊观，悲风吹断鹡鸰篇。","鹡鸰歌急孤鸾窜，可怜亲友皆星散。","伍胥祇合避芦中，宁戚惟知愁夜半。","故旧沦亡有几存，中表行中君最尊。","甘为贫士终逃禄，曾列诸生亦受恩。","伤心思过乌衣巷，遁迹难营白板门。","君年七十荣期似，犹待华封祝男子。","自言御妇比容成，莫是安储有园绮。","忆昔风流邝舍人，雕龙绣虎夐无伦。","世人妒才皆欲杀，君与相欢儿女亲。","广陵遗散成绝调，山阳闻笛重沾巾。","端阳怨切灵均赋，酌酒同吟舍人句。","君持竹杖且须停，云过西山雨如注。"]},{"t":"屈道人歌","f":"古风","c":["云中龙，变化隐隐见其鳞。","支公与林师，髣髴云一人。","方袍白足采兰蕙，僧伽未必非灵均。","屈上人，天下士。","杂佩芳菲吾与尔，远游高举今在此。","只今吾见化鹤归来之苏耽，谁解昨日出关犹龙之老子。"]},{"t":"二子歌","f":"七言律诗","c":["皖城方子栖庐山，番禺屈子辽东还。","裁书寄去客复到，道气往来天地间。","此时天地烟茫茫，一鹤低迷双鹤翔。","会须共集三珠树，莫惜参差道路长。"]},{"t":"五羊门","f":"古风","c":["船维五羊驿，车发五羊门。","曾建双龙阙，何来万马屯。","五羊原是仙来处，自从羊去仙亦去。","仙人遨游朝玉京，几时重到五羊城。"]},{"t":"沉香浦送澹归上人兼寄元孝金吾","f":"古风","c":["舴艋载孤客，一湾复一湾。","沿洄欲指沉香浦，轻桡声入水潺湲。","短蓑破笠伴枯槁，山眉相顾明烟鬟。","长风万里成夙往，鸥飞凫浴洲渚间。","依稀三见东海浅，巀嶭忽对蓬莱山。","秦王此境何曾至，驺衍能知九州事。","虞舜原为天下君，至今偏有神仙意。","苍梧云影明复微，潇湘竹泪沾人衣。","九成台圮狐狸卧，瑶瑟龙吟水中破。","禺阳二子笛声残，朱明梅花吹古寒。","南武销沉南汉绝，苍苔满道谁呼鸾。","君不见素馨田近城西社，素馨花气薰游冶。","素馨墓上牛羊来，当日人前面空赭。","仆本豪华澹荡人，奇情逸思超无垠。","鲲鱼本化北溟水，那知蹭蹬桃源津。","十年九迁无定止，一生万事随流水。","海畔还逢逐臭夫，污尘何处堪湔洗。","曹溪分流香且甘，故人往结松间庵。","此水直待夷齐饮，从他取尽石门贪。","扁舟笑彼陶朱富，携童入海期老寿。","我不能同五百人一死从田横，会当直入四百峰师事安期生。","向人贷粟不得饱，餐芝自可呼龙耕。","五岳遥遥未遽蹑，行行请避西山猎。","同心不见当奈何，今夜相思浮一叶。"]},{"t":"四咏 其一 循东陵","f":"楚辞体","c":["循东陵兮怀故侯，圃秋瓜兮农之俦，我今安知嬴与刘。","夫君资我端章甫，文身断发将焉取。","不如蝉蜕圭与组，身齐逸民此终古。"]},{"t":"四咏 其二 望西山","f":"楚辞体","c":["望西山兮钦义士，采薇食兮饿而死，我向颍滨犹洗耳。","夫君贻我辟谷丹，吞腥啄腐登仙难。","不如观化栖岩峦，强持一杯且为欢。"]},{"t":"四咏 其三 眷南郭","f":"楚辞体","c":["眷南郭兮希达人，阐三籁兮闻天真，我昔此居称里仁。","夫君助我云连宅，燕泥忽混狐狸迹。","不如瓮牖门悬席，天地蘧庐况为客。"]},{"t":"四咏 其四 吟北门","f":"楚辞体","c":["吟北门兮伤贤者，室人谪兮不我假，我有忧心不能写。","夫君赠我飞蚨钱，金珠奈此糟糠贤。","不如敝屣却床前，商歌高入沧浪天。"]},{"t":"罗浮胡蝶歌送屈翁山之金陵同梁芝五陈元孝席上赋","f":"七言古诗","c":["胡蝶来从胡蝶洞，南园先集罗浮凤。","凤衰久作接舆歌，昨夜蝶酣庄叟梦。","东家西家胡蝶飞，蝶黄蝶白争春晖。","罗浮大蝶真凤子，暂憩华堂还翠微。","屈生却自翠微出，欲走名都怀道术。","卜居未忍便沈湘，修辞莫是身曾漆。","藻思如餐婀娜花，翱翔远食琅玕实。","神仙之侣不可羁，还待怜才重惜之。","文章被服人尚爱，况乃吐纳生神奇。","送君凤皇台畔去，去去逍遥君自知。"]},{"t":"醉中吟寄内","f":"七言律诗","c":["江城飞雨烟濛濛，主人劝我杯酒浓。","绿槐雨滴白鹇饮，蜜酒藤床醉即寝。","山妻生日身在城，白头相重千金轻。","醉中笑看侏儒饱，犹有东方割炙情。"]},{"t":"飞奴行","f":"古风","c":["青天迷白雁，沧海潜鲤鱼。","鱼雁不堪使，使鸽飞飞行作奴。","飞奴何事事寄书，山盘水曲云路长。","相思不见愁参商，吾不能如比翼共翱翔。","飞奴飞奴使尔腾空觅路冲苍茫，征云片片晴景光。","鸟坠高枝影入塘，雕鹗屏迹鹰鹯藏。","系铃播远声如璜，千里不聚三月粮，为君缄情致八行。","岂免阴霾昏复黑，金眸独辨遥林色。","高愁鸷搏低愁弋，得归始见辛勤力。","飞奴飞奴凤则尔之主，何必能言似鹦鹉。","且歌作书与鲂鱮，周公鸱鸮，迨未阴雨。","曲江海燕，谢彼林甫，吾闻飞奴之名曲江取。","去国难忘求友生，山川间绝离情苦。","古今同一时，千里如一家。","封书达庾岭，折赠空梅花。","飞奴飞奴，吾将使尔行不由径，目不视邪，然后寄声东父游紫霞。"]},{"t":"以诗代书呈诸公","f":"七言古诗","c":["我生澹荡本无忧，生产萧然无所求。","楚楚摊书独南阮，栖栖环辙或东丘。","床无阿堵何劳撤，路有明珠怯暗投。","同异仅存黄马论，纵横敝尽黑貂裘。","几回变态翻云鸟，只自忘机对海鸥。","岂知世事争排击，水静偏逢乱石激。","当年倾意尽江河，谁是衔恩见涓滴。","一饭今惟感漂母，百金可怪谋洴澼。","蟊贼伤苗越陌阡，射工伺影含砂砾。","莫是豪强归阘茸，奈何贫贱招仇敌。","士龙父祖人所知，司马文章空尔为。","意气必须天下士，风波翻自里中儿。","愿同知己谈深浅，不厌旁人说盛衰。","傥逢晏子鞭堪执，欲绣平原难买丝。","休言伏枥年将暮，剪拂长鸣是此时。"]},{"t":"青霞子歌为郭生赋兼简刘焕之阿字澹归二上人","f":"古风","c":["青霞子，昔住丹霞山。","壮岁从师客南越，家乡回首古秦关。","自言十六十七时，脩真炼气寻希夷。","静中虚室能生白，坐使元阳含早晖。","参同契中颇紬绎，未叩羲文穷大易。","丹霞跽请郁先生，三绝韦编观未画。","要妙全窥太极图，绪言发挥二篇策。","侍立匡床师返真，彷徨浊世求三益。","旧友黄门久出家，亦持锡杖开丹霞。","霞光照仙还现佛，并至珠江烟水涯。","我向珠江得居止，主人意气云霄似。","出身戎马心大儒，鞅掌勤劳归性理。","閒邀禅客恣高谈，排关忽见青霞子。","座中复有阿首座，舌长放出雷声大。","一时四子三教同，惟我赘疣添一个。","青霞子，丹霞僧，多谢主人能得朋。","未可轻传讲德论，恐令闻者如苍蝇。"]},{"t":"南海神祠古木棉花歌","f":"古风","c":["祝融煮海不得乾，烛龙腾波金蜡寒。","红旗捲日鏖水战，向天欲插珊瑚竿。","海若森森坐鳞屋，天池一勺?灵木。","青帝行春辇且停，望洋却倚扶桑旭。","岢峨艚舶千万樯，赤文羽葆邀团光。","请搥铜鼓劝花发，吾神饮酒吾人悦。"]},{"t":"赠沈耕岩徵君","f":"七言古诗","c":["前者渊明后者潜，眉生老矣称耕岩。","今人追古如一辙，高名应向陵阳镵。","陵阳之峰连敬亭，即今文脊栖瞿硎。","宣城纵有玄晖守，那得徵君出户庭。","我从庐岳趋黄山，避暑吴淞秋始还。","江楼远望不及往，宛然斯人苍翠间。","共是山林江海士，寄书合倩琴高鲤。","告君旧事君应喜，乞君书满泾县纸。"]},{"t":"露筋庙","f":"七言古诗","c":["蚊为海水人为鱼，人沈蚊海啄团肤。","呜呼高邮蚊毒粗，露筋女子诚丈夫。","毒物杀人无贤愚，烈女岂为高邮有。","此毒未必天下无，蚊何易生人易枯，古今几多露筋徒。"]},{"t":"舣松江","f":"七言律诗","c":["十日兰桡抛草屩，违山又向松江泊。","未归犹觅四鳃鱼，长往须骑丹顶鹤。","吴月渐明风渐殷，江边一线是吴山。","不信天池飞翼畔，高吟朗朗下云间。"]},{"t":"吴歌可听行","f":"古风","c":["生平解吴语，客里爱吴歌。","吴江江水流无歇，歌起吴江君奈何。","浪船摇摇天向晓，枕上诗成思未了。","忽然听得声满江，声声揭出江云表。","畴昔听歌歌必昆，座中顾曲惊梨园。","老年放浪吴江下，鼓枻惟寻渔父言。","君不见百万黄金争度曲，酒阑人散抛丝竹。","江头谁解听吴歌，信口清音断还续。"]},{"t":"鹤舒台","f":"五言律诗","c":["安期干楚罢，跨鹤弃人间。","卖药已前代，遗祠空此山。","枯枝蝉自蜕，晴海客偕还。","不向金丹学，劳劳玄鬓斑。"]},{"t":"曲江怀张文献","f":"五言律诗","c":["金鉴丹诚尽，玉堂风度开。","南天相初入，西蜀眷空来。","独预防胡计，无伤咏燕才。","谁怜桑梓共，吟破岭头梅。"]},{"t":"西江春事","f":"五言律诗","c":["桃花水上新，况复满山春。","历乱闻啼鸟，清明烂醉人。","相思阻天末，相慰且比邻。","借问求桑女，如何大路遵。"]},{"t":"玩月山池","f":"五言律诗","c":["雨霁山池晚，悠然逢月明。","山中如此色，天上有无情。","雾碎安期石，风微子晋笙。","犹闻小桥畔，农父话春耕。"]},{"t":"苍梧访绿珠太真遗迹","f":"五言律诗","c":["湘波流媚远，鱼媵正愁人。","金谷何年入，华清几处春。","环为天上宝，珠是掌中珍。","聊持堕楼思，并起马嵬尘。"]},{"t":"昌华苑","f":"五言律诗","c":["南汉风流地，芳湖曲带潮。","芙蓉依殿脚，杨柳近宫腰。","一往多疑冢，千年不复朝。","空馀化萤草，羃历彩虹桥。"]},{"t":"游峡山","f":"五言律诗","c":["轩辕二帝子，弄笛开禺阳。","江岸扁舟客，闻钟到上方。","仙灵今阒寂，云水空青苍。","欲遣愁心去，猿声岭外长。"]},{"t":"西樵大科峰","f":"五言律诗","c":["樵峰七十二，秀出一峰尊。","策杖观朝日，浮澜动海门。","孤松生鸟外，片雨落山根。","吾欲骖鸾去，凭虚望帝阍。"]},{"t":"碧玉洞作","f":"五言律诗","c":["我有碧玉调，匣琴无处弹。","登山见流水，高调和皆难。","壁立一片雪，风含白云端。","羽人不可见，环佩日珊珊。"]},{"t":"秋江夜汎","f":"五言律诗","c":["秋光枫叶动，星转客帆孤。","况复秋水至，安知秋夜徂。","牛渚袁宏月，鸱夷范蠡湖。","裴褢无所似，空作水中凫。"]},{"t":"江上怀所钦","f":"五言律诗","c":["六月三江水，扁舟独客思。","何劳远天色，不共小窗时。","一枕清波听，谁家玉笛吹。","心藏山木咏，摇漾与君知。"]},{"t":"咏陈思王","f":"五言律诗","c":["大雅黄初见，词林此凤麟。","游园邺城客，入梦雒川神。","竹帛思垂绩，旗章漫宠亲。","相知零落早，论定属何人。"]},{"t":"伏波祠","f":"五言律诗","c":["遥遥汉交阯，初识汉将军。","偶尔明珠谤，繇来铜柱勋。","春江激怪石，夏木栖寒云。","世鲜爰生笛，劳歌如可闻。"]},{"t":"寄陈仲因","f":"五言律诗","c":["秋气忽不解，起歌还侧身。","远思西湖水，高映胥山人。","飞雀少年剑，钓鱼公子纶。","浙潮今正好，急送梅花春。"]},{"t":"秋怀 其一","f":"五言律诗","c":["山山木叶脱，一为洞庭波。","今年春草碧，今日伤如何。","四愁看雪早，七发属涛多。","宋玉元生楚，秋如羁旅过。"]},{"t":"秋怀 其二","f":"五言律诗","c":["杀气到金天，狼星见几年。","贤良诏骑射，经史傍貂蝉。","榆荚连关暗，花名渡海偏。","仍闻来陆贾，应有逐居延。"]},{"t":"秋怀 其三","f":"五言律诗","c":["碧沚渺秋思，飘鸾淡雾姿。","明珰一以献，玉佩解要之。","子夜芙蓉曲，秋风兰菊辞。","却看银汉侧，牛女别经时。"]},{"t":"望孔林奉和瞿稼轩先生","f":"五言律诗","c":["尝游先圣地，嘉木蔼成林。","今日宗周老，遥同望鲁心。","麟来青草合，凤去碧梧阴。","想见宫墙色，谁聆丝竹音。"]},{"t":"东皋观刈稻同诸从兄","f":"五言律诗","c":["出刈东皋稻，来同南阮人。","香吹三伏日，欢洽八家邻。","野俎堆蔬甲，深杯注粟唇。","清风万石在，蠲恤诏方新。"]},{"t":"薄醉入山","f":"五言律诗","c":["尚有一樽酒，山楼复数杯。","暝风送酣影，明月正裴褢。","七不堪都释，一相思辄来。","回溪值清浅，观海必澜哉。"]},{"t":"流杯池赠陆岫青明府","f":"五言律诗","c":["朱明山下水，一见陆郎心。","仙醴玉壶挈，芳春赭白寻。","积砂应作灶，通涧亦鸣琴。","笑我留兹土，何须白石吟。"]},{"t":"送曹彝伯还太仓","f":"五言律诗","c":["綵艇餐红荔，明楼宿白云。","如何方缱绻，天际忽离群。","甲帐长途匝，牙香夹被熏。","会吹吴地月，佳气一氤氲。"]},{"t":"赠歌客","f":"五言律诗","c":["谁能为此曲，毋乃古绵驹。","今夜尉城月，攒风江笛纡。","宋人有章甫，越地亦吴歈。","知尔丹山凤，高歌闻众雏。"]},{"t":"七夕珠江汎舟同豫章黎左严陈元者同里黄逢永黄季恒黎美周席上有赠","f":"五言律诗","c":["珠江指银汉，相见复相亲。","往岁悲秋客，都为乞巧人。","南流豫章水，或有雒川神。","深夜星前酌，依依溪上蘋。"]},{"t":"吴楚行","f":"五言律诗","c":["神女惊临楚，西施粲入吴。","朝云蒙泽芷，秋露坠宫梧。","狐媚疑詹策，龙文失属镂。","年年兴楚些，日日变吴歈。"]},{"t":"何印尼太常招同刘安世司马陈忝生宫谕雨集分得来字","f":"五言律诗","c":["江楼散凉雨，溶㵝入深杯。","坐久月光动，歌停花气来。","勋名惊下濑，词赋笑阳台。","辛苦天南事，长安道更催。"]},{"t":"走笔询家兄山中潴水复满几尺","f":"五言律诗","c":["不厌山中水，冬寒更几深。","激流康乐咏，魏阙子牟心。","牛马虚遥涘，鸳鸯下众禽。","乘车堪借问，渔父有拿音。"]},{"t":"夜度大舰口","f":"五言律诗","c":["水涘还牛马，悠然已望洋。","味盐真泽国，穷海讵荒唐。","梦减五更鼓，行馀三月粮。","罗浮看浴日，无树即扶桑。"]},{"t":"何仙姑祠","f":"五言律诗","c":["云母凝清甃，仙姑渺碧空。","佩声遗凤穴，绡影借鲛宫。","纷若神弦曲，泠然少女风。","守雌长若此，无处问鸿濛。"]},{"t":"寓潮戏集海味成律","f":"五言律诗","c":["海青窥瓦屋，沙白露为霜。","玉赘长须国，珠联牡蛎房。","月姑能不字，螺女亦名香。","何必遵伊洛，方知贵鲤鲂。"]},{"t":"客游怀黎美周梁渐子","f":"五言律诗","c":["漫游消失意，诸子复如何。","闭户壁书满，伤时文选多。","长楸走马引，白石饭牛歌。","近世临川剧，寒烟吊尉佗。"]},{"t":"赋得鸣琴赠张公亮明府","f":"五言律诗","c":["朗朗琴张子，鸣琴揭岭间。","南徐下流水，北固旧高山。","听讼依桐响，怀仙与鹤閒。","惟怜一绿绮，掩抑独无颜。"]},{"t":"月夜迟朱王孙不至","f":"五言律诗","c":["临风孤玉树，明月七星台。","清夜一何永，碧云殊未来。","虚空忘障闼，图画入莓苔。","一室皆如水，将予漫溯洄。"]},{"t":"梅花","f":"五言律诗","c":["彼美矜寒夜，菲菲皎月痕。","篴中吹有色，关外寄何言。","抗手期瑶草，高情命绿尊。","方知倾盖地，已见白头恩。"]},{"t":"牛","f":"五言律诗","c":["呼名原一我，占梦即三公。","紫气伯阳至，黄姑七夕中。","有人曾化虎，见月异屏风。","刺促因鞦鞅，长谣阁道东。"]},{"t":"有感","f":"五言律诗","c":["时事纷回薄，悲秋且禦寒。","累累看客印，岌岌爱予冠。","国是谈何易，韩非说实难。","踌躇中夜起，不耐斗阑干。"]},{"t":"南侍御谪藩幕至粤赋赠","f":"五言律诗","c":["参军天子命，谪宦越王城。","幕下皆言屈，朝端有直声。","霏微刘苑月，寥落楚江蘅。","早入陈时事，南中未息兵。"]},{"t":"箧中存张天如吉士所遗诗扇次韵哭之","f":"五言律诗","c":["道术期经世，文章真史官。","夫君斯已矣，挥扇涕阑干。","垂诏王心恻，遗言友道看。","朝华披可恨，谁起楚臣餐。"]},{"t":"忆银尖","f":"五言律诗","c":["忽忆银尖好，相悬玉塞春。","服劳常出众，未老别随人。","水涨权奇渺，天空剪拂新。","莫令街市上，鹰犬逐浮尘。"]},{"t":"龙川","f":"五言律诗","c":["漠漠龙川水，轻舠溯浅滩。","欲于风气得，已作霸图看。","花蔓零魋结，莺巢暖汉官。","斑骓自骄蹇，客子动征鞍。"]},{"t":"自大埔度上杭","f":"五言律诗","c":["八闽初入路，鸟语信钩辀。","如马填江石，升猱逆水舟。","天鸡虚倦客，野老习通侯。","南北京何似，须成万里游。"]},{"t":"苍梧扈驾谒兴陵","f":"五言律诗","c":["旧邸瞻神庙，前旌指孝陵。","松坛开虎拜，桂海溯龙兴。","羽卫千官导，戎衣列圣凭。","他时天子孝，文在泰山登。"]},{"t":"奉和瞿相公劳师全州见道上古松之作","f":"五言律诗","c":["不掩将军树，言开召伯棠。","苍梧生大道，偃盖复成行。","积甲龙鳞见，投醪琥珀香。","军心欢不已，声共舞风长。"]},{"t":"留别刘及叔兵部","f":"五言律诗","c":["刘生为我别，何以写衔杯。","一曲东平意，相如西蜀才。","蒯缑悬锦水，花笔掩兰台。","但断忧时泪，吟诗瘦莫哀。"]},{"t":"夜度梅林","f":"五言律诗","c":["即不疲行役，何方作逸民。","风林摇入暮，沙水咽迷津。","远灶翻刍狗，低篷仰杞人。","江边如秃节，可共雁来宾。"]},{"t":"题朱子洁小舫","f":"五言律诗","c":["五湖何处去，一叶且经营。","犹可汎溪月，将子同濯缨。","兰幽期绝迹，豆落怅归耕。","倚棹或堪近，桃花鸡犬声。"]},{"t":"赋得云中辨江树","f":"五言律诗","c":["已极扶桑影，微依委杖林。","因波闻脱叶，傥别即伤心。","牛马虚秋水，猿猴隔楚吟。","安知如荠外，不是八公寻。"]},{"t":"述哀 其一","f":"五言律诗","c":["心摧娲后石，泪尽蜀山鹃。","自恨无容地，谁还共戴天。","飞尘金齿路，沈日点苍烟。","愿挽乌号射，欃枪会应弦。"]},{"t":"述哀 其二","f":"五言律诗","c":["黄竹歌残雪，苍梧泣断云。","三年曾克鬼，诸□乃无□。","逐日还何及，呼天竟不闻。","定知图箓秘，哀痛为斯文。"]},{"t":"述哀 其三","f":"五言律诗","c":["列圣恒如在，孤臣尚苟生。","生年从万历，往恨积崇祯。","流落捐躯免，传闻洗耳惊。","将来纪年月，良史正含情。"]},{"t":"述哀 其四","f":"五言律诗","c":["云沈六诏外，天远七盘西。","不义为彭宠，休屠无日磾。","难期大树赏，空使具茨迷。","他日还钟簴，如何慰鼓鼙。"]},{"t":"村社饷予酒肉","f":"五言律诗","c":["古树小桥幽，江村赛社秋。","恒饥双稚喜，多病一杯酬。","底事周人栗，贫时曲逆侯。","摐金人语歇，天外暮云流。"]},{"t":"赋得花丛乱数蝶","f":"五言律诗","c":["梅花与李花，相趁复相加。","大都多粉色，子细认东家。","绿窗春有梦，雕槛昼无哗。","不堪垂手伎，烂漫舞茵斜。"]},{"t":"赋得风帘入双燕","f":"五言律诗","c":["芳春荡晓风，双燕向帘栊。","尔是新还旧，谁知雌与雄。","振襟钩自上，拂尾剪俱空。","似恨歌尘寂，金塘泥正融。"]},{"t":"送人之牂牁","f":"五言律诗","c":["居人殊郁郁，送尔客何方。","白露将秋色，青莲愁夜郎。","沙分胡雁小，天合楚云长。","为问牂牁水，楼船何渺茫。"]},{"t":"赠景公峻兼讯陆参军骏如","f":"五言律诗","c":["风月羁离际，论交二十年。","吹箫还入市，取醉不忧天。","鹿閟苏台迹，羊孤海峤仙。","芙蓉峰四百，持照幕中莲。"]},{"t":"招旧游","f":"五言律诗","c":["游情向春鸟，鸟语在庭柯。","我罢归欤叹，谁为劳者歌。","青春将进酒，白日倩挥戈。","何不还携手，高高藏绿萝。"]},{"t":"巫山之阳香溪之阴明妃神女旧迹存焉 其一","f":"五言律诗","c":["碧峰连枕席，青冢隔烟萝。","汉道寖微矣，荆王如梦何。","遥知云色寡，夕想雨容多。","欢怨皆芜没，回肠发浩歌。"]},{"t":"巫山之阳香溪之阴明妃神女旧迹存焉 其二","f":"五言律诗","c":["阏氏留汉月，芳草藉巫云。","清怨独和胡，微辞因奉君。","溪萦香缥缈，台驻梦氤氲。","不蹑风流迹，荒山空旧闻。"]},{"t":"巫山之阳香溪之阴明妃神女旧迹存焉 其三","f":"五言律诗","c":["楚汉风流事，千年迹并稀。","巫云象神女，塞月照明妃。","余欲登高赋，征人怨不归。","清秋如有梦，应逐朔鸿飞。"]},{"t":"艳诗","f":"五言律诗","c":["南林苏合弹，西堰木兰舟。","藻动文鱼戏，花飞艳妇愁。","遥闻轻薄子，新拜富平侯。","树背无萱草，飞蓬两鬓秋。"]},{"t":"雨中即事简在城亲旧","f":"五言律诗","c":["细雨滋何限，浮生澹不营。","碧苞防露笋，红吐拒霜英。","鹤发来扶杖，渔歌迥濯缨。","轩车任流水，书此报寒城。"]},{"t":"石门吴刺史祠","f":"五言律诗","c":["石门之水清，刺史昔年情。","日照龙骧节，风高雁翅城。","江河遮贝阙，俎豆出芹羹。","极浦香沈尽，西山薇欲生。"]},{"t":"展观朱仲韶所画梅花作诗寄怀","f":"五言律诗","c":["梅花开棐案，岭路未曾知。","偏是南州士，孤芳劳我思。","青山无半亩，白眼亦多时。","君解轩辕历，崆峒何处期。"]},{"t":"寄徐巨海","f":"五言律诗","c":["南州徐孺子，高卧有青山。","往日蒲轮弊，穷年桂树攀。","溟鱼不得运，雾豹迥无斑。","却望罗浮色，知予亦闭关。"]},{"t":"寄陈元水","f":"五言律诗","c":["吴王苑边客，憔悴豫章江。","伊昔宰百里，踌躇之一邦。","新篇寄金错，旧恨剪兰釭。","赭白吾将尔，骄时各自降。"]},{"t":"寄蒋南陔先生","f":"五言律诗","c":["南海神明宰，归吴赋五噫。","内廷虽一召，末路叹多歧。","小子亦鸿渐，终焉同凤衰。","因声寄丹穴，雏羽日威仪。"]},{"t":"寄徐子能","f":"五言律诗","c":["美人家何处，百尺姑苏台。","麋鹿游今日，龙威书几开。","迷离天末客，放浪湖上杯。","遥知二毛落，秋兴倍从来。"]},{"t":"游中宿望西樵怀家园所钦","f":"五言律诗","c":["出户辞容膝，征途重久要。","吟空峡猿夜，梦变楚云朝。","中宿将三宿，西樵非两樵。","沿江新柳色，回首见攀条。"]},{"t":"灌园","f":"五言律诗","c":["磬折君勿嗤，为园勤注兹。","民生不匮事，草木向荣时。","子月馀清浅，仙源动碧滋。","淮南洵汲井，鍊药更何为。"]},{"t":"雨中弹琴作","f":"五言律诗","c":["飞雨洒檐轻，轻弦逗雨鸣。","器泠因得法，心语欲无声。","水泛中郎弄，风将列子行。","徐收玳瑁匣，还见峄峰晴。"]},{"t":"岁暮过海幢寺谒空隐禅师寄薛二","f":"五言律诗","c":["渡江寻净域，了自不关人。","息影入中岁，生烟开早春。","启扉无一语，踧踖愁书绅。","归对同门友，溪风萌绿萍。"]},{"t":"寄一灵上人","f":"五言律诗","c":["中洲千嶂月，何处一龛灯。","独坐旷无侣，高吟遥对僧。","别来云共水，空外谷为陵。","待发秋江棹，松门最上层。"]},{"t":"卜筑","f":"五言律诗","c":["九江村色明，三径欲经营。","最喜池塘遍，圆波连月生。","此中有桑竹，无以异蓬瀛。","谁信扶摇翼，而甘择木情。"]},{"t":"江村","f":"五言律诗","c":["昔游九江郡，今寄九江村。","禹迹复何处，佗城非故园。","乡关生死泪，亲旧岁时论。","那得深山入，西风吹暮猿。"]},{"t":"题乡事寄静者","f":"五言律诗","c":["俗尚吾何羡，乡情君莫嘲。","鱼花千里舸，鸡菜万家庖。","竞渡黄头出，柔桑皓腕交。","惟馀读书客，高卧静衡茅。"]},{"t":"山寺听蝉","f":"五言律诗","c":["偶同高士出，一路听蝉嘶。","雅尚宜秋露，何心怜夏畦。","晚风清梵外，茂树翠微西。","复此令人远，依依飞鸟栖。"]},{"t":"奉题欧先生南圃","f":"五言律诗","c":["南圃人安节，东篱菊吐英。","苍凉开画色，閒暇读书声。","远水浮秦树，斜阳澹汉城。","所欣吟月下，一傍古松行。"]},{"t":"题朱子茂茅亭新成","f":"五言律诗","c":["中表过从好，巢居又一枝。","金鳞云锦烂，玉树月华披。","坐即频呼酒，行应为采芝。","不逢尧与舜，安敢望茅茨。"]},{"t":"濠上逢旧妓","f":"五言律诗","c":["骄马几时迎，桃根艳柳营。","半生重入梦，两度总倾城。","日澹青楼色，笳悲子夜声。","藁砧何可道，山上若为情。"]},{"t":"大历琴","f":"五言律诗","c":["端居珍所尚，三叹少知音。","不遇丁年友，那称大历琴。","徽明千古月，匣向万山岑。","最是同閒止，商歌入旧林。"]},{"t":"家无长物琴砚特佳聊为之咏","f":"五言律诗","c":["紫云鸲鹆砚，绿绮凤凰琴。","静者亦何有，兹焉朋盍簪。","诗书敦宿好，山水有清音。","欲解无弦趣，惟操匪石心。"]},{"t":"城中寄怀某郎","f":"五言律诗","c":["想子中洲夜，月斜春帐深。","新蛙乱欹枕，起坐空横琴。","予实同栖鸟，飞翔惟近林。","春潮日来往，因信平生心。"]},{"t":"英石砚山","f":"五言律诗","c":["英州小小石，宛似文君眉。","一抹不加画，千峰何处移。","白云侵半岭，清海或环之。","紫砚琉璃匣，缘情赠汝诗。"]},{"t":"朱子勷赠予墨拓瘗鹤铭喜赋","f":"五言律诗","c":["何代华阳逸，遗音瘗鹤铭。","胎禽漠然化，腕兔若为灵。","势挟云螭驾，图分山海经。","羽仙将墨客，无不掞天庭。"]},{"t":"赠陶大","f":"五言律诗","c":["君家原五柳，知不重千金。","结客非游宦，移居为入林。","天风双袖阔，花雨一帘深。","长向东方倩，高歌度陆沈。"]},{"t":"寄旧游二三诸公","f":"五言律诗","c":["岁晏沧江雨，空濛一望君。","校书犹马队，临帖几鹅群。","白雪从歌聚，青帘引袂分。","王通归老处，知是恋河汾。"]},{"t":"舟夜闻雁","f":"五言律诗","c":["春雁不宿渚，夜飞鸣向舟。","三江惊始旦，二月重南游。","且复韬羽翼，谁能忘匹俦。","溯洄将倩尔，明发见中洲。"]},{"t":"用乐府题作唐体十二首 其一 有所思","f":"五言律诗","c":["贱妾对流萤，良人备北庭。","金闺淹日月，沙碛动风霆。","去梦萦蛛网，归书暗雁翎。","君恩治第否，天末不遑宁。"]},{"t":"用乐府题作唐体十二首 其二 关山月","f":"五言律诗","c":["边月散边霜，长城月正长。","狼烟虚远色，驿火断寒光。","北照惟依斗，南临一望乡。","营门钲鼓静，昨夜遁贤王。"]},{"t":"用乐府题作唐体十二首 其三 紫骝马","f":"五言律诗","c":["国事勤玄塞，将军跃紫骝。","都门一发迹，千里去悠悠。","大漠风多逆，长城水不流。","功成何用赏，骨立视封侯。"]},{"t":"用乐府题作唐体十二首 其四 刘生","f":"五言律诗","c":["卿家赤帝后，走马黄云间。","独入咸阳市，报雠时度关。","愁将边月远，卧对酒垆閒。","傲尽王公席，青春抚绿鬟。"]},{"t":"用乐府题作唐体十二首 其五 折杨柳","f":"五言律诗","c":["离情相送送，大道夹垂杨。","千里从兹远，一枝空折将。","结为腰带缓，吹与鬓丝长。","何必闻羌篴，方知断客肠。"]},{"t":"用乐府题作唐体十二首 其六 梅花落","f":"五言律诗","c":["陇右五歧路，梅花寒并飘。","春风上冰雪，人迹澹溪桥。","白破胡天晓，香分庾岭遥。","谁知金屋里，坐使玉容销。"]},{"t":"用乐府题作唐体十二首 其七 从军乐","f":"五言律诗","c":["南征忘苦辛，百万出咸秦。","破竹看崩角，分茅掩沸唇。","箭穿无石虎，车载有金人。","遂使光天下，皆称率土臣。"]},{"t":"用乐府题作唐体十二首 其八 明妃怨","f":"五言律诗","c":["物色归骄虏，蛾眉镇独颦。","迁延上马地，决绝贯鱼人。","觱篥风相切，琵琶语不真。","君王有飞将，妾是玉关尘。"]},{"t":"用乐府题作唐体十二首 其九 古意","f":"五言律诗","c":["玉匣鸣琴出，繇来是爨桐。","中含太古意，侧想先生风。","抚罢不成操，知音人已空。","滔滔流水去，悽绝对仙宫。"]},{"t":"用乐府题作唐体十二首 其十 难忘曲","f":"五言律诗","c":["花径入檀郎，君家不可忘。","交精飞过水，反舌唤登墙。","南国明珠佩，东家白玉床。","微躯何所托，端在婉清扬。"]},{"t":"用乐府题作唐体十二首 其十一 关陇吟","f":"五言律诗","c":["秦地双崤阻，周王八骏雄。","水流巴子国，山压隗嚣宫。","榆细森关月，梅春袅笛风。","寄言被褐者，相助守山东。"]},{"t":"用乐府题作唐体十二首 其十二 长安道","f":"五言律诗","c":["古树咸原色，繁华大道春。","长风与流水，翠粲复龙鳞。","狐白逢公子，鸦黄见美人。","萧条道旁客，叹息经情亲。"]},{"t":"上巳海目山禊饮 其一","f":"五言律诗","c":["羽觞何处流，飞渡羽人丘。","斗酒黄莺语，山枝青翰舟。","春丛烟雾气，波荡古今愁。","楚水长相接，言归芳杜洲。"]},{"t":"上巳海目山禊饮 其二","f":"五言律诗","c":["海目更长望，珠江云水连。","因仍京洛事，飘泊楚人船。","细雨滋平仲，春风愁杜鹃。","当杯酣上巳，何必问丁年。"]},{"t":"种柳","f":"五言律诗","c":["池水如明镜，杨枝是细腰。","宅边宜有此，花外不堪飘。","昔在长杨苑，因风拂灞桥。","桥西几攀折，今日抚柔条。"]},{"t":"无题 其一","f":"五言律诗","c":["桃李自成蹊，媻姗并上堤。","秦宫花底活，周史月边迷。","乐府能传凤，天河恨报鸡。","因君逢嫁娶，端是不须啼。"]},{"t":"无题 其二","f":"五言律诗","c":["不矜交甫佩，不羡莫愁堂。","死认罗浮树，生怜西国香。","老来将药却，忧至倩萱忘。","定有龟台使，馀桃泥汉皇。"]},{"t":"纸帐","f":"五言律诗","c":["素丝缝侧理，兹帐息深深。","一榻何高卧，洞房非此心。","云封虚白室，月在梅花林。","个里雕龙思，天孙无自寻。"]},{"t":"春日与薛刚生期于崔千上江馆崔子谷在焉因并留赠","f":"五言律诗","c":["门前杨柳色，日日向通津。","一水过春雨，三杯逢故人。","垆头卖浆至，座右勒铭新。","无使穷途泪，阑干缨上尘。"]},{"t":"乡中有井出泉甘冽好事者浚而识之邀予为咏","f":"五言律诗","c":["玉醴浮双井，金瓶洒八公。","会当行汲去，不是后园中。","改邑君莫问，枕流谁可同。","泠然饮仙液，云水思无穷。"]},{"t":"过朱未央","f":"五言律诗","c":["风流当日事，矍铄老翁心。","薄俗不相厚，古欢遑问今。","垂帘障野马，出郭听春禽。","始信朱公叔，门稀鹤盖阴。"]},{"t":"送元孝之楚","f":"五言律诗","c":["远游安可极，壹郁念平生。","背雒独愁坐，怀沙空此行。","疑山低晚黛，梦泽转寒旌。","今日黄钟毁，休高白雪声。"]},{"t":"楚云台","f":"五言律诗","c":["昔贤期友地，风义一何深。","云岂浮车盖，台非市骏金。","惟将素心合，不作白头吟。","吾与二三子，欣然共入林。"]},{"t":"葵扇","f":"五言律诗","c":["冈州剪玉葵，习习凉风吹。","自以白茅藉，何烦朱粉施。","蕺山逢逸少，阶草问班姬。","亦有倾阳意，秋来空尔为。"]},{"t":"口号赠故人","f":"五言律诗","c":["万里来又去，如君忠信稀。","将离一以赠，杨柳重依依。","余欲蹈东海，西山犹采薇。","应知六月息，风力使鹏飞。"]},{"t":"江涨雨甚浩然兴叹","f":"五言律诗","c":["白马涛方怒，苍梧云正流。","临渊叹今雨，向若况先秋。","独閟江上阁，谁归天际舟。","若为藏羽翼，深树拂鸣鸠。"]},{"t":"赋得江海寄情人","f":"五言律诗","c":["平生寥廓意，持此结情亲。","明月隔千里，沧洲同几人。","依依寒雁渚，淼淼落花津。","我独乘桴去，思君愁白蘋。"]},{"t":"何仙姑祠","f":"五言律诗","c":["才近仙灵宅，群山翠黛浮。","欲餐云母去，君与鲍姑游。","奏以湘江瑟，觞之蓬岛流。","空祠隔环佩，明到玉峰头。"]},{"t":"寄无可大师","f":"五言律诗","c":["平生皖城友，当世白莲师。","金策摇何处，碧云愁莫时。","月临无尽界，鸟择最高枝。","同病还同老，浮沈愧所知。"]},{"t":"人日送人之鲁郡赋得尧祠","f":"五言律诗","c":["一尊君但饮，策马指尧祠。","万古瞻如日，孤臣正到时。","春阶数蓂荚，故国见茅茨。","借问巢由事，今人那得知。"]},{"t":"元夕灯下怀所钦","f":"五言律诗","c":["情人旷颜色，空此九微灯。","今夕始三五，今年思旧朋。","愁听火凤唱，梦到烛龙升。","春雪如相映，山阴棹已乘。"]},{"t":"秋日赠别","f":"五言律诗","c":["荆棘参天满，君行思独深。","不穷驺衍口，至慎阮公心。","想到西荆日，登楼罢叹音。","风尘重相见，长袖拂霜镡。"]},{"t":"忆别","f":"五言律诗","c":["邑井观鱼处，新丰策蹇时。","阿咸挥麈尾，匡鼎解人颐。","荒径暌三益，临风怅别离。","何当同旅雁，过岳复相随。"]},{"t":"忆黎君选十一丈","f":"五言律诗","c":["畴昔黎夫子，居然晋代贤。","夜阑诗酒洽，人去笔精传。","胜事难回首，馀生渺比肩。","城南怅韦杜，莫问此时天。"]},{"t":"访卢逸人却寄","f":"五言律诗","c":["迷途问牧童，虚谷见愚公。","百舌梅花里，二毛蓬户中。","檐风清响铁，厨水远邀筒。","别后千山外，依依一亩宫。"]},{"t":"倩人寄吴越书","f":"五言律诗","c":["隔岁成书札，春催雁即飞。","八行缄字密，千里访人稀。","河草通清梦，关梅带掩扉。","凭君计然策，吴越见同衣。"]},{"t":"戍客吟","f":"五言律诗","c":["长城万里远，久戍不知劳。","听角单于小，占星太白高。","何辞逐行幕，不惜敝征袍。","为报红楼妇，新妆认节旄。"]},{"t":"赠屈贲士仪部","f":"五言律诗","c":["怜尔高阳裔，含愁向楚天。","八龙秋色远，一鹤下荒烟。","陋室且相聚，悲歌谁为传。","茫茫江海畔，閒却祖生鞭。"]},{"t":"寄黎左严","f":"五言律诗","c":["登台问梅信，君有故人心。","老作南州卧，愁连东海深。","好风通语默，皦日慎飞沈。","相约关前路，匡山且入林。"]},{"t":"喜伟公侄过","f":"五言律诗","c":["咏怀思对尔，烟渚过秋鸿。","蔓草是今日，竹林还古风。","但令奇字满，莫恨故园空。","举酒复相勉，黄金徽爨桐。"]},{"t":"三闾庙","f":"五言律诗","c":["汨罗沈自昔，安问后人怜。","古庙临湘水，秋兰薰楚天。","巫歌村社鼓，客至洞庭船。","惭愧生斯世，长沙泪洒然。"]},{"t":"黄石公祠","f":"五言律诗","c":["素书传孺子，黄石是吾师。","何事谷城道，披榛寻古祠。","风生雕虎啸，日落蹇驴疲。","济北遥遥去，鸡鸣何处期。"]},{"t":"仲宣楼","f":"五言律诗","c":["飘零千古意，词客望秦川。","乱世何如此，登楼空复然。","浮萍逢落日，远雁下寒烟。","莫问依刘事，归欤沧海边。"]},{"t":"采石夜泊","f":"五言律诗","c":["千秋牛渚月，清影照袁郎。","异代还高咏，孤臣对举觞。","江心飘断梗，天末见维桑。","何处瞻鳷鹊，金波自渺茫。"]},{"t":"黄金台","f":"五言律诗","c":["此台犹可上，此意莫能酬。","骏足轻千里，当年侧席求。","朔风高雁度，燕阙暮云愁。","行子非干进，长歌别蓟丘。"]},{"t":"严陵钓台寄关西故人","f":"五言律诗","c":["我来钓台上，怀古复沾巾。","不有中兴主，那为高尚人。","春波翻白鸟，落日转青蘋。","漫似狂奴态，遥遥寄渭滨。"]},{"t":"入剡中怀贺监","f":"五言律诗","c":["乍入剡中路，先令客望劳。","湖将一曲远，山有四明高。","贺监今何在，谪仙宁独豪。","荷花空满浦，惆怅发轻舠。"]},{"t":"寄林信卿广文","f":"五言律诗","c":["增江仙岭下，君寄一毡寒。","欲饱青精饭，非耽苜蓿盘。","鸟吟山户晓，虫篆竹书乾。","我有怀仙操，横经试一看。"]},{"t":"赵国子书至赋答","f":"五言律诗","c":["恍然开尺素，之子抱连城。","江海还逢掖，风尘误上卿。","豫章俄独老，桑落念同倾。","此意难持报，萧萧楚泽蘅。"]},{"t":"春溪独往率尔遣怀","f":"五言律诗","c":["林香迎杖发，一路落橙花。","复被鸟声引，溪南人几家。","暄风吹日动，细水向田斜。","即事可深悔，平生白鼻騧。"]},{"t":"赠张昆城曾青藜","f":"五言律诗","c":["故园吾作客，羁旅子投谁。","杯酒执无地，相逢空复辞。","月连徐孺宅，花笑陆郎骓。","云海春还暮，宾鸿方去兹。"]},{"t":"春暮","f":"五言律诗","c":["自徙江村遍，谁令春色深。","泊如过屡空，铿尔奏长吟。","花落穿书蠹，风惊下案禽。","袖中三岁字，空见故交心。"]},{"t":"赤花洲寄朱生","f":"五言律诗","c":["中洲未归客，伫立赤花洲。","日动绿槐影，闻君骄紫骝。","绛纱傅郑子，黄石待张侯。","肯以青云器，随余汗漫游。"]},{"t":"秋霞效骆丞","f":"五言律诗","c":["人惊洛川上，秋在赤城隈。","散处皆成绮，流时定作杯。","染江枫失叶，烛野烧无灰。","五云虽稍隔，终是掞天才。"]},{"t":"寄林潜颖","f":"五言律诗","c":["往岁龙山曲，寻君穿菊丛。","今朝渔浦上，忆别对江枫。","四海怀知己，千秋怯伏戎。","一从裘马敝，栖息几人同。"]},{"t":"感秋四十首 其一","f":"五言律诗","c":["秋至三城里，羁愁不可言。","香须薰宋玉，丝欲绣平原。","座逼千金寿，家悬一饭恩。","长裾经岁典，谁道曳朱门。"]},{"t":"感秋四十首 其二","f":"五言律诗","c":["轻风吹禦寇，举步欲泠然。","那使扶摇翼，而飞莽苍天。","平沙多雁阵，濒海绝人烟。","挥手复归去，高斋叠嶂前。"]},{"t":"感秋四十首 其三","f":"五言律诗","c":["素交长逝矣，心事与谁论。","望去虹蜺气，招来胡蝶魂。","浮名孤并驾，清泪切啼猿。","携手一相失，吁嗟甘闭门。"]},{"t":"感秋四十首 其四","f":"五言律诗","c":["昔别重城出，曾营三径幽。","结茅恒苦雨，种树总宜秋。","去去北山外，盈盈南渡头。","何当归此地，垂钓一销忧。"]},{"t":"感秋四十首 其五","f":"五言律诗","c":["世态狂澜倒，何人结古欢。","心将日皛皛，行怯露漙漙。","荆棘生毫末，干戈起舌端。","惟应万峰隐，差可一身安。"]},{"t":"感秋四十首 其六","f":"五言律诗","c":["失我乌衣巷，登君白玉除。","人疑趿珠履，或亦候篮舆。","桂岭秋偏蚤，松窗月正虚。","茂陵家不远，何事倦相如。"]},{"t":"感秋四十首 其七","f":"五言律诗","c":["平生矫俗虑，不乐闻徵输。","负郭田方弃，未能归旧庐。","中林行命酒，欹案坐观书。","仰止桐江客，垂纶不羡鱼。"]},{"t":"感秋四十首 其八","f":"五言律诗","c":["晚世轻黄发，秋风凋白杨。","鹤归千岁老，鸡唱二更荒。","大翼风难举，方舟壑暂藏。","眷回潸出涕，贤哲几沦亡。"]},{"t":"感秋四十首 其九","f":"五言律诗","c":["名流今特盛，览古觉才难。","请以市琴碎，为君杯酒欢。","道存不下带，心折一相看。","百尺琅玕实，惟应彩凤餐。"]},{"t":"感秋四十首 其十","f":"五言律诗","c":["彩凤舞炎方，朝阳更夕阳。","苍梧不可宿，韶石但相望。","本与麟龙并，如何羽翼伤。","长歌洁心志，芝草秀斋房。"]},{"t":"感秋四十首 其十一","f":"五言律诗","c":["昔我居环堵，江村远甲兵。","池风鱼沫出，林雨竹根萌。","天阔看无尽，窗虚梦不惊。","全无近市宅，唯此故园情。"]},{"t":"感秋四十首 其十二","f":"五言律诗","c":["未能抛故态，毋乃是狂奴。","本自襟期一，翻成今昔殊。","接舆解衰凤，伏枥想名驹。","老我湘江外，陈词问有虞。"]},{"t":"感秋四十首 其十三","f":"五言律诗","c":["青琐先君职，金台屹古燕。","艰难依丙舍，谏诤忆丁年。","自上玄成牍，空归范蠡船。","海天迷皂帽，何处拟辽田。"]},{"t":"感秋四十首 其十四","f":"五言律诗","c":["闻道凌云构，锱铢均众材。","凫飞葛令下，骓驾陆郎来。","地爱求砂近，天教使橐回。","如何过结驷，非为荜门开。"]},{"t":"感秋四十首 其十五","f":"五言律诗","c":["多年贫贱惯，颇觉俗尘稀。","蜾蠃入筠管，飞鹑恋葛衣。","何曾挟策出，翻欲聚粮归。","抗手谢知己，毋令心曲违。"]},{"t":"感秋四十首 其十六","f":"五言律诗","c":["袁宏运租去，甘与众佣群。","日为千仓积，非因五谷分。","舟中看皓月，身外比浮云。","偶尔成高咏，偏教谢尚闻。"]},{"t":"感秋四十首 其十七","f":"五言律诗","c":["泪以劬劳下，吟为曾闵思。","未将封树合，空诵蓼莪为。","綵舞三迁地，庭趋七诤时。","最饶纶綍贵，一倍负恩私。"]},{"t":"感秋四十首 其十八","f":"五言律诗","c":["一裘齐相敝，七叶汉侯传。","世有勋华盛，从来廉节全。","怀存鸣凤曲，泪展鹡鸰篇。","琐琐流离子，如何遂勉旃。"]},{"t":"感秋四十首 其十九","f":"五言律诗","c":["开府方夫子，当年骨鲠臣。","西人瞻节钺，南纪惜经纶。","是日敷天泪，遥摧报主身。","只今知己感，往事总伤神。"]},{"t":"感秋四十首 其二十","f":"五言律诗","c":["同声曾不少，今日几人存。","最想匡山衲，多时阻笑言。","交惟天下士，法是众中尊。","却谢三千客，吾归不二门。"]},{"t":"感秋四十首 其二十一","f":"五言律诗","c":["欲采琪花去，云深不可知。","青天难矫翼，尘世总低眉。","方朔何容易，灵均有所宜。","金丹如可授，会是别渑淄。"]},{"t":"感秋四十首 其二十二","f":"五言律诗","c":["故人书不至，边雁度梅关。","月色江湖上，秋声枕席间。","霜清九曜石，木落二樵山。","独向南楼叫，知予鸥鹭閒。"]},{"t":"感秋四十首 其二十三","f":"五言律诗","c":["与子策龙媒，言登南武台。","长空一鸟疾，远水孤帆来。","自古兴怀地，应高作赋才。","北风吹且缓，目极秋云开。"]},{"t":"感秋四十首 其二十四","f":"五言律诗","c":["昔日王孙路，而今草已黄。","还家对乡里，拂面有繁霜。","磊落生高兴，萧条免慢藏。","浮家皆信美，回首暮川长。"]},{"t":"感秋四十首 其二十五","f":"五言律诗","c":["举世知名蚤，中年学道迟。","识途伤老马，戢翼愧长离。","与客吟风竹，寻僧供露葵。","旷怀人境内，何叹路多歧。"]},{"t":"感秋四十首 其二十六","f":"五言律诗","c":["南城起凉月，今夜好长歌。","车马喧渐息，客心清奈何。","中天下风露，前月过星河。","有酒且沈醉，安能忧思多。"]},{"t":"喜翁山道人归自辽阳作","f":"五言律诗","c":["芙蓉南浦开，开士玉关回。","万里辽城鹤，仍栖朝汉台。","久游生古貌，相对出新裁。","处处兰荃意，楚魂吟自哀。"]},{"t":"郊居答梁颙若陈元孝见访之作","f":"五言律诗","c":["我憩西郊外，入山殊未深。","不堪徵赋及，幸有故人寻。","金磬答双院，木瓜寒一林。","还期同静坐，乘月在长吟。"]},{"t":"铜雀妓","f":"五言律诗","c":["惊乌将顾兔，夜夜起西陵。","玉箸隐然堕，铜台空复登。","歌尘愁易积，舞袖倦难胜。","寒绝当年宠，漳河有断冰。"]},{"t":"经漂母墓","f":"五言律诗","c":["淮阴成往迹，客子渡淮来。","旅食若为进，王孙还此哀。","春流萦落絮，古墓蘙新苔。","向晚空相见，城阴罢钓回。"]},{"t":"伟公侄至宿","f":"五言律诗","c":["寒宵共阿咸，陋巷本居南。","雨气侵残梦，鸡声发绪谈。","家风怀万石，春兴待双柑。","莫道天难问，高高是蔚蓝。"]},{"t":"礼诵后作寄道侣","f":"五言律诗","c":["十年伤白发，万虑息金经。","春鸟鸣鱼梵，天花落草亭。","高堂嗟见背，大块实劳形。","为寄潮音去，宗风满塔铃。"]},{"t":"佛日东游答欧奏孚陈皖公","f":"五言律诗","c":["西方传佛日，东去访仙山。","五十未闻道，江湖稀闭关。","苍烟奔急翼，霁景媚衰颜。","君问逢迎意，方将乞大还。"]},{"t":"度龙川","f":"五言律诗","c":["佗城游不得，孤棹上龙川。","岂挟千金橐，而冲五岭烟。","江风吹苦竹，津树咽新蝉。","又策斑骓去，无诸海国边。"]},{"t":"五日龙川舟中时文晖先归","f":"五言律诗","c":["百里仍秦县，千秋忆楚臣。","符开银艾小，粽裹绿荷新。","乡土能无恋，愁思郁未伸。","那堪观霸气，临水送归人。"]},{"t":"困酒入诃林留宿自公房","f":"五言律诗","c":["祇园甘露滴，使我宿酲消。","独自留方丈，诸天不寂寥。","行踪泥芳草，吟兴写芭蕉。","已作逃禅客，无烦折简招。"]},{"t":"海幢寺阿字首座屡约相过未果作此简之","f":"五言律诗","c":["隔江曾自度，长约渡江人。","绝迹淹残雨，浮生阅仲春。","钟吟清水泛，门迥白鸥邻。","不到真空地，梨花月漫新。"]},{"t":"澹归大师自丹霞山至海幢寺有赠","f":"五言律诗","c":["多君驻白足，结宇向丹霞。","依树珠林矗，缘藤石径斜。","閒摇下山策，方值泛源花。","可念江城客，飘零似出家。"]},{"t":"移居 其一","f":"五言律诗","c":["携家似行脚，重卜佛山居。","避寇图中策，呼童载旧书。","春风开瓮牖，夏屋谢权舆。","莫谓皆稠杂，萧萧竹影疏。"]},{"t":"移居 其二","f":"五言律诗","c":["怅别仙湖里，何期住佛山。","乌衣离乱后，青琐市尘间。","花鸟欺容膝，亲朋劝破颜。","来逢脩禊日，觞咏且宜閒。"]},{"t":"与家明敬","f":"五言律诗","c":["后于君学道，实是愧称兄。","岩岫有同适，江湖嗟各行。","殊勋閒料易，俗事偶谈清。","何故疏踪迹，骑牛独到城。"]},{"t":"寄尹右民","f":"五言律诗","c":["蝉鸣江稻熟，鹭食渚荷香。","送客东官去，怀人夏昼长。","高歌求伐木，不远得维桑。","门内论公道，山公是弟行。"]},{"t":"七夕过李琬若希素兄弟斋中时有谈禄命者","f":"五言律诗","c":["秋宵疏柳下，群坐见双星。","独作江头月，浮来满户庭。","候虫参语默，天爵测玄冥。","莫论纷纭事，邻箫细可听。"]},{"t":"桐江方君及妻祝氏孝节诗","f":"五言律诗","c":["七里严陵濑，三声旧断猿。","成仁身后事，之死梦中魂。","白日空军幕，青编美相门。","南来一鸣雁，犹感鹡鸰原。"]},{"t":"寄谭公子","f":"五言律诗","c":["南游无赠橐，君本是南金。","自别过穷腊，相思作会吟。","吟清卧薪骨，文细浣纱心。","草屋稽山上，悬知春又深。"]},{"t":"佛日至端州","f":"五言律诗","c":["疏钟岩畔发，孤棹峡中行。","是岸西方到，兹辰大圣生。","望农花雨急，问禁竹房清。","旅食同僧乞，依稀舍卫城。"]},{"t":"戏赠山中长者","f":"五言律诗","c":["往往山家语，多君善住山。","券焚收责便，租散课耕閒。","入酿蒸苍耳，迎人使白鹇。","不知江水上，那遣辙鱼还。"]},{"t":"遥送孙无言自扬州还黄山","f":"五言律诗","c":["维扬不久客，故里有黄山。","厌听竹西唱，欲怡松际颜。","鸾高方解啸，鹤在更知还。","望以罗浮月，寥寥天地间。"]},{"t":"雨中过离公房","f":"五言律诗","c":["禅房高柳色，晴雨共依依。","我到不知屡，所闻惟觉稀。","堂邀云板食，炉烘水田衣。","坐对烟郊晚，嗈嗈沙雁飞。"]},{"t":"送人游西岳","f":"五言律诗","c":["山色淡无尽，片云飞向西。","身将落日上，背指秋旻低。","我独未得往，三峰空有倪。","因君寄清梦，寥绝问高栖。"]},{"t":"送吴熙申之潮州兼讯故将军吴葛如家予时有豫章之行","f":"五言律诗","c":["江南芳草气，蒸作岭南云。","更客江南久，相逢对夕曛。","北风随落雁，西第忆将军。","我亦东林去，山钟使尔闻。"]},{"t":"将之吴越留别亲友 其一","f":"五言律诗","c":["童年随历宦，胜地祇谙名。","记得山川遍，重为老大行。","垂杨萦越岸，娇鸟入吴声。","谁谓家乡远，逢人识父兄。"]},{"t":"将之吴越留别亲友 其二","f":"五言律诗","c":["赭颜当别酒，不饮且先陈。","衣食堪生我，妻孥暂托人。","回肠千水曲，迎面众山新。","肯厌一茅屋，端居养性真。"]},{"t":"发舟言怀 其一","f":"五言律诗","c":["丛花三月重，百戏一村喧。","静者那同俗，兹焉遂出门。","路纡思逐鸟，吟断待呼猿。","已得无穷意，当为别后言。"]},{"t":"发舟言怀 其二","f":"五言律诗","c":["独自装瓢笠，还谁宠远行。","人人嬉上巳，物物得由庚。","话就官亭短，诗将客货轻。","江风与山瀑，初作枕间声。"]},{"t":"过飞来寺","f":"五言律诗","c":["忽见飞来寺，去心还欲飞。","前山青不已，孤鸟白初微。","樯杪杂千树，帆阴封半扉。","泠然于此过，风笛在渔矶。"]},{"t":"舟中示从侄孙寂珠上人","f":"五言律诗","c":["儒业痛非时，沙门早愿归。","为君持一杖，犹未著三衣。","船卧宵中密，斋炊午后稀。","远峰灵鹫色，只待兴如飞。"]},{"t":"泊樟树访屠梦破","f":"五言律诗","c":["岸上话将续，橹声难久停。","欲攀彭泽柳，一系楚江萍。","灶隐朱砂暗，门开樟叶青。","不嫌霜鬓老，秋晚许重经。"]},{"t":"宿栖贤寺","f":"五言律诗","c":["听得万松声，如传五老迎。","到门云旧识，释子晚经行。","怪石云衣覆，虚寮夜瀑明。","终期此禅寂，安用昔贤名。"]},{"t":"游万杉寺","f":"五言律诗","c":["拄著茶枝杖，龙钟入万杉。","石欹泉自咽，山午日教衔。","竹箸挑中饭，棕鞋下半岩。","老师浑坦率，眼见葛藤芟。"]},{"t":"寓南康东观赠章松樵道人","f":"五言律诗","c":["东观同为客，南阳老鍊师。","玉京遗草莽，庐岳借茅茨。","泣鬼多将字，饶人半在棋。","连朝沥酒出，鹤发仅如丝。"]},{"t":"逢邓子敬讯郭天门先生家居有寄","f":"五言律诗","c":["中丞归老处，一片洞庭秋。","客至鄱湖上，湖光远近浮。","天风吹鹤氅，海国忆龙舟。","若有离骚作，知子赋远游。"]},{"t":"与彭海翼夜话","f":"五言律诗","c":["旅夜众嚣息，与君谈便长。","看诗双眼大，阅世二毛苍。","帘洞垂深影，炉峰袅静香。","我行思隐遁，休取贱名扬。"]},{"t":"过彭蠡湖","f":"五言律诗","c":["禹迹停终古，湖光荡至今。","涵云四天影，注瀑一山心。","垂白浮孤棹，飞乌背远林。","所思犹未见，渔唱夕烟深。"]},{"t":"望九华","f":"五言律诗","c":["江南莲乍动，帆背二孤开。","水气偏浮上，山光忽照来。","地增人峭绝，云合路纡回。","明到池阳郡，思君且上台。"]},{"t":"石埭访姚六康明府","f":"五言律诗","c":["白笴陂前路，长吟问玉人。","琴堂时一望，雨霁九峰新。","野寺弛官禁，江楼纳客身。","还凭仙舄力，能使入山频。"]},{"t":"同毕牧生萧湘隐游万松庵","f":"五言律诗","c":["城喧时得避，松为响飕飕。","复与行吟接，因令旅思留。","维新香火故，结夏石堂秋。","看展华严礼，殊无一字酬。"]},{"t":"逢沈从弱","f":"五言律诗","c":["忆打渔阳鼓，风流自皖江。","忽然清梦断，消息宝钟撞。","夫子复解此，难将宿习降。","相期鸾啸处，江阁对虚窗。"]},{"t":"石埭昭明太子庙","f":"五言律诗","c":["只在删诗后，斯文入选初。","能收百家作，非但一朝书。","山出菁华外，江流绮靡馀。","何期向萧寺，野服拜仙储。"]},{"t":"湾沚 其一","f":"五言律诗","c":["江南山县里，不省是江南。","野鸟啄亭木，狞龙胶石潭。","照鱼松火猛，驱魃纸旗惭。","今作投湾沚，心惟江月涵。"]},{"t":"湾沚 其二","f":"五言律诗","c":["湾沚宣州地，水乡连众山。","蝉嘶溪木上，虹饮岳湖间。","带梦依垂钓，囊诗应榷关。","偏宜远游兴，浩荡大江还。"]},{"t":"过句容作","f":"五言律诗","c":["微凉初贴地，稍稍上行踪。","远树漏人语，斜阳明句容。","排门询葛令，宿店倚茅峰。","明又催僮起，马头闻曙钟。"]},{"t":"兰陵赠庄书采进士","f":"五言律诗","c":["兰陵荀祭酒，绛帐马扶风。","岂敢一日长，惟应千里同。","吞沙龙嘴现，射日凤毛红。","不忘行吟叟，弦歌或向东。"]},{"t":"赠吕半隐常博","f":"五言律诗","c":["巴江隐隐流，岂是浙江秋。","君住湖山曲，峨嵋天际头。","云松巢独鹤，沙屿过群鸥。","千里论胶漆，真堪此处投。"]},{"t":"长兴大雄寺听吴仲徵弹琴","f":"五言律诗","c":["古寺过从密，秋心不待言。","鸣琴匣里出，歌凤指端翻。","独作高阁啸，犹嫌邻磬喧。","当携画溪上，弹向老梅根。"]},{"t":"同朱五瑞吉人兄弟游画溪","f":"五言律诗","c":["君家兄弟好，邀我画溪游。","一幅展松雪，几回来隐侯。","停桡访高阁，过树俯清流。","已得忘筌理，持竿何所求。"]},{"t":"客长兴时京口李司直自卞山买舟相寻","f":"五言律诗","c":["浮萍各自飘，折简不烦招。","知有五千字，来从丁卯桥。","埋名已东郭，访古尚南朝。","想借天人供，禅房慰寂寥。"]},{"t":"铁如意","f":"五言律诗","c":["新得铁如意，浑如来一朋。","斜根芝贴石，耸脰鹤陪灯。","只许频更仆，何须叩默僧。","深冬还一捉，心解冷如冰。"]},{"t":"张友鸿司李招饮竹深书屋王衡之工部适自白下至","f":"五言律诗","c":["华堂屏歌舞，深馆特邀余。","馔倚商周鼎，杯参甲乙书。","论心欢有素，赏句讶无初。","更喜同声至，休令促膝疏。"]},{"t":"旅馆折蜡梅花贻王衡之","f":"五言律诗","c":["敬致王工部，孤心在蜡梅。","虽然经折了，犹有未曾开。","东莞牙香片，西洋蜜珀杯。","不堪乡物奉，客思为君裁。"]},{"t":"游穹窿山上真观闻施亮生尊师有岭南之行留此为赠","f":"五言律诗","c":["真师请于帝，应世住穹窿。","锁院凭雷掣，飞楼惹鹤翀。","神形符字凸，鬼血剑花红。","见说南行久，多应遇葛洪。"]},{"t":"京口金山寺","f":"五言律诗","c":["归逐赣船行，金山下且停。","閒身无北顾，道味在中泠。","雉堞分城出，鲸钟带浪听。","家乡海珠寺，髣髴似宁馨。"]},{"t":"金陵 其一","f":"五言律诗","c":["六朝君莫问，千古并生愁。","宫似咸阳创，江胜雒水流。","鹓鸾何日散，芦苇飒然秋。","独有秦淮月，时时照客舟。"]},{"t":"金陵 其二","f":"五言律诗","c":["往日南京事，閒时共尔论。","江来千万派，城启十三门。","剑佩留勋府，戎衣在寝园。","兴亡看六代，何必远伤魂。"]},{"t":"辛亥秋遇沈从弱于石埭遂往白门相期归路访其安庆家居兼取药地和尚近耗明年归舟经过乘风不及登岸为之怅然","f":"五言律诗","c":["去岁曾相约，春江草阁中。","拟闻清啸足，兼与老禅通。","破浪浮扬子，看山失皖公。","无由登彼岸，人世易西东。"]},{"t":"归宗寺戒后与记汝阇黎夜话","f":"五言律诗","c":["与师谈娓娓，浑不著绵藤。","戒后身知贵，穷来愿解宏。","春将枯树美，瀑似石崖崩。","才觉抛儿戏，归鞍倚大乘。"]},{"t":"开先寺留呈山鸣和尚","f":"五言律诗","c":["招提经林麓，不觉过桥来。","赑屃兼山负，虹蜺落涧开。","衣摊春草染，杖发暝钟催。","未敢酬言语，山阳有殷雷。"]},{"t":"敷浅原","f":"五言律诗","c":["别有深深意，舟行敷浅原。","水通神禹智，山鉴谪仙言。","火食参烟气，风衣燥雨痕。","不因飘荡极，那解卧林园。"]},{"t":"寿曾旅庵","f":"五言律诗","c":["鼓枻过沧浪，看君正钓璜。","参差分老少，一半共行藏。","古意含灵寿，春风满豫章。","请歌新乐府，惟采旧芝房。"]},{"t":"往还岭上皆值佛日","f":"五言律诗","c":["佛日出梅关，踰年佛日还。","有怀惟野老，如愿即乡山。","衣逐缁流破，鞭垂白马閒。","如何卢行者，归路发先斑。"]},{"t":"初发连州","f":"五言律诗","c":["岁晏穷千里，心知恋本州。","山川交楚粤，文藻忆韩刘。","对雁方怀岳，看云却背楼。","疏林晴可数，寒鸟不妨投。"]},{"t":"中宿峡","f":"五言律诗","c":["舟过罕攀跻，幽奇事可稽。","笛传黄帝子，环系白猿妻。","古迹分明在，新松髣髴齐。","老僧如久定，期宿此招提。"]},{"t":"江上","f":"五言律诗","c":["水程天易晚，客思此逡巡。","斜日铺江面，遥帆卸树身。","休灯窥岸烧，息语会船邻。","此去犹悬绝，离忧近楚人。"]},{"t":"湟水舟中","f":"五言律诗","c":["腊近客都归，吾游尚未几。","楚萍催发迹，江雪溅行衣。","山僻僧孤往，潭明鸟对飞。","陶潜偶然出，毋乃为愁饥。"]},{"t":"送远斋上人北游","f":"五言律诗","c":["了得南宗义，因人漫北行。","衣藏珠自现，锡指雁新横。","舌底将莲种，眉毫斗雪生。","遥知直署客，休沐出都迎。"]},{"t":"寄潘子","f":"五言律诗","c":["南园旧诗社，潘子此翱翔。","城树标吟出，渠花引步香。","纵横轻白璧，谑浪倚红妆。","傥问离居者，虫声满草堂。"]},{"t":"夜潮","f":"五言律诗","c":["维舟偶终日，不约肯重来。","雁翅城边月，虎头门外雷。","岸高渔火上，沙暗縠纹回。","可是期神女，非关行雨台。"]},{"t":"赠脂落上人住景泰寺 其一","f":"五言律诗","c":["常时住山意，独与老夫论。","眷属恒相外，云峰觉尔尊。","向人求箬笠，并鸟过松门。","度得中餐饱，疏泉注茗根。"]},{"t":"赠脂落上人住景泰寺 其二","f":"五言律诗","c":["景泰繇来久，诃林别一林。","无忘出家地，终遂入山心。","金界何烦施，白云元自深。","城头隐孤月，后夜上方寻。"]},{"t":"廖昆湖太守见示胡沂庵太守邀过赏菊兼赠黄菊一盆赋谢之作有和","f":"五言律诗","c":["黄堂返初服，色尚映东篱。","相赠长生药，相辉绝妙辞。","登盆珍水土，入盏谢糟醨。","欲并幽兰采，佳人倍可思。"]},{"t":"西畴早春","f":"五言律诗","c":["落落向春城，欣欣出郭行。","生烟林薄色，细水石桥声。","菜甲塘边摘，秧船草际撑。","閒心亦何望，归去学躬耕。"]},{"t":"赠杜光生","f":"五言律诗","c":["对尔城南近，来从路几千。","一寻铜柱迹，罢饮锡山泉。","带甲归环堵，家丁尽下田。","心肝缘若个，长泛左江船。"]},{"t":"送陈明敬游西湖","f":"五言律诗","c":["西湖清彻底，观海眼犹悬。","二月千花浪，三吴一叶船。","红颜开藕际，白业在鸥边。","去去隳名得，鸱夷未足贤。"]},{"t":"阮伯髦见过有赠","f":"五言律诗","c":["能言常不倦，老益见精神。","篆必师秦相，医何让越人。","疏杯偏热耳，选杖不扶身。","复此閒相对，溶溶竹屿春。"]},{"t":"寄叶许山","f":"五言律诗","c":["水门山郭里，旧种掖垣梧。","示客书多秘，随僧礼半儒。","池浮苏子舫，家造葛仙庐。","莫更寻閒事，如花镊白须。"]},{"t":"送区公式同何景常之任溧阳","f":"五言律诗","c":["临行资馆谷，赎得敝裘回。","微雪飘长荡，閒云到大坏。","寻幽知独往，望远倩君催。","铸剑前徽在，羞称笔札才。"]},{"t":"唐倩明藜之潮州谒宋太守索予赠诗","f":"五言律诗","c":["唐勒游何事，东寻宋大夫。","披云看揭岭，乘月过丰湖。","生计愁鹏徙，归期约鲤趋。","丈人何足赖，八口向人糊。"]},{"t":"江上","f":"五言律诗","c":["人间不得意，江上往还来。","雨至潮初长，帆归烟未开。","荆吴占利涉，南北满云雷。","惟有残僧苦，茫茫渡一杯。"]},{"t":"绿茉莉","f":"五言律诗","c":["茉莉白可摘，崖州殊不然。","鸭江来细雨，蕉叶漏诸天。","蜀客绮相对，石家珠可怜。","谁曾簪雪鬓，传到素馨田。"]},{"t":"与郝载匡夜话","f":"五言律诗","c":["床如丁字置，夜与郝生谈。","世故淡边谢，禅心嚣里参。","轻装分絮被，归计在松庵。","莫谬推师长，知君青出蓝。"]},{"t":"访梁法师道院归途遇雨柬同游林李二子","f":"五言律诗","c":["西郊云偶集，先雨谒东皇。","露马踏风叶，飙车候石房。","夫君元始佐，启我玉函光。","归路嚣尘息，中峰鍊九阳。"]},{"t":"美斯侄谋同予归营沙贝祖居诗嘉其志","f":"五言律诗","c":["尔念流离久，慨然思本源。","能依先世泽，即见累朝恩。","天籁空南郭，清风洒石门。","纵令归未得，何敢忘斯言。"]},{"t":"同循州车世之咏一长命人得轩辕集","f":"五言律诗","c":["荒涂纡逸轨，抗手问轩辕。","独有玉书要，空留金阙恩。","韬精竹叶酒，散发扶桑暾。","客自罗浮至，应知羽士魂。"]},{"t":"箨冠","f":"五言律诗","c":["相期竹林下，相问竹皮冠。","况是萧萧鬓，华簪非所安。","端居崇朴素，危坐对檀栾。","唯有湘江上，三闾时一弹。"]},{"t":"落落","f":"五言律诗","c":["落落千秋赏，此生殊可怜。","閒云过白眼，流水切朱弦。","物态久相轧，文心终自宣。","可能如脉望，食字得神仙。"]},{"t":"访丹霞先生","f":"五言律诗","c":["屏居不肯出，便老即迷邦。","渔艇独知汉，鹿门原姓庞。","白云侵隐几，雕虎过吟窗。","问我从何至，一樽浮越江。"]},{"t":"赋得秋水寄怀友人","f":"五言律诗","c":["无限秋天色，偏于秋水多。","风高太液雁，月满洞庭波。","最彻庄生理，堪邀孺子歌。","自从南浦别，春去却如何。"]},{"t":"咏萧何","f":"五言律诗","c":["相国超诸将，收图不取金。","无双识韩信，画一付曹参。","名益图麟著，功将汗马深。","如何灭秦佐，偏结故侯心。"]},{"t":"寄杨六笥","f":"五言律诗","c":["昔有吴都督，英豪动海陬。","赠人挥万镒，教妓舞纯钩。","小队临花坞，高朋对画楼。","邀予未曾往，书此报杨侯。"]},{"t":"送体瑩上人之云门","f":"五言律诗","c":["祖庭将重辟，师命敢辞劳。","鹤过篷窗疾，猿窥箬笠高。","一林寒独往，众壑水相遭。","未觉暌言笑，松风与海涛。"]},{"t":"呈宗和尚","f":"五言律诗","c":["头白优婆塞，随堂近事初。","枯为秋院叶，醒及夜池鱼。","厥后曾何得，于人总不如。","那分一灯影，归彻小窗虚。"]},{"t":"水仙花","f":"五言律诗","c":["一一孤根发，丛丛翠叶新。","清琴弹此曲，白露谓伊人。","蓬岛何年别，兰堂幸可亲。","安知芳草气，不是雒川神。"]},{"t":"咏画竹赠剑公","f":"五言律诗","c":["何人操不律，种就此林于。","不异琅玕色，犹然篆隶书。","纸光依本质，壁影荫吾庐。","总觉非时尚，高贤来伴余。"]},{"t":"自东安将之新州阻雨先寄潘葱石","f":"五言律诗","c":["千山身偶入，十日雨淫淫。","狭室伏泉涌，前途芳草深。","村烟遮骋望，檐溜聒知音。","疲极津梁者，新州去印心。"]},{"t":"新州国恩寺是六祖故居","f":"五言律诗","c":["无生向师学，师是此中生。","树觉菩提长，山经獦獠行。","归鸦临寺黑，激水叩钟清。","我自虞园至，维桑空复情。"]},{"t":"鼻天子墓","f":"五言律诗","c":["鼻祖何年帝，荒唐得此名。","垂衣想韶石，左纛吊佗城。","落月妖狐拜，空山杜宇声。","兴亡都莫问，榛草细烟生。"]},{"t":"示美斯侄","f":"五言律诗","c":["萧然无旧业，亦可赋新诗。","燕筑座间击，奚囊杖后随。","云霄劳梦想，湖海引心期。","不见寒梅树，繁花雪满枝。"]},{"t":"上巳蒲涧偕诸子","f":"五言律诗","c":["异地兰亭会，春郊蒲涧游。","杖随清瀑引，觞带白云流。","旅食忽三月，狂歌仍一丘。","何烦脩禊事，灵境即蠲忧。"]},{"t":"宿城西与麦盛际","f":"五言律诗","c":["杠门新一出，听尔话汾州。","远梦断山驿，冷烟生海楼。","得僮吴语变，开箧汉碑留。","莫恨田方老，还应教魏侯。"]},{"t":"寓华林寺飓风欲归不果与天藏上人","f":"五言律诗","c":["风塘菱荇散，鱼鸟自相亲。","天怒驱神物，途危息老身。","所闻归夜梵，不寐达明晨。","复见东窗里，前身自在人。"]},{"t":"赠华林监院电公","f":"五言律诗","c":["来城常作客，向寺即如家。","佛子住才去，閒房飞供花。","江秋欣见苇，野暮厌闻笳。","忆得前相送，云山各靡涯。"]},{"t":"答陆导甫","f":"五言律诗","c":["陆郎金散尽，萧索对斑骓。","踏遍重关草，空馀两鬓丝。","春芳一以歇，阴雨况凄其。","世故还相见，披襟似旧时。"]},{"t":"念珠","f":"五言律诗","c":["乌木为珠子，黄山去日持。","得之云象罔，智者见摩尼。","个个成圆果，声声绕串丝。","君看白玉閒，多半是从缁。"]},{"t":"宝象林访在犙和尚","f":"五言律诗","c":["院隐一溪深，无人不到寻。","食来船运米，坐致地铺金。","廓落全开面，庄严总现心。","最堪增我恋，房树有巢禽。"]},{"t":"游麻奢宝象林还至冈头村遇雨","f":"五言律诗","c":["复此泥涂迹，真怜昨日晴。","弥天皆月色，破地忽雷声。","雨点红鱼吸，风轮白鸟征。","惟留法云在，烟树失江城。"]},{"t":"同旷圆大师庞若云诸子游家牧止深村别业","f":"五言律诗","c":["深村好林沼，况乃属深春。","最是闭门者，偏宜摇艇频。","花繁初露子，竹密竟遮人。","觅得青莲种，从来不染尘。"]},{"t":"水瓜架","f":"五言律诗","c":["庭浅怕天炎，栽瓜欲接檐。","叶看新绿布，花又嫩黄添。","浇水知含喜，和羹足养廉。","此间方偃仰，李下为谁嫌。"]},{"t":"寄梁药亭芙蓉村居","f":"五言律诗","c":["夫君泥不滓，避地入芙蓉。","况复乘一叶，回环江上峰。","充餐团瓣菊，覆屋曳枝松。","见说沙汀畔，分明好卧龙。"]},{"t":"赋得明月照积雪","f":"五言律诗","c":["凝阴宵忽豁，高下总晶晶。","冷气能相荡，空光只自盈。","梅疑无地落，鹤见有身惊。","头白绳床上，安禅故一行。"]},{"t":"闻天和尚自庐山归雷峰喜赋","f":"五言律诗","c":["日照金轮峰，遥瞻方丈容。","风生锡拄杖，归拨海门松。","忽慰三年别，初为两地逢。","愿教鼙鼓息，齐叩法堂钟。"]},{"t":"素馨鹦鹉 其一","f":"五言律诗","c":["香国生毛羽，飞来震旦遐。","分明鹦鹉鸟，莫道素馨花。","被雪心偏热，含辉影故斜。","迦陵音自足，凡鸟慎无哗。"]},{"t":"素馨鹦鹉 其二","f":"五言律诗","c":["花鸟恒相得，今看一体浑。","妆成矜独立，慧极耻能言。","与月呈诸相，因香托六根。","然灯红一抹，衔得觉皇恩。"]},{"t":"春山","f":"五言律诗","c":["一卧经残雪，新年忽改观。","地将青草上，天与绿云盘。","深洞花应合，高林鸟益欢。","化工如可肖，安敢惜毫端。"]},{"t":"春帆","f":"五言律诗","c":["飐飐复幢幢，吴江与楚江。","心存平水路，树闪侧船窗。","马走蹄无一，鸦飞翅自双。","指南车在此，春极海南邦。"]},{"t":"春岸","f":"五言律诗","c":["高深何所极，春在小河滨。","水映融和地，舟偕荡漾人。","游鱼听黄鸟，垂柳拂青蘋。","伫立忘言久，君休疑问津。"]},{"t":"春草","f":"五言律诗","c":["绿草蔓平原，风吹日复温。","远铺惟有色，促立似无根。","藉此添花事，多君护荜门。","试从樵者去，寻迹入西村。"]},{"t":"春泉","f":"五言律诗","c":["千山浑一气，拨著即淋漓。","静到极深处，閒来行汲时。","僧尝犹待滤，猿挂始能窥。","别有真香意，崖边花自垂。"]},{"t":"春衣","f":"五言律诗","c":["染成茶色布，裁作水田衣。","香草堪充佩，垂杨近带围。","逢人问宜称，见佛合皈依。","却语诸童冠，都从点也归。"]},{"t":"春屐","f":"五言律诗","c":["天晴亦著屐，休笑岭南人。","于道犹行古，□□□□春。","杖声间得得，石齿漱粼粼。","不碍尊瞻视，端然郭泰巾。"]},{"t":"春寒","f":"五言律诗","c":["得非寒士态，春到怯逾增。","陋室风黏壁，虚窗雨罩灯。","娇莺寻不见，懒仆唤无应。","戏论调元事，阳春一曲能。"]},{"t":"春灯","f":"五言律诗","c":["分光从一点，点点是春光。","二曜悬中夜，百花开此堂。","因心呈绝丽，隔燄觉微凉。","照尽寒斋客，君家不可忘。"]},{"t":"远如期","f":"五言律诗","c":["经年弹一调，道是远如期。","未审邀欢地，都为伫立时。","加衣防玉体，对镜写山眉。","万事归专一，何当慰所思。"]},{"t":"湘管","f":"五言律诗","c":["不知将寸管，何以问重华。","江岸斑斑竹，千竿似著花。","野云笼杂树，苔石点晴沙。","读罢灵均赋，含毫日又斜。"]},{"t":"端研","f":"五言律诗","c":["万古云凝处，渊深不可知。","文心正如此，山骨自多奇。","滴水波无极，浮星影欲垂。","行吟皆属汝，忆得过溪时。"]},{"t":"吹箫","f":"五言律诗","c":["玉琴浑碎尽，閒把洞箫吹。","紫凤吟乾竹，清商绕白髭。","行过吴市日，赋动汉宫时。","总是洪钧气，声声讵自知。"]},{"t":"相逢行","f":"五言律诗","c":["相逢君不见，疏柳对黄昏。","水畔鸦头袜，垆间犊鼻裈。","与云兼送目，为草亦交魂。","未得通媒妁，微私曷敢言。"]},{"t":"观斗蟋蟀","f":"五言律诗","c":["蟋蟀盆中养，无端敌势成。","何殊邹鲁鬨，信有触蛮争。","骨细楸枰子，威张草木兵。","颇供閒者看，物类几时平。"]},{"t":"追赋西苑","f":"七言律诗","c":["北极星辰敞太空，宸游辇路玉河通。","刍荛雉兔归文囿，封禅麟龙足汉宫。","点点尘皆经御跸，条条草亦仰皇风。","当年犬子非园令，曾识朝端谏猎忠。"]},{"t":"听百舌鸟","f":"七言律诗","c":["景阳钟动曙光开，丹凤城中春色来。","遂有登墙能急唤，多因出谷重相催。","临风几处生芳草，度曲纷然倚落梅。","一入深林聊自语，汉廷原有碧鸡才。"]},{"t":"偶书所见","f":"七言律诗","c":["春星隐隐匹匏瓜，日上青衣转绛霞。","拾翠误连书带草，避人偷折射干花。","鸳鸯也解栖胸锦，蜥蜴何劳养臂砂。","枉渚欲遵凫藻远，几重帷帐倚秦嘉。"]},{"t":"戊寅小岁和黎美周","f":"七言律诗","c":["声华街鼓急相闻，烛跋西园至夜分。","作赋不曾逢武帝，弹琴犹复看文君。","常时歌对吴阊月，奇服香连楚泽云。","何处新知最相乐，颉颃狂燕隔帘纹。"]},{"t":"三皇庙","f":"七言律诗","c":["三皇遗庙对荒丘，灵气苍苍至道留。","此日渐传天地意，儒生将诉古今愁。","图书远影连清渚，耒耜春风满绿畴。","忆昨骑驴过涿鹿，正闻兵法破蚩尤。"]},{"t":"感讽 其一","f":"七言律诗","c":["南越称臣汉赵佗，于今南海甚风波。","高台尚在堪朝汉，逝水如斯无渡河。","几度狐骀闻国诵，谁边犀兕答城歌。","涉川济世元多术，寄语楼船漫戢戈。"]},{"t":"感讽 其二","f":"七言律诗","c":["书生无计取封侯，群盗纷纷欲效尤。","遂使陈琳无罪状，何论关羽有春秋。","风来巢鹊曾思起，鼎沸江鱼故自游。","谁复轻身能报国，麒麟图画日悠悠。"]},{"t":"江上弹琴得女道士韩玉灵书却寄","f":"七言律诗","c":["海上依稀望五城，苇花飞处放船轻。","焦桐一引青鸾信，秋水皆添白雪声。","竹泪尽斑原鼓瑟，鹤毛如絮未吹笙。","四百芙蓉青可揽，只应知我已移情。"]},{"t":"中秋海上对月","f":"七言律诗","c":["三山长待驾鼋鼍，九点苍烟汎白波。","秋水极天临海若，夜帆殊域见嫦娥。","光生鹏翼垂云小，晕入珠胎映岛多。","听罢龙吟转寥阔，露华应坠故池荷。"]},{"t":"赠王季重先生","f":"七言律诗","c":["芝荣剡曲久悬车，秋宪高文重石渠。","棋隐独严司马法，扇题人宝右军书。","长将宦兴花边过，欲倚童颜海外居。","三十年来钦姓字，朗然挥麈就蓬庐。"]},{"t":"邀瀑亭探得西字","f":"七言律诗","c":["一踏春郊信杖藜，吾兄邀瀑有高栖。","招同桂树山虚左，漏满莲花日隐西。","射客御风惊履石，琴歌流水戛回溪。","欲穷康乐全山胜，已羡开门第一题。"]},{"t":"赠吴鲁冈恤部吴持张天如庶常书至","f":"七言律诗","c":["青蘋风起柳花垂，渐下吴江落叶时。","远札忽传金马署，使君原重爽鸠司。","偶怜义士骖能脱，长爱閒园席屡移。","为报虎丘明月道，石门天尽水涟漪。"]},{"t":"二月二十二日","f":"七言律诗","c":["罗浮二月春如烟，江花酣春入眼鲜。","句漏就丹未免俗，陆郎怀装殊自妍。","素丝皎皎在所染，黄雀飞飞谢少年。","五湖四海青眼几，与尔剖符知英贤。"]},{"t":"拟高常侍送李少府贬峡中王少府贬长沙","f":"七言律诗","c":["都亭风拂柳丝长，握手怜君谪两乡。","三峡建瓴奔滟滪，九疑如黛望潇湘。","清江雁落裁巴字，绝巘猿啼湿楚裳。","圣主恩深霄汉上，忍令双鹄久摧藏。"]},{"t":"家兄云淙落成 其一","f":"七言律诗","c":["北阙遥遥荷圣君，东山还欲谢人群。","仙家可住胜黄阁，卿月流辉照白云。","蒲涧瀑飞烟翠湿，桂林秋爽露华芬。","若为池草成佳句，高会连枝日未曛。"]},{"t":"家兄云淙落成 其二","f":"七言律诗","c":["杖屦宁寻楚泽芳，出郊高处选林篁。","人看谢傅营棋墅，自拟卢鸿卧草堂。","金界别成开士舍，白云元是列仙乡。","华阳弟子知无数，谁领松风过瀑长。"]},{"t":"归善王明府招同曹彝伯叶必泰姚瞻子游丰湖即席赋","f":"七言律诗","c":["鹅城西畔入龙渠，茂宰閒邀出郭车。","画里云山偏过鸟，镜中菱荇不潜鱼。","斜阳隔岸通樵唱，明月当空照客裾。","到处风流问湖水，郎官今夜醉何如。"]},{"t":"渔艇鸬鹚 其一","f":"七言律诗","c":["过河鱼泣未忘筌，比目宁为比翼怜。","小似垂云浮积水，真看衔石出重渊。","嘉名何事传乌鬼，贱质依人羡羽仙。","袅袅竹竿频应接，白头相慰报青钱。"]},{"t":"渔艇鸬鹚 其二","f":"七言律诗","c":["烹鲤休惊尺素书，论功恰似赋芧狙。","桃花源口同为业，莲叶江南识所如。","拂舞白鸠长祝噎，铙歌朱鹭亦称鱼。","扁舟却笑鸱夷子，远听涛声避伍胥。"]},{"t":"丰湖 其一","f":"七言律诗","c":["横桥微向合江分，流水淙淙出浅濆。","直接鹅城排雉堞，斜飞白鹤迥青云。","香风著草摇书带，明月生波濯练裙。","绝类钱塘歌舞地，罗浮仙霭别氤氲。"]},{"t":"丰湖 其二","f":"七言律诗","c":["一望山围敞旧楼，通江文物易传邮。","抱关近接丹砂令，潴水微开赤县州。","渔父沧浪时鼓枻，王孙桂树莫离忧。","轻风冉冉吹菱芡，随意观鱼更狎鸥。"]},{"t":"丰湖 其三","f":"七言律诗","c":["长堤犹忆直如弦，学士蒙恩剩赐钱。","窥月似分桥廿四，徙溟谁击水三千。","清尘漠漠银鱼影，碧草深深石马烟。","已觉春风悬荔颗，攀枝全借烛龙然。"]},{"t":"丰湖 其四","f":"七言律诗","c":["桃李年年解笑颜，朝云小字托巫山。","只缘胜地西湖似，不使佳人南国还。","黛写青螺皈净土，魂招黄鹄下前湾。","将离士女于今赠，雾露芙蓉尽等閒。"]},{"t":"新寮旅主鸡黍乞诗","f":"七言律诗","c":["鸟啼天白响柴门，鸡熟杯清出菜园。","谬以著书留老子，真能进食愧王孙。","忘年亦有荣枯纪，无欲休将好丑论。","昨夜床头叹梁甫，赠君閒步及朝暾。"]},{"t":"落第后将往潮州赴李乔之司李之约呈家兄宗伯","f":"七言律诗","c":["泣玉空将策屡干，家林袍笏映儒冠。","秋风落羽辞蓬阆，春水乘舟访李官。","载笔欲寻驱鳄地，担簦期共祝鸡坛。","风流自笑任公子，东海依人乞钓竿。"]},{"t":"曲江舟中怀张文献","f":"七言律诗","c":["亘矣南天张相国，遥遥风度系冠裳。","功名金鉴臣心直，乡国箫韶帝乐长。","燕子自衔宜白羽，鸽书相问荡炎方。","千年汉塞通周道，五马炉烟冷墓霜。"]},{"t":"冬心 其一","f":"古风","c":["长城血战窟曾腥，百二雄?不在扃。","安得将军奋猿臂，生擒老上捣龙庭。","丝纶远大承皇祖，爵禄分明点客星。","借问东南多竹箭，君王亲发为清宁。"]},{"t":"冬心 其二","f":"七言律诗","c":["山北山南应鹧鸪，舟来舟去似飞凫。","上林卢橘熟何晚，子夜梧桐歌有无。","青琐玉堂垂北极，翠翘金粉艳南都。","瞻天目共高帆上，夜半横过海鹤孤。"]},{"t":"冬心 其三","f":"七言律诗","c":["尉佗城对素馨田，日日香风度画船。","十月梅花盈岛屿，二樵云气护神仙。","堪窥载籍兰台里，不惜酣歌锦瑟边。","报主实多梁阁老，风流游豫武宗年。"]},{"t":"诏拟初唐应制","f":"七言律诗","c":["万里乘龙正御天，四方归马诏安边。","铙歌昔奏之回曲，镐燕新书卜雒年。","衮色旦披临玉帛，炉香风静肃貂蝉。","臣称圣寿沾三爵，还向明堂缀五篇。"]},{"t":"梁非馨归至行在因赠","f":"七言律诗","c":["一片南云对转蓬，五噫歌歇见梁鸿。","气凌燕筑高秋外，悲满秦淮细雨中。","廿载风流羞结客，几时天下罢从戎。","乡关信尔游踪近，桂树南山有小丛。"]},{"t":"赠罗文止祠部","f":"七言律诗","c":["过君花县上君堂，杯引清泉汎稻香。","不学骅骝宁历块，同为葵藿好倾阳。","春坛巨丽来三品，宵鼓纤阿倚七襄。","近听军书颇恢廓，即推文气更飞扬。"]},{"t":"戏简艾千子侍御","f":"楚辞体","c":["花点朝衣憩郭西，轻风一引夏蝉嘶。","时名且任呼牛也，君姓犹烦问凤兮。","今日好为真御史，前筹何以慰蒸黎。","汉家边事廷臣重，耻对侏儒作滑稽。"]},{"t":"度虔州","f":"七言律诗","c":["虔州四达康庄路，数月艰难忍戍边。","日落黄云高野烧，尘飞青草乱江烟。","一身琐尾金门外，中夜回肠画戟前。","最忆士行修战具，九牛无恙岭南船。"]},{"t":"凌江中秋","f":"七言律诗","c":["舟缘清浅发重湾，八月潮生客好还。","世乱随时忘涕泪，月明今夜尚关山。","即飞白羽催军令，自拂黄尘定壮颜。","四海转输劳尺泽，菰芦何处钓竿閒。"]},{"t":"代赠效李义山体","f":"七言律诗","c":["自觉妆鬟太沓拖，不因君意却因何。","车中果亦同心少，座上香须见面多。","犬子于今还绿绮，牛郎无夕不银河。","此心醉久公然说，冷淡朱颜更易酡。"]},{"t":"越王台","f":"七言律诗","c":["南天草昧越都开，南越风光武帝台。","万里楼船元渺漫，百年君相自迟回。","晴云白月空阳鸟，画角清歌出岭梅。","独有海滨渔父啸，郊原骑马半豗隤。"]},{"t":"舟中瓶梅 其一","f":"七言律诗","c":["顾影中流棹并斜，寒姿清切望天涯。","绿珠价重曾名井，碧玉生来自小家。","乱却游蜂过别苑，添将立鹭写晴沙。","即看琐碎明珰色，何处扬帆采石华。"]},{"t":"舟中瓶梅 其二","f":"七言律诗","c":["清川临镜认氍毹，骨象亭亭本应图。","楚客微辞怀白雪，江妃弹泪谢珍珠。","欲离尘网游三岛，量著仙衣点五铢。","一样苧萝山下水，鸱夷生计决归湖。"]},{"t":"舟中瓶梅 其三","f":"七言律诗","c":["木兰花老觉新香，横笛风回水一方。","南雪峥嵘不到地，中庭摇荡早经霜。","催来两桨湖烟冷，配得孤山鹤梦长。","情在陇头愁隔谷，且看渔父濯沧浪。"]},{"t":"舟中瓶梅 其四","f":"七言律诗","c":["山人衣白到扁舟，昨夜朝天露缀旒。","世上波澜疑沐鹄，壶中形影不惊鸥。","囊须献笑分前席，内手知寒映敝裘。","二十三丝丛水调，一时一瓣记箜篌。"]},{"t":"舟中瓶梅 其五","f":"七言律诗","c":["远趁银云海市光，擎将小贝出龙堂。","月明鲛女珠为泪，水冷溪姑石是郎。","似有佩遗遵汉广，欲随帆转望潇湘。","谁怜美晰来迟暮，蘋草汀洲日已黄。"]},{"t":"春日东皋席上即事","f":"七言律诗","c":["东皋风日静堪依，结伴凭高步翠微。","王气自居丹凤阙，徵书尝下钓鱼矶。","长杨赋就才应贵，子夜歌成调亦稀。","莫向五陵思杜若，可愁清梦与云飞。"]},{"t":"花烛诗","f":"七言律诗","c":["何年洛水献明珰，此夕天河有报章。","凤吹月连青锁闼，鳦衔春度郁金堂。","香奁向曙催鸿雁，画阁轻寒拥鹔鹴。","闻说莫愁新度曲，侬家夫婿胜王昌。"]},{"t":"白鸭","f":"七言律诗","c":["方塘萍荇荡纷纷，曲曲朱栏泛泛纹。","似任风吹成独往，偏能日浴向同群。","花边被服真浮月，水际弹冠妄切云。","今日呼名在邻里，羲之何必不怜君。"]},{"t":"用齐梁体作唐律","f":"七言律诗","c":["白雪红桃养莫愁，明珠翠羽粲登楼。","风斜乙鸟摇窗格，露满丁香上帐钩。","昨夜兰缸金蛱蝶，今晨杨陌玉骅骝。","却呼左右扃重户，莫使东西怨御沟。"]},{"t":"少年","f":"七言律诗","c":["冠玉簪貂结束新，鸣弦揽辔薄家臣。","鸳鸯是马能千里，繁弱名弓已百钧。","近垒烟花攒皎月，斜阳金鼓急清尘。","独将脱兔三千骑，可信骁腾处女身。"]},{"t":"无题","f":"七言律诗","c":["户转阑干花自生，铅华终日洗来清。","单衫半臂双条脱，白纻红牙子夜声。","沈水袅烟穿瑟瑟，守宫回印点猩猩。","鸳鸯鸂鶒徒相比，记得乘鸾吹玉笙。"]},{"t":"步摇","f":"楚辞体","c":["步摇妆近赵王筵，名列琵琶最小弦。","躄者井头羞上客，丱兮城里愿求仙。","偷来香麝薰周史，戴起金貂学董贤。","犹笑卓家新寡女，远山眉黛画屏边。"]},{"t":"既作前诗因阅袁公安即事起语云个是春江旧舞楼海棠花下小梁州爱其尖丽复演前意效而小变焉题曰个是","f":"七言律诗","c":["个是春江绝艳船，芙蓉塘外小游仙。","偶看竹泪回双袖，全谱枫香入四弦。","细马驮来羞虢国，流莺惊起隔韩嫣。","东南亦有秦家女，白日高楼只爱眠。"]},{"t":"自感 其一","f":"七言律诗","c":["夸父深林托杖根，巫咸渺渺自天阍。","空江落日双悬泪，衰草秋山九逝魂。","何处归耕无妄邑，有人搔首莫愁村。","孤清得学于陵子，李下寒浆足灌园。"]},{"t":"自感 其二","f":"七言律诗","c":["莫臂饥鹰莫钓鳌，泰山遮莫等鸿毛。","日光肯照冯生铗，霜色先凋范叔袍。","迥出楼台何岁月，相依篱落此蓬蒿。","因风漫谢芦中父，海岛俄奔白马涛。"]},{"t":"赠暮冈内兄弟","f":"七言律诗","c":["上池之水玉山禾，黻佩今如负戴何。","地主或兼怜宅相，暮冈全不比朝歌。","即伤饥渴牛羊下，不数于思犀兕多。","自惜流离真琐尾，入林端倚硕人薖。"]},{"t":"雨","f":"七言律诗","c":["榕树垂垂雨欲沈，短扉斜窦昼阴阴。","檐閒鸟雀寒相向，浪里鱼龙迥自深。","身世虚舟还木偶，江河大地有蹄涔。","轻尘只信阳关唱，今日滂沱别更禁。"]},{"t":"四愁 其一","f":"楚辞体","c":["我所思兮在骏台，行行当日陟崔嵬。","真轻伯玉胡琴价，自负相如汉苑才。","待漏琐闱深凤籞，防秋金甲盛龙堆。","北风不那吹华发，荒径南园蘙碧苔。"]},{"t":"四愁 其二","f":"楚辞体","c":["我所思兮在鹉湖，西陵歌舞未荒芜。","此时问俗真黄口，忆昔循陔有绛趺。","禹穴秋风馀霸气，耶溪春色上姑苏。","遥遥牛女同消息，水国青烟散舳舻。"]},{"t":"四愁 其三","f":"楚辞体","c":["我所思兮在雁峰，高高晴雪记前踪。","皇华戒路贤劳独，赤帝名区紫翠重。","投赋汨罗曾痛哭，专经繁露实儒宗。","梅花绝塞今牢落，雪压寒香对偃松。"]},{"t":"四愁 其四","f":"楚辞体","c":["我所思兮在剑津，高歌起舞四愁新。","河梁共上还携手，秘阁曾跻亦洁身。","秋月光阴连碧草，雄风飘举托青蘋。","杜陵同谷哀无数，山雪林猿忽过春。"]},{"t":"谢伯子久游不归有怀","f":"七言律诗","c":["四愁西望浩难凭，诗思何堪向子称。","天际归舟曾易识，江中孤屿若为登。","尚馀华表吟丁鹤，无限秋风叹季鹰。","欲采汀蘋时已过，九嶷烟雾隔层层。"]},{"t":"白燕","f":"七言律诗","c":["故人相见乍疑非，海外精神座上稀。","休傍入宫邻国号，新持赐扇曲江归。","银花屈戌窥轻剪，玉匣芳诸对卷衣。","纵是衔泥身不污，自捎尘网得飞飞。"]},{"t":"哭云淙兄","f":"七言律诗","c":["取义先申报国劳，师行将克绝号咷。","一生心事苌弘碧，百粤经营伍子涛。","眦裂旄头清露泣，身骑箕尾玉堂高。","平生雁序曾师友，今日招魂尚读骚。"]},{"t":"苍梧寓目柬鲁孺发巡抚","f":"七言律诗","c":["西江过雨水盈盈，薄暮荒山片月明。","旧俗虚传分界树，新功应号受降城。","雕床贡马春齐舞，画角啼乌夜莫惊。","翘首五云丰镐地，六龙先问亚夫营。"]},{"t":"和邝湛若苍梧访太真绿珠遗迹","f":"七言律诗","c":["宛转斜阳草径阴，遗钿香袜杳难寻。","山虚旧井鸳鸯甃，水澹孤村翡翠林。","锦步障前花漠漠，紫云回后夜沈沈。","牵牛织女人閒世，黯绝明君远嫁心。"]},{"t":"谒伏波将军祠","f":"七言律诗","c":["白鹭低飞绕汉旗，乌蛮滩上伏波祠。","云台极望悬天阙，铜柱经营出地维。","古柏来风呼罔象，丛茅摇火猎委蛇。","金装下粤空谈笑，薏苡明珠岂免疑。"]},{"t":"至行在拜吏垣感赋","f":"七言律诗","c":["五岭光华复旦初，六龙停跸诏新除。","不堪海岛从王事，遂向天垣读父书。","南国风轻冈上凤，西江波动辙中鱼。","天颜咫尺青蒲地，采得忘忧寄倚闾。"]},{"t":"赠金道隐","f":"七言律诗","c":["西湖浓柳上林花，天下风流在子家。","采采芙蓉俱木末，飞飞鹓鹭复天涯。","越台春韵虞廷石，楚水秋高汉使槎。","最是伏蒲伸白简，忽看行殿绚丹霞。"]},{"t":"酬职方潘员外霜鹤","f":"七言律诗","c":["青春湖海挟飞仙，白马朱明粲锦鞯。","日下心期比鸣鹤，秋来职事托轻蝉。","通侯解佩酬新赋，侍女添香媚晚筵。","欲学卢谌守从事，翻飞仍在圣人前。"]},{"t":"寄方密之学士","f":"七言律诗","c":["桂林西去雪雰雰，皖国残山转郁云。","偃息自怜徵郑宦，激卬人识相张君。","玉堂春别夔龙侣，石室天空麋鹿群。","还倚松风辞好爵，九皋鸣鹤动相闻。"]},{"t":"腊兴","f":"七言律诗","c":["征西仗剑倚霞开，献岁新谣独酒杯。","明月半帘虚入燕，白云层峤远舒梅。","筝调静女鲛绡卷，阵破愁胡羯鼓催。","兵甲尚悬春帐梦，盈盈碧水隔高台。"]},{"t":"赠马五郎大金吾","f":"七言律诗","c":["煌煌京雒想君家，十堰淹留桂海涯。","新执金吾何所恋，久虚兰室莫长嗟。","鹍弦度曲繁三调，虎帐谈经屈五车。","对酒欲期归隐事，碧山何地邵平瓜。"]},{"t":"遥讯万膳部寓处","f":"七言律诗","c":["南浦经年澹绿波，美人东路思如何。","滕王阁上风流远，陆贾城边荆棘多。","桂水月寒淹击楫，兰台春暗失鸣珂。","思君宗衮阽危日，一曲箜篌怨渡河。"]},{"t":"与少司寇黄公感述","f":"七言律诗","c":["古桂烟空石室寒，扶桑低拂海门宽。","屯田日月愁充国，赌墅风流泥谢安。","汉苑望迷承露掌，楚天弹破切云冠。","巨鱼出没无消息，犹自期年守钓竿。"]},{"t":"后白燕","f":"七言律诗","c":["春风翻觉冶游非，公子西园遇亦稀。","桃渡仅随团扇影，瑶池初媵婉罗归。","寒分玉塞难传语，月下银塘早振衣。","正是江南花草杂，将军重幕慎教飞。"]},{"t":"写意","f":"七言律诗","c":["芳草出门花在闺，小屏无影远山低。","流黄已乱回文锦，尺素还将隐起圭。","官渡晚澜虚鸐立，女墙斜月冷乌栖。","不堪衫袖泪重叠，谁唱竹枝湘水西。"]},{"t":"新秋","f":"七言律诗","c":["平昔问天天不应，新秋閒坐觉崚嶒。","铜龙滴水情何竭，乌鹊填桥力自胜。","宫样渐收蝉翼鬓，客怀须重鹄文绫。","洞房靡曼扬州俗，何事观涛必广陵。"]},{"t":"七夕","f":"七言律诗","c":["九天香露下真珠，谁望银河意不输。","侍婢皆思代乌鹊，男儿争得似黄姑。","月中针孔真穿未，云里机丝定卷无。","安得丹青掞天手，年年兹夕绘新图。"]},{"t":"可思","f":"七言律诗","c":["柳色如烟罥绮尘，月光何必掩香茵。","颤将金雀如无股，甜入瓠犀不见唇。","司马长卿还病渴，乘鸾箫史正宜春。","挂开鹦鹉从渠骂，啄碎桃花未足嗔。"]},{"t":"试撷","f":"七言律诗","c":["试撷花房露尽垂，心星相照夜何其。","戏鱼大抵因莲叶，嬲燕从来是柳枝。","赵后凝妆招赤凤，陆郎分橐促斑骓。","安知为雨为云意，十二巫山不可移。"]},{"t":"寄邝湛若","f":"七言律诗","c":["南郭灰心念故庐，西园飞盖结交初。","观鱼乐去逢庄叟，歌凤狂来是接舆。","日色有时荣木槿，海风无象避爰居。","年年脉望看仙化，空老雕虫旧秘书。"]},{"t":"赠某将","f":"七言律诗","c":["一令衔枚昼不哗，一声传箭满风沙。","帐中辩士秦犀首，门下材官汉虎牙。","系肘讵嫌金印重，开颜新贮玉楼斜。","劝君须惜河山誓，不灭胡虏不作家。"]},{"t":"上定兴侯相公","f":"七言律诗","c":["衮钺远离行在所，威声雷动九天加。","帐中辩士梁犀首，戟下将军汉虎牙。","雁值飞书曾落羽，霜迎舞剑不成花。","夜分指顾高台上，已自心过北斗斜。"]},{"t":"以乐府题作唐体五首 其一 昔昔盐","f":"七言律诗","c":["鸳鸯楼下乌欲栖，玳瑁梁间燕吐泥。","月晕圆随汉东蚌，天河倾向汝南鸡。","万方仪态华镫出，一笑横陈翠帐低。","愁见晓鸿征塞北，不知天将定辽西。"]},{"t":"以乐府题作唐体五首 其二 朱鹭","f":"七言律诗","c":["将军不事渔阳掺，伐鼓扬歌朱鹭飞。","白马涛边光景发，朱鸢城下捷书归。","天声并作苍山响，日色中悬赤羽辉。","燕颔何辞驱雁塞，玉颜春思在金微。"]},{"t":"以乐府题作唐体五首 其三","f":"七言律诗","c":["碎叶城秋起阵鹅，圆花床软动灵鼍。","白鱼本是周王瑞，朱鹭新成汉凯歌。","靺鞨装流征马汗，燕支山照美人酡。","黄龙显见麒麟至，陛下垂衣协太和。"]},{"t":"以乐府题作唐体五首 其四 将进酒","f":"七言律诗","c":["明月三五二八夜，春风丝竹管弦时。","若复不饮独归去，空留可怜持与谁。","鸡黍寒家崇汉腊，虹梁晓日艳胡姬。","人閒乌白马生角，一醉君前浑不知。"]},{"t":"以乐府题作唐体五首 其五 秋思","f":"七言律诗","c":["佳人兰室寤青阳，朱鸟窗临堕马妆。","一夜秋风下庭绿，几家明月照流黄。","琵琶声断羞和戎，锦字书回拜护羌。","犹自留情顾华寝，岂知牛女限河梁。"]},{"t":"南中塞上曲","f":"七言律诗","c":["胶寒竹箭犹扬越，笛散梅花已汉关。","小月阵前云出海，骨都营外火连山。","江边玉帐楼船度，马上金钱御府颁。","百尺朝台两铜柱，汉家何日拓南蛮。"]},{"t":"汉臣篇","f":"七言律诗","c":["汉家宫阙入边尘，白草黄榆问远臣。","南越荒坟嘶石马，北庭清露泣金人。","山河不改千秋色，卫霍原轻百战身。","莫忘群公骖驾路，柏梁冠履应星辰。"]},{"t":"苍梧怀古","f":"七言律诗","c":["水绿三湘下九疑，海隅风动帝巡时。","五弦惟托南薰奏，二女何孤北渚思。","轩后衣冠同委蜕，楚臣椒桂独陈词。","谁将百粤文身众，会向箫韶学凤仪。"]},{"t":"厓门吊古 其一","f":"七言律诗","c":["南渡何因断好音，两厓松柏昼阴阴。","鱼鳞屋里君臣会，羊角风前社稷心。","重译海遥天上下，九州金散鼎浮沈。","中原仓卒移龙战，泪尽玄黄根至今。"]},{"t":"厓门吊古 其二","f":"七言律诗","c":["舟中劝学非迂阔，纵有孙吴可奈何。","实异处堂安燕雀，虚言梁海有鼋鼍。","枢衡并拥慈元殿，柴市遥闻正气歌。","千古兴亡问穷海，几时还见不扬波。"]},{"t":"曹溪礼大鉴禅师塔","f":"七言律诗","c":["宝林天外指黄梅，花发菩提五叶开。","祖法云何便南去，新州元自具西来。","山间逐猎人终散，钵里降龙蜕已灰。","闻道此心无所住，愿随溪水日潆洄。"]},{"t":"登楼","f":"七言律诗","c":["万山深入且登楼，萧散看春不断愁。","朝雨疏烟摇大壑，夕阳空影纳神州。","七哀诗思无刘表，十赉文心有敬游。","今日风光仍汉腊，白云多处任淹留。"]},{"t":"早春梦游罗浮","f":"七言律诗","c":["葛令安期几岁年，梦魂春上曜真天。","白云影入飞泉碎，沧海波涵赤日圆。","竹叶成符丹自转，梧花栖凤色相鲜。","如何识路归来遽，身在齐州九点烟。"]},{"t":"始安寻颜延年故迹","f":"七言律诗","c":["延年错彩归风雅，体降元嘉自尔时。","曲水屡承三月诏，竹林惟缀五君诗。","怀人定向浔阳醉，从宦那因汨渚悲。","缓唱椅梧高凤句，桂林秋净月离离。"]},{"t":"之清远","f":"七言律诗","c":["负郭田空客已逋，登舟袁虎漫佣租。","门前小试双文履，江上轻浮五石瓠。","帆挂三江凉雨急，寺残中宿远烟孤。","潮声到枕闻吹笛，为谱清愁寄二禺。"]},{"t":"宫人入道","f":"七言律诗","c":["长信阶前草露晞，碧桃花发紫鸾飞。","峨眉月上眉双远，群玉春深玉一围。","九籥驻颜销楚梦，八琅垂手落秦衣。","君王万寿山川阔，环佩何年妾独归。"]},{"t":"八音二首 其一","f":"七言律诗","c":["金母防閒贮绛宫，石城烟水戏鱼通。","丝抽园客心还乱，竹写湘娥泪亦工。","匏叶春舒迷鷕雉，土囊秋启怯雄风。","革言尚未闻三就，木落寒宵倚断鸿。"]},{"t":"八音二首 其二","f":"七言律诗","c":["金隍归骑杳无踪，石阙衔将玉箸重。","丝履远游愆雒女，竹枝清唱懊吴侬。","匏星妾让牵牛匹，土块谁颁汗马封。","革绪风时初景在，木兰秋晚罢芙蓉。"]},{"t":"春夜闻角","f":"七言律诗","c":["尉佗城上春吹角，月暗千门夜可怜。","几处惊乌栖未暖，往时词客泪应悬。","江山一为迷孤枕，笳鼓何劳媚远天。","无限微吟向明发，晓风吹断越台烟。"]},{"t":"光孝寺铁塔","f":"七言律诗","c":["霸国禅关问大雄，南朝钟梵袭遗风。","曾然劫火藏沙界，似立金茎表汉宫。","狮座何人高说法，貂珰皈佛漫论功。","檐铃不动诸天寂，薄暮愁看海日红。"]},{"t":"奉赠东方先生","f":"七言律诗","c":["斑鬓风流滞汉貂，独怜朱凤出神霄。","弹琴不觉鹴裘敝，赋猎回瞻馺娑遥。","池草昔游专甲帐，岭梅今雨带申椒。","莫驰河朔鹰扬誉，闻道祁连厌射雕。"]},{"t":"珠江与严伯玉话旧","f":"七言律诗","c":["鸣鸟难闻羽翼稀，身馀萍梗涕沾扉。","故山在客云松老，初服从谁昼锦归。","世弃君平方卖卜，年高蘧瑗早知非。","南中芜绝乘骓路，目尽吴阊匹练微。"]},{"t":"春初答曾笃卿去年见赠之作","f":"七言律诗","c":["憔悴江潭赋卜居，半生裘马憺樵渔。","同株已恨三荆别，环堵空垂五柳疏。","梁甫吟成孤管乐，建安才老减应徐。","春风把臂光人胜，怀袖犹珍隔岁书。"]},{"t":"人日寄曹秋岳方伯","f":"七言律诗","c":["渔矶独坐酒微曛，人日高歌想使君。","一字国门空战垒，三城烟火挹春云。","青山不隔金龟侣，篮舆堪随竹马群。","憔悴江潭孤献岁，茂林芳树太氤氲。"]},{"t":"曹方伯闻予谈西樵之胜有作赋答","f":"七言律诗","c":["十载移家叠嶂前，心期五岳尚悠然。","白云楼倚松间月，碧玉琴挥石上泉。","学道定须龙作友，还城应见鹤为仙。","谁兼济物高情在，为问洪厓几拍肩。"]},{"t":"中秋寄楚中旧游","f":"七言律诗","c":["蠛蠓浮去傍高萝，千里秋空对寤歌。","霜落雁低衡岳影，月明人远洞庭波。","频年玉塞燕支老，别苑金盘白露多。","夜静湘南倍萧瑟，二灵清泪碎云和。"]},{"t":"山居闻吴客来五羊多是旧游遥有此寄","f":"七言律诗","c":["月冷吴江枫叶声，莼鲈遥慰十年情。","旧游半倚生公石，新语重携陆贾城。","麟阁惊心仍草莽，鸡坛回首识肥轻。","何当七发开眉宇，秋晚观涛气暂平。"]},{"t":"对酒同黄子","f":"七言律诗","c":["酒酣耳热君勿喧，世上悠悠安足论。","龟策不开严叟肆，雀罗终守翟公门。","天空芳草催鸣鴂，寒入梅花断啸猿。","痛哭穷途今泪尽，且回青眼看乾坤。"]},{"t":"赠高严若","f":"七言律诗","c":["吾爱高生高且奇，钓竿高拂若华枝。","谈天河汉俱无极，蹈海风云自有时。","杂佩实愁芳草歇，画图虚使万山移。","德辉未览同增感，遮莫狂歌笑凤衰。"]},{"t":"寄黄季恒","f":"七言律诗","c":["秋江枫落雁声繁，去岁同君深夜论。","醉倚蠛蠓浮北极，梦惊胡蝶化南园。","临文每叹风云事，作赋能忘笔札恩。","不见柴桑故人久，几回烟水限桃源。"]},{"t":"奉答业师欧先生见怀之作次韵 其一","f":"七言律诗","c":["策杖何从出世氛，避人深识海鸥群。","明珠暗道皆丛怨，磐石虚名谁复闻。","兰畹不供骚客佩，松风时播隐居文。","从游独近朱明路，已小罗浮四百君。"]},{"t":"奉答业师欧先生见怀之作次韵 其二","f":"七言律诗","c":["几载谈天辩五车，浮云城阙望弥遮。","洲中有橘千头实，墙下无桑八口家。","金石古文封小草，丹青明誓托繁华。","每从南郭欣闻籁，终负东陵懒种瓜。"]},{"t":"寄怀祖心禅师","f":"七言律诗","c":["弥天觉路竟孤攀，满月毫光想别颜。","舍利不缄金口偈，袈裟投老玉门关。","清斋硕果悬春署，故国梅花指雪山。","寄语辽城千岁鹤，祇园无恙待师还。"]},{"t":"寄澹归上人","f":"七言律诗","c":["谏草重焚入绀园，昙花初发掩黄门。","何能容易谈天下，祇学阿难白世尊。","南海潮音通瀑布，西泠花雨接风幡。","二樵青翠堪相问，明月依依九逝魂。"]},{"t":"答区叔永见怀之作","f":"七言律诗","c":["风吹城树散群鸦，万事摧藏感鬓华。","旧国自传燕市筑，轻舟宁阻越溪花。","西园邺下难重集，东岳平原忆共誇。","谁倚蘋洲怨春晚，碧云新对一江霞。"]},{"t":"雁来红","f":"七言律诗","c":["上林缯缴亚枝低，下国烟花晚更迷。","女草逢人应绝艳，宾鸿背日不闻嘶。","候残星火虚躔鸟，书度燕支恨牧羝。","最是鴂鸣芳易歇，朱颜终觉负春闺。"]},{"t":"听百舌鸟","f":"七言律诗","c":["新叶新花淑气融，芳郊芳陌几多丛。","岂无鸣律嘘寒谷，自有微辞悦后宫。","春思尽传朱户外，曙烟初满绿杨中。","平生轻薄弦歌者，为尔移情曲未终。"]},{"t":"宫莺诗","f":"七言律诗","c":["难齐双阙凤皇飞，易引重门燕子归。","骀荡春晴翻艳曲，林光花落卷金衣。","几回绿树停宸跸，一抹黄妆透夕晖。","空见人间纷羽翼，托身无出省郎闱。"]},{"t":"端午别万履安严伯玉朱锡鬯还山却寄","f":"七言律诗","c":["楚水遥遥浸钓矶，江楼归兴傍凫飞。","辟兵是处逢端午，望气何人识少微。","花压长林麋鹿过，泉深曲沼鲤鱼肥。","风流飘泊同湖海，期尔名山一掩扉。"]},{"t":"忆邝秘书","f":"七言律诗","c":["洁身曾比向阳翘，秘阁终存桂树招。","鹦鹉赋成人欲杀，鹔鹴裘典令空朝。","彩毫飞檄边霜起，玉貌围城薤露消。","泪落丹台寻故宅，仙羊无迹雨潇潇。"]},{"t":"访黄仪部","f":"七言律诗","c":["红蕉花发碧山陲，鸡黍邀人鹤氅披。","我祖岂知王氏腊，叔孙曾定汉官仪。","当窗远树乌栖尽，剪烛寒宵月上迟。","旧府百龄丞相在，祇应留得白云怡。"]},{"t":"春日山居即事","f":"七言律诗","c":["篱落春风自满堂，荜门烟火近传觞。","忽惊水面千文皱，亦觉山眉半额长。","草绿远郊间赭白，花丛深树隐鹂黄。","九州未纵淩云步，醉后行歌拾禹粮。"]},{"t":"七夕雨集弹琴同朱子茂子祐子习","f":"七言律诗","c":["悲秋一借阳台雨，却怪明河此夕阴。","剪烛试窥牛女渡，落梅先入凤凰琴。","情随天上乘槎客，响切城南捣素砧。","回首珠江花艇夜，玉人歌罢漏沈沈。"]},{"t":"四失诗和徐文长韵 其一 失书","f":"七言律诗","c":["五车书备隐囊提，一自东游锁舍西。","踏踏官街翻积叶，编编私印绝缄泥。","都无关尹逢牛驾，自合庄生惜马蹄。","安得结绳归混沌，便便鼓腹树阴低。"]},{"t":"四失诗和徐文长韵 其二 失画","f":"七言律诗","c":["摩诘无端认画师，禅心真在辋川时。","自馀平远转相袭，何代推迁能久垂。","盘礴人应歌薤露，名山僧每蜕茶毗。","只今飘泊萧然矣，禁得狂风四壁吹。"]},{"t":"四失诗和徐文长韵 其三 失貂","f":"七言律诗","c":["潦倒风尘须发黄，生涯归问五仙羊。","秺侯七叶还西汉，季子千金散洛阳。","火鼠不灰凭造化，青蚨无种信空囊。","美人几有襜褕赠，大醉吟诗雪到床。"]},{"t":"四失诗和徐文长韵 其四 失磬","f":"七言律诗","c":["硁硁鄙质久相留，燕石周人漫应酬。","一足或当夔戛击，泗滨空记玉方流。","浮图钵应三更早，碧落钟虚五岳游。","笑问泉明归去后，还堪如此折腰不。"]},{"t":"忆昔戏效韦郎","f":"七言律诗","c":["故园尝竞海珠游，海气金银十二楼。","霸主台边调叱拨，女郎花里出箜篌。","凤凰栖老邀琴挚，鸿鹄飞回对弈秋。","此处寂寥空怅望，乾坤原是一沙鸥。"]},{"t":"元夜与友人话旧","f":"七言律诗","c":["剪烛烧残白凤膏，旧时人擅五陵豪。","笙歌夜出如琴辔，兰麝春归似草袍。","越地比年空蒟酱，汉宫何处醉蒲萄。","然藜闭户知谁共，纸帐吟看璧月高。"]},{"t":"山枝","f":"七言律诗","c":["去年今日咏山枝，风细金墉月满池。","竹尾虽遥应有实，藕心频折不胜丝。","画图想像轩皇态，歌调殷勤帝子嬉。","何幸丈人峰顶坐，碧笙吹罢对弹棋。"]},{"t":"客赠昭明文选玉台新咏二书山中循览率尔成诗","f":"七言律诗","c":["甲观鸿都安在哉，壁经犹怯祖龙灰。","椎轮有事驱铜辇，宝轴何人擅玉台。","明月珠分隋掌玩，结风衣称楚腰裁。","六朝芳草皆销歇，空隐西园游上才。"]},{"t":"新制丹砂之冠爰赋","f":"七言律诗","c":["飞遁何妨服好奇，儒冠只自信天时。","嵯峨合上朱明洞，酣醉浑空白接篱。","日下朝元宾戴胜，泽中逢霸笑委蛇。","胎禽未老原丹顶，紫凤青鸾是羽仪。"]},{"t":"并蒂莲","f":"七言律诗","c":["青天双华削初成，芳沼移根翠盖倾。","雒浦微波交皓腕，汉宫繁露擢金茎。","飘香一比文禽翼，倚棹全翻绛树声。","同梦绿房深子夜，见君谁道不分明。"]},{"t":"邺台怀古","f":"七言律诗","c":["邺城斜日散陂陀，铜雀荒凉蔓草多。","薤露一为称汉世，墓田空自对漳河。","中原孤寡窥符玺，甲帐婵娟泣绮罗。","词客几回羁旅恨，月明乌鹊迥飞过。"]},{"t":"寄吴门故人","f":"七言律诗","c":["吴门千里故人欢，每折疏麻意莫殚。","茂苑初莺啼杂树，太湖春水溢微澜。","马飞匹练清尘远，鱼隐双钩白日寒。","十载长谣滞桑梓，赁舂何地待梁鸾。"]},{"t":"谢伯子户部自香山见过","f":"七言律诗","c":["曾趋建礼共鸣珂，一落丹霞发已皤。","月满千山惟独寤，花藏三径忽相过。","池边命酒观王鲔，石上题诗拂女萝。","归去登临空海峤，君家还有几羊何。"]},{"t":"读区太史集因赠区二延之","f":"七言律诗","c":["虎变龙文有化工，新词还属旧家风。","西园驾轶中郎将，南国书藏太史公。","蓬转秋山归旅鬓，花飞春涧度诗筒。","明堂钟磬音如缕，谁谓江河日向东。"]},{"t":"寄陈子明","f":"七言律诗","c":["荆蛮逃去见仁风，久客逢人问粤东。","水国有芦遮伍相，阊门何庑寄梁鸿。","雪晴书系胡天雁，江冷魂销楚客枫。","歌作吴趋君试听，白头寥廓素心同。"]},{"t":"病起","f":"七言律诗","c":["病起柴门春已深，迟迟日影向前林。","杨花落尽曾生肘，萱叶齐来好树襟。","渡海月经闻五石，垂堂炯戒谬千金。","何曾行乐城东去，憔悴空知作楚吟。"]},{"t":"中园坐月","f":"七言律诗","c":["独坐中园欲二更，栖乌寥绝树无声。","六时莲水风微动，五色瓜田月倍明。","狭室自娱真已幸，离居相望不堪情。","朝来雨过林林绿，閒夜谁教白发生。"]},{"t":"薛二过宿归后却寄","f":"七言律诗","c":["翩然来对草堂閒，又爱元亭自闭关。","沿岸棹随黄犊去，向汀人共白鸥还。","蝉追高唱传深柳，雨漱微酣到暝山。","后日相思寻步履，隐囊依旧绿苔环。"]},{"t":"怀一灵上人塞上","f":"七言律诗","c":["方袍经岁曳边尘，一雁横秋鵙送春。","碎叶不飞穷海路，征蓬那顾住家人。","烟开山院临关月，雪映龛灯吊野燐。","白马经尊驴背字，只今诗思几由旬。"]},{"t":"薄游方归过某生馆","f":"七言律诗","c":["长松一路接柴荆，昨日言归轸友声。","翠鸟斜飞荷沼漾，玉人端坐竹风清。","舟维坛下歌渔父，琴取闺中抚马卿。","羽翼无多君自爱，秋高鸿鹄谢卢城。"]},{"t":"赠杨明府","f":"七言律诗","c":["飘泊何堪寄一廛，乡心淮海片帆悬。","卜居揽尽中洲莽，嗜酒烹馀大邑鲜。","矫制益知长孺直，著鞭终拟祖生先。","看君一鹗横秋在，云散昏鸦落野田。"]},{"t":"秋野独行因寄茅鍊师","f":"七言律诗","c":["秋敞松关对泬寥，悠然散步引长谣。","冠当岫色沾云叶，杖应泉声响石桥。","远树亭亭孤鹤起，荒原漠漠万蓬飘。","故人独在朱明顶，白鹿新骖学子乔。"]},{"t":"答欧奏孚订游吴门之作","f":"七言律诗","c":["春深吟过赤花洲，酒半思为汗漫游。","江渚几闻袁虎咏，秋风一振马卿裘。","黄云极目寻知己，芳草何心问蹇脩。","此去龙威书可识，玉函先为报罗浮。"]},{"t":"道逢周木天有赠","f":"七言律诗","c":["柳拂铜章早折腰，还闻星使影摇摇。","宦途傍海愁鸿渐，旅食逢秋作叶飘。","羽猎尚劳千里骏，铙歌新动九江潮。","风尘梦想披云得，何惜班荆定久要。"]},{"t":"崧台有沈宋故迹秋日过之赋此","f":"七言律诗","c":["古碑无字绿苔封，犹有初唐词客踪。","海燕惹香贻补阙，夜珠流月鉴昭容。","明河京国空翘首，寒食驩州诧贯胸。","今日笑看垂拱世，楚裳秋净采芙蓉。"]},{"t":"野阔","f":"七言律诗","c":["野阔苍梧云向西，漓江东下楚天低。","清秋牧马羚羊峡，落日跕鸢鸲鹆溪。","炎峤从来尊赤帝，寒烟几处哭黔黎。","可怜旧种桃花客，重问武陵津已迷。"]},{"t":"己亥秋日有寄 其一","f":"七言律诗","c":["秋鸿翼阵起滇池，上相初隆剑履时。","身奉至尊为手足，心惟不二有熊罴。","长江北振灵鼍鼓，驰道西扬翠凤旗。","会见收京求鼎实，峤梅辛苦一南枝。"]},{"t":"己亥秋日有寄 其二","f":"七言律诗","c":["秋入疏槐想汉宫，遥遥天上集鹓鸿。","青山色在离愁远，玉漏声微曙梦通。","七圣何曾迷大块，五丁元自出蚕丛。","功高微管先江左，还遣车书万国同。"]},{"t":"半醺","f":"七言律诗","c":["细雨颓檐酒半醺，商声一弄岭猿闻。","南车指去空沧海，西母谣成间白云。","合浦风生杉叶起，番禺秋老桂枝芬。","何当云鬓看诸少，铜虎金鱼倚翠裙。"]},{"t":"村居寄友人","f":"七言律诗","c":["燕去雕梁竟不还，臣居疑在屋舟间。","溪边列沼夜涵月，竹里开门朝见山。","每踏云根期白足，偶书霜叶戏红颜。","淹留若此向君说，迟暮桂枝空自攀。"]},{"t":"送查伊璜还浙","f":"七言律诗","c":["花落台荒始见君，岭梅如雪惜离群。","惊人上座金盈橐，载妓归舟水映裙。","柳嫩西陵莺语涩，峰晴南岳雁行分。","只今诸弟弦歌宰，越艳吴趋远莫闻。"]},{"t":"荔支 其一","f":"七言律诗","c":["侧生炎夏绿阴阴，答遝曾同献上林。","巴蜀锦封频送骑，罗浮丹就亦来禽。","香披绛袖窥如玉，宴醉红云胜赐金。","闻说渡江萍实赤，朵颐休负日边心。"]},{"t":"荔支 其二","f":"七言律诗","c":["思君颜色比琼枝，岂是炎天雨露私。","山带赪霞初起处，日翔朱凤尚饥时。","摘来偏倚三珠树，捧出宜堆五色丝。","烂向卿云瞻火藻，楚臣犹自荐江蓠。"]},{"t":"五月黎梅萼刺史斋中纳凉","f":"七言律诗","c":["一水何烦远溯洄，荔支湾上柳塘隈。","大夫旧创迎风馆，中圣新持避暑杯。","疏雨洒松棋子落，暗潮翻荇棹歌来。","濠梁陈迹湘累怨，玉麈挥残赋莫裁。"]},{"t":"寄远","f":"七言律诗","c":["若为樽俎滞衔杯，衰草荒烟积汉台。","关内好将屠狗入，郭西何患斩蛟回。","河山远送音书喜，风雨寒生鼓角哀。","我独羊裘披岁暮，一竿惭尔济川才。"]},{"t":"己亥书怀","f":"七言律诗","c":["鸡鸣拂旦羽书闻，玄武湖前太乙军。","樯似邓林开楚望，骑随吴练蹑燕云。","野晴他日游安石，涛起从来怒伍员。","独有子牟瞻魏阙，月船烟岛思纷纷。"]},{"t":"寄方密之","f":"七言律诗","c":["彩毫长挹袖中书，秋色寥寥寄净居。","金粟后身仍怖鸽，碧山回首漫焚鱼。","潮生白下闻仙梵，叶坠枞阳见旧庐。","谁遣汤师吟怨别，暮云江上倍踌躇。"]},{"t":"寄毛子霞武昌幕中","f":"七言律诗","c":["楚吟高彻雁来声，词客飘零尚甲兵。","一讯怀沙淹贾傅，三为祭酒识荀卿。","迷阳草长歌先断，梦雨山沈赋不成。","他日江南采蘋地，潇湘多少故人情。"]},{"t":"寄陶仲调","f":"七言律诗","c":["九畹兰边五柳家，沅湘归去阻瑶华。","名山太史传青简，濒海诸生想绛纱。","怀古独寻洲畔树，悲秋还听月中笳。","上林摇笔空云梦，肯向游畋逐后车。"]},{"t":"寄怀江夏隐士艾木田","f":"七言律诗","c":["赋里怀人楚泽赊，汉阳秋色净君家。","荒田偶种狙公芧，丈室时飞天女花。","门对远峰先落雁，枕欹鸣叶过栖鸦。","闻风不得便相访，千里月明江上沙。"]},{"t":"己亥岁暮","f":"七言律诗","c":["尚平游岳定何年，饮蜡群中戏拍肩。","双鬓欲沾梅峤雪，孤怀悽断竹林烟。","衡门细雨淹三径，欹案隆寒对一编。","吟傍槁梧看腊尽，此心潜发在花前。"]},{"t":"庚子元日","f":"七言律诗","c":["烟霞深处捧春王，漫就农人较雨旸。","一日又看添马齿，十年曾是入鸳行。","嫣红欲醉桃开户，微绿含滋柳向塘。","荐罢辛盘愿何事，太阶平后慰高堂。"]},{"t":"江城旅兴","f":"七言律诗","c":["旅思摇摇拂旆旌，百忧如草蔓江城。","重关不锁浮云态，孤枕空淹夜雨声。","浦外渔灯窥燕垒，津头人语应鸡鸣。","四民一业都无据，谁任飘零困地征。"]},{"t":"止酒示内","f":"七言律诗","c":["接篱空与酒人偕，憔悴身依楚水涯。","典却鹴裘司马渴，梦回鸳禁太常斋。","花间绮席年今老，柳外旗亭雨更霾。","犹为细君时割炙，陆沈何处进如淮。"]},{"t":"圭峰戏呈友人","f":"七言律诗","c":["沧波西望与天平，携手间遵紫水行。","明月车回歧路夕，绿荷衣振一峰晴。","鹤群绕树多窥塔，蜃气为楼半入城。","莫是云潭犯龙性，故人何敢嬲嵇生。"]},{"t":"陆参军贻书招饮不赴戏答以诗","f":"七言律诗","c":["金门索米谢侏儒，骑马群儿笑酒徒。","莲幕尘生高士榻，蔗浆寒彻大官厨。","青楼鸳梦重城闭，绿树莺歌故苑芜。","乡落不知蛮府事，参军何用说娵隅。"]},{"t":"城西七夕","f":"七言律诗","c":["倦客当檐步列星，银河天半落飘萍。","安贫恰与秋皆素，怨别那能岁久青。","城树暝烟笼喜鹊，水轩新月荡飞萤。","谁堪故里成羁旅，欹枕残更酒乍醒。"]},{"t":"避寇","f":"七言律诗","c":["氛起潢池接野烟，秋生皂帽失辽田。","婆娑忍别枌榆地，豁达惟看鸿雁天。","畏道回车疑九折，芳邻将母尚三迁。","腐儒书剑期无恙，愁展蒙庄胠箧篇。"]},{"t":"入光孝寺宿自先上人兰若","f":"七言律诗","c":["三城秋动白云层，旧地重游独拊膺。","觱篥声中才避寇，菩提树下且寻僧。","危巢鹊顾香台饭，暗路人归古殿灯。","君问穷愁不堪说，虞园书破剡溪藤。"]},{"t":"送董无休还会稽兼寄陆惠迪子占兄弟","f":"七言律诗","c":["严城风物倍萧森，斜日河桥去客心。","三策漫劳趋阙献，五噫还为出关吟。","苧萝黛色归装入，茹霅烟波倚棹寻。","且欲从君称二陆，云间髣髴似山阴。"]},{"t":"陈村","f":"七言律诗","c":["皇皇避地此重过，乔木乡园在伐柯。","水绕村墟宜短棹，松阴石路好长歌。","名流莫负前脩在，氏族其如故国何。","閒步赤花洲畔望，绿筠清沼隔烟萝。"]},{"t":"过石帆一株兰若","f":"七言律诗","c":["虚沼长涵钟磬音，庵罗秋色引相寻。","天荒金界疑萧帝，人傲朱门似道林。","法雨定沾狮座近，霜风不到雁堂深。","平居诗思偏怜汝，还为晴窗一朗吟。"]},{"t":"寄钱牧翁","f":"七言律诗","c":["虞山远见紫芝荣，鹤发人间有老成。","眉宇欲开枚叔赋，齿牙曾忝谢公情。","缥缃字化千编蠹，丝竹歌残百啭莺。","谁共容台高典礼，钧天回首醉咸英。"]},{"t":"宿从大堂忆表兄朱子洁","f":"七言古诗","c":["庭院风飘夜合香，旧游人事阅星霜。","朱弦欲抚无钟子，白日终回惜鲁阳。","卿月宵悬枢府冷，□□□□□□□。","良朋叹罢鸰原寂，悽断风前雁两行。"]},{"t":"陶钜标行人见讯却寄陶有旧欢故调之","f":"七言律诗","c":["会稽何处学逃名，苕霅烟波一叶轻。","行李旧恩衔帝阙，落梅新唱动江城。","十年星散杨朱路，半枕云愁宋玉情。","莫是南中留桂树，皇华归客赠生平。"]},{"t":"东过郁洲与空和尚飞锡相近不及往讯归后作寄普雨澹归二上座","f":"七言律诗","c":["病躯漫拟维摩诘，神骏那投支遁林。","道路近来稀会面，津梁疲绝好栖心。","身归独閟松萝迹，书去难酬钟磬音。","为倩阇黎报方丈，凄迷门外见恩深。"]},{"t":"九日江楼雨中","f":"七言律诗","c":["楼居髣髴问仙人，亦插茱萸桂水滨。","秋雨一江沈落照，海波千里暗扬尘。","蚁浮素影辜黄菊，雁歇清声在白蘋。","言送将归归未得，羊裘冲雪去垂纶。"]},{"t":"吊南越王佗","f":"七言律诗","c":["霸图曾与海天赊，真定南来号帝家。","未得攀龙空左纛，何须逐鹿向中华。","笙镛报本推任尉，剑履专权笑吕嘉。","一自高台稀汉使，楼船几度咽金笳。"]},{"t":"舟泊平步怀孙典籍蕡","f":"七言律诗","c":["榕阴江岸起炊烟，忽忆词人草奏年。","使节不须来陆贾，台关空说镇梅鋗。","至今举眼思尧日，终古招魂隔楚天。","吟向南园此时节，蝶残花尽草芊芊。"]},{"t":"经南园书院废址有怀葛无奇侍御","f":"七言律诗","c":["周家柱史汉廷威，绣服风流天下稀。","湖上鸳鸯香阁锁，南中翡翠笔床飞。","栖乌几树当城出，避马何人醉月归。","惆怅輶轩采风往，白云歌断越山薇。"]},{"t":"姑苏","f":"七言律诗","c":["枫叶纷纷自古愁，如花歌舞不曾休。","台临水殿终成沼，春在梧宫已报秋。","但爱青蛾颦月下，焉知白马怒潮头。","五湖烟景和人远，日暮阊门空棹讴。"]},{"t":"燕台","f":"七言律诗","c":["南人北去路茫茫，吹面风高鬓易霜。","望断冥鸿飞碣石，自驱驽马拜昭王。","台经驻辇山空翠，客待捐金日欲黄。","几度芦沟桥上过，燕歌临阙限河梁。"]},{"t":"楚宫","f":"七言律诗","c":["幽兰采罢佩缤纷，忆得微辞善讽君。","清怨瑟堪弹夜月，细腰宫亦梦朝云。","天低沔口来鱼媵，帆转湘南出雁群。","曾见长沙尊傅礼，汨罗沈尽贾生文。"]},{"t":"咸阳","f":"七言律诗","c":["羸马垂鞭气亦豪，关门胜迹莽相遭。","锡来鹑首霸秦缪，会去鸿门兴汉高。","三辅依然环帝里，二崤不动表神皋。","少年却在远林下，閒臂角鹰新放绦。"]},{"t":"沛中","f":"七言律诗","c":["秦关西作汉家基，草色无穷铁马驰。","云气居通高拱处，竹皮冠卸远游时。","遥林鸟尽秋方净，大泽龙归雨更滋。","何物至今传得在，山河不及大风辞。"]},{"t":"雒阳","f":"七言律诗","c":["周王定鼎初营邑，及至东迁近孟津。","往事并流清雒水，旧京终化素衣尘。","铜驼荆棘愁看汝，笙鹤云烟笑谢人。","自是书生徒解咏，五诗无复授西宾。"]},{"t":"蜀中","f":"七言律诗","c":["山木森森闻杜鹃，路难真拟上青天。","当关一士可胜万，分鼎中原翻在边。","剑阁旧踪云栈暗，锦城新雨海棠鲜。","文心对此几能写，绿绮凄清蜀国弦。"]},{"t":"邺中","f":"七言律诗","c":["漳河流尽故宫尘，霸气如从马首新。","东汉缀旒因有国，西园飞盖若无人。","风悲古冢啼山鸟，日射寒塘散渚蘋。","孤客吟边不知暝，建安年后有良辰。"]},{"t":"金陵","f":"七言律诗","c":["秦淮新月浸微波，曾咽当年玉树歌。","双阙荒凉山鸟至，六朝烟霭寺僧多。","桃迎渡口春无限，蘋采江南晚奈何。","莫把须眉倚红粉，酒楼高绝客颜酡。"]},{"t":"隋宫","f":"七言律诗","c":["浪结同心嗣太平，一朝閒梦决东征。","红颜泣尽宫谁守，白骨流多殿自行。","仙李根深摇柳色，后庭花谢到芜城。","横波若久留人住，还望江南无限情。"]},{"t":"江楼归兴","f":"七言律诗","c":["将归更上尉佗楼，楼外烟江惹客愁。","白发影同汀鹭晚，黄花香在井梧秋。","平芜迥绝千林鸟，独树閒邀一叶舟。","惟望故山今夜月，清辉前路慰同游。"]},{"t":"重移村居既北复南未返吾庐慨然兴叹","f":"七言律诗","c":["桑梓依依历草茅，故园应为长蟏蛸。","望穷北渚湘兰种，拣尽南枝越鸟巢。","淮海岂同公路浦，辋川新有孟城坳。","柴门几处秋萧瑟，后夜行吟月下敲。"]},{"t":"寄板桥黎方回务光","f":"七言律诗","c":["板桥霜色带芳篱，四海才名怅昔时。","流水竟孤琴一曲，临风长见玉双枝。","藏书曝日恩犹在，裹革终天泪总垂。","国士只今惭马队，凌江不用奋长离。"]},{"t":"送谈蘧怀游潮阳便还京江","f":"七言律诗","c":["满天寒雨问将归，沧海东流碣石微。","乡思已驰京口去，宾鸿犹欲岭南飞。","春生石砝尝鲜馔，云起金焦见羽衣。","还望台关转寥落，折梅书信莫教稀。"]},{"t":"示族中诸兄弟","f":"七言律诗","c":["秀气环洲云浸矶，枌榆时见旧恩辉。","丁年盛事族人说，丙舍残春江燕飞。","竹长龙孙留劲节，松彫马鬣几成围。","先庐独远北堂老，一赋南陔愁广微。"]},{"t":"循州车世之来江村度岁而还比以诗见寄答此兼讯叶姚诸子","f":"七言律诗","c":["愁寂孤村阅九春，二樵烟霭若为邻。","素馨田外苦吟客，红翠声中肥遁人。","一昨梅香薰水部，祇今蓬户笑山宾。","采薇便拟行歌远，东就鸿濛问矅真。"]},{"t":"寄叶犹龙金吾","f":"七言律诗","c":["鹤峰高卧羽林郎，闻道将雏舞凤皇。","顿逊杯新擎到酒，博山炉旧赐来香。","门前月冷彫弓影，宅内湖涵宝镜光。","早晚灵洲见佳气，可能无意共翱翔。"]},{"t":"走笔因柬止言澹归二上人","f":"七言律诗","c":["郁郁谁能滞此乡，飞鹑走狗共津梁。","钩辀笑客行不得，灵寿扶吾当自强。","句漏洞中期葛令，扶摇枝上过云将。","寄声白足同心侣，古月明灯何处堂。"]},{"t":"寄寿汤惕庵先生","f":"七言律诗","c":["二十年前出宪时，美髯玄发映清姿。","观风只许凛相对，执法敢求深见知。","丹陛也曾留汲孺，碧云何异咏休师。","莫疑棠荫馀霜雪，今日南岩生紫芝。"]},{"t":"过白石村访唐明藜聓其从兄明犀久游未归因并怀之","f":"七言律诗","c":["采菱风急暮天浮，一枕听潮溯上流。","每向亲朋称旅客，独迷烟雨见江鸥。","颓垣护果丹垂树，小艇穿苗绿满畴。","知尔一乡栖息好，白云何处伴人游。"]},{"t":"赤花洲七夕同李樵怀家皖公","f":"七言律诗","c":["龙目离离垂暗津，渔家灯影共星陈。","名香竟日熏荀令，绣被深宵覆越人。","斜汉欲将云树合，闰年贪向月华新。","桑田沧海君休问，结袜閒生雒浦尘。"]},{"t":"和薛秀才旧识邯郸歌姬后入靖江藩府藩国遭乱姬便流落偶于逆旅逢故宦者述姬寄语之作","f":"七言律诗","c":["名士倾城两不惭，丛台歌舞系征骖。","绿珠终合藏金谷，碧玉曾闻嫁汝南。","绠断银床飞桂瘴，弦更瑶瑟怨湘潭。","西风短鬓劳相问，惆怅当年玳瑁簪。"]},{"t":"寄觉度上人","f":"七言律诗","c":["青龙昙壁辋川游，最忆栘花拂寺楼。","千梵放生深院午，一枝扶老故山秋。","阶苔转日摇平仲，窗竹鸣风过鞠侯。","十载支离有尊足，不妨寻我白蘋洲。"]},{"t":"岁除答梁羲倩敦五两甥 其一","f":"七言律诗","c":["荆扉閒掩碧江边，十载愁如水上烟。","溪树半含莺语涩，朔云中断雁行偏。","知音几处逢歌雪，问字何人识草玄。","敝宅屡迁无足相，飘零还见汝家贤。"]},{"t":"岁除答梁羲倩敦五两甥 其二","f":"七言律诗","c":["当年竹马外家游，共看初生似阿侯。","山豆种来杨氏盛，楚兰滋遍女媭愁。","春深豹雾薰书幌，水接鹏溟动钓舟。","千古运期更姓字，虚名知尔世情留。"]},{"t":"壬寅元日","f":"七言律诗","c":["漫拂峨冠向曙烟，颓檐犹得拜高天。","鲲溟见击三千里，雁塞闻归十九年。","米汁从今斋绣佛，露盘依旧捧铜仙。","閒吟欲制将雏曲，且奏村灯社鼓前。"]},{"t":"挽何司寇","f":"七言律诗","c":["汉署星沈紫水滨，冈州难问老成人。","万钱忆会鸣钟里，五羖俄悲相杵邻。","枣下歌传真厌世，橘中棋散竟藏身。","承家更有玄成嗣，乔木他年念世臣。"]},{"t":"春日言怀","f":"七言律诗","c":["寂寞于陵独灌园，秦人鸡犬共桃源。","乌皮几在客谁对，龙眼花繁蜂自喧。","潋滟春波平草阁，槎枒老树夹柴门。","河清可俟还愁暮，试上高台礼日暾。"]},{"t":"八九吟","f":"七言律诗","c":["剑气方寒南斗墟，河清难俟乱离馀。","滔天却讶帻如屋，齧雪犹看旃绕庐。","但有金牛通栈道，可无騧马出莎车。","干戈满目风云晚，深入薜萝还读书。"]},{"t":"秋日西郊宴集","f":"七言律诗","c":["寥落王风蔓草生，荒郊何意会群英。","十年丧乱同王粲，万里归来独子卿。","林际远烟鸦噪晚，雨馀新月雁窥晴。","故园秋色携琴在，吟断西楼画角声。"]},{"t":"癸卯早春口占呈友人","f":"七言律诗","c":["今年岂谓去年非，漠漠慈颜认旧闱。","眷属不离居士室，劳生元息丈人机。","村僮警夜当风语，汀雁嫌泥带雪飞。","三陟自知吟更苦，早春怜尔远游归。"]},{"t":"得钱牧斋宗伯书","f":"七言律诗","c":["吴江飞雪上梅枝，海曲人归积雨时。","双泪正缘乌哺尽，尺书还为雁行悲。","生身金粟能深信，博物张华谬见知。","远目不堪迷匹练，梦周今已觉吾衰。"]},{"t":"首夏东游江上作","f":"七言律诗","c":["高帆挂月转江濆，回首孤村在水云。","赊酒愿逢颜特进，运租期有谢将军。","女墙独树摇乌影，官渡千艘载马群。","前路草长劳未歇，况从先哲挹清芬。"]},{"t":"送雁和元孝","f":"七言律诗","c":["雪后长途在远天，榆关风细客心悬。","迹留南浦因成别，啼过西楼忽渺然。","新影欲低青海月，故群仍破黑山烟。","稻粱不免重来食，多恐惊沙没水田。"]},{"t":"四会访朱子敬表兄学署","f":"七言律诗","c":["潮平江影见秋山，桑梓程途莽苍间。","乱后插萸中表共，庭前收橘广文间。","曲池皓月恒相鉴，高第浮云未可攀。","笑我出门多内顾，片帆西上昨东还。"]},{"t":"程周量梁芝五二子同过","f":"七言律诗","c":["严城旅食笑孤身，结驷同来第一人。","近市久知齐晏子，登坛何有汉韩信。","官街鼓响迎秋急，卜肆帘垂过雨新。","歌罢无车终不出，愧君风雅为扶轮。"]},{"t":"酒酣赠汪汉翀工部","f":"七言律诗","c":["杖藜无赖到东城，话到悬河酒遂倾。","桂树小山成吏隐，桃花深水见交情。","欲持元赋还西鄂，却选青钱忆水衡。","四座相欢重问我，十年忧患感生平。"]},{"t":"赎琴","f":"七言律诗","c":["萧条深负峄阳材，裘敝经时笑古台。","白雪调高人和寡，青蚨飞去尔归来。","秦庭璧在相如睨，汉日笳清蔡琰回。","重拂细尘摩玉轸，一弹还欲进千杯。"]},{"t":"听在犙禅师讲法华经兼较金刚经异同师曰陈乔生意者其憍陈如乎因纪一律","f":"七言律诗","c":["火宅莲华露特寒，比来禅味憺忘餐。","净名复有称摩诘，凿齿非徒对道安。","物论已齐庄马喻，经文重把鲁鱼看。","他年傥授菩提记，妙法悬知得者难。"]},{"t":"送某还义乌营母太夫人葬","f":"七言律诗","c":["何事登堂慰伯俞，空闱一拜旧罗襦。","白杨风急吹萱草，鸿雁天寒泣孝乌。","玉帐珥貂身暂远，瑶台遗蜕手亲扶。","祥芝定发金华岭，雪遍梅花隐绛趺。"]},{"t":"寒江","f":"七言律诗","c":["寒江兵气两无穷，海国渔家沸鼎中。","罗网法张回献鹄，鼓鼙声急散哀鸿。","且邻空舍为孤客，难挟残书命一僮。","奔走至今何计是，杳然虚谷待愚公。"]},{"t":"生日","f":"七言律诗","c":["植根长似九秋蓬，戢翼徒看万里鸿。","晚节可称诗圣得，生年真与觉皇同。","累朝紫诰归逢掖，两鬓清霜点次工。","从此亦知陶写去，缺瓶沽酒按枯桐。"]},{"t":"冬夜赠曹自悦司马","f":"七言律诗","c":["围炉曲宴烂灯花，客话平生益自嗟。","六国印销愁委佩，五湖舟泛不归家。","随身秘笈诸郎负，寄迹残山万树遮。","头白逢人工定拙，好从方朔学龙蛇。"]},{"t":"拱北楼望仙湖里故居","f":"七言律诗","c":["楼下双门车马尘，楼头五夜唱鸡人。","十年清梦里闾改，一片彩云窗槛新。","雀噪北林窥殿影，籁传南郭窅天真。","回翔却问乌衣燕，此处雕梁谁旧邻。"]},{"t":"甲辰小除夕作","f":"七言律诗","c":["零落黄门欻白头，几年萍梗泛沧洲。","结交悔作四公子，学佛思随五比丘。","穹室烟深归祀灶，金银云起去登楼。","明春未得避喧计，空负晓林黄栗留。"]},{"t":"将归九江村旧居先寄亲旧","f":"七言律诗","c":["浮家今拟动归桡，家在中洲宛转桥。","菊落秋英频扫径，池平春水渐通潮。","妻儿已解安容膝，亲友难忘是久要。","斑鬓经冬拌白尽，青山如画待归樵。"]},{"t":"送梁甥敦五德庆广文","f":"七言律诗","c":["越江西上近湘漓，薄禄还同酒一卮。","舅宅昔闻成此相，圣门今见作人师。","猺童语杂城边市，龙母神归树里祠。","莫谓山陬限文教，看君前去拥皋比。"]},{"t":"七夕前梁阜己宅逢王震生初归自豫章","f":"七言律诗","c":["庭邀皎月树含风，归客吟孤旧友同。","老丑自看诗益好，贤豪相待命犹穷。","白藤穿枕眠徐孺，龙眼推筐掷左冲。","劝种宜男家计得，小星言在此城东。"]},{"t":"寄潮州宋上木太守","f":"七言律诗","c":["二十年来名甲科，云间华望郢中歌。","骚坛到郡声逾籍，诗思为官政自和。","挥翰珠光凌夜出，褰帷山翠面南多。","因风黄鹄东飞去，为说朝台有薜萝。"]},{"t":"哭朱远公","f":"七言律诗","c":["绝技翻如不爱身，奄然朝露坠萧晨。","臞形自合骑高鹤，生态空归画美人。","世上名从莲社记，扇头书作蕺山珍。","平生拌得称文弱，遗嗣如何遣负薪。"]},{"t":"城中答王东村家元孝送归中洲草堂之作兼示二三同志","f":"七言律诗","c":["归心一发尉佗楼，一点晴烟见渡头。","三径尚堪携客入，中洲曾是为谁留。","青含浦树喧黄鸟，绿遍江苗过白鸥。","七十二峰无恙在，更于城郭念同游。"]},{"t":"初返故园","f":"七言律诗","c":["昨上归舟寻水云，故园閒旷使情欣。","无穷月色坐皆见，不断花香行即闻。","五亩宅边敦素业，三层阁上蓄奇文。","梁间燕子似相识，飞下小塘衔嫩芹。"]},{"t":"王阮亭客部枉评予诗作此寄赠兼怀令兄西樵吏部 其一","f":"七言律诗","c":["十年不拟北书通，閒听归人话北风。","黄叶小窗寻句在，玉人清署寄声同。","霜凋桂树香犹烈，海浸珊瑚气亦红。","长是微名自珍惜，汝南评却重山东。"]},{"t":"王阮亭客部枉评予诗作此寄赠兼怀令兄西樵吏部 其二","f":"七言律诗","c":["南云长望北云飘，诗思相亲不觉遥。","欲挽颓波谁独峙，解承仙露是双标。","肯邀旧友藏深署，应为宫人赋洞箫。","朝夕看山已相识，琅邪遵海有西樵。"]},{"t":"答沈甸华见赠","f":"七言律诗","c":["风流历历溯西泠，皦日偏高处士星。","远访遂过梅峤路，出寻閒傍李官厅。","龙蛇岁去身犹屈，鸲鹆溪回眼尽青。","来就嵇含询草木，欣然携手折芳馨。"]},{"t":"丙午腊月羊城对雪","f":"七言律诗","c":["怪得年来事事殊，岭南飞雪旧时无。","云凝不见三山黛，天漏争盛合浦珠。","野寺一僧烧榾柮，官街群马从氍毹。","冲寒便欲还山问，糁到溪梅第几株。"]},{"t":"暮春三宿邝无傲斋中迟高望公不至同许式微许二陔赋","f":"七言律诗","c":["丘壑身存鬓任颓，柴扉深掩草堂开。","三春燕语几人问，昨日渔舟特地来。","僮煮碎香凝白室，鸟翻层叶堕青梅。","离心转剧留连地，延伫高高只古台。"]},{"t":"将溯端水而上贻二三知己","f":"七言律诗","c":["村居无计隐烟萝，强走江关无奈何。","举案妇愁储粟尽，牵衣儿竞念书多。","行同老马犹知路，食有嘉鱼且放歌。","寄语离居数君子，道心随处恐消磨。"]},{"t":"初至泷洲访从侄山庄遇故里杜子","f":"七言律诗","c":["诸峰丛翠复丛烟，县境闻开未百年。","山鸟独啼宫保庙，土人多种客家田。","林交虎迹谙樵入，石閟星文厌俗镌。","谁谓龙钟行不得，来巢飞燕共翩翩。"]},{"t":"荆棘","f":"七言律诗","c":["草色如烟偶出寻，参天荆棘晚森森。","未曾说剑逢瞋目，乍可虚舟触褊心。","石窦蝙飞遗土气，柳塘蛙怒象雷音。","知君捷径南山度，乞放骚人泽畔吟。"]},{"t":"西游归贻王大雁侄元孝兼怀梁阜己","f":"七言律诗","c":["重城郭外野溪滨，讲德谁能似此亲。","暂别却无高卧处，薄游还有未归人。","心如蠹柳常经折，字泣鲛珠不救贫。","万里声名千古业，只应相爱寂寥身。"]},{"t":"答赠叶虎竹","f":"七言律诗","c":["少年何事被愁侵，玉树萧萧忆故林。","万卷幼依慈母读，七言閒对野鸥吟。","若教视草知能手，便拥如花不称心。","暂觅交亲道情素，山中萝月约秋阴。"]},{"t":"送谭天水游燕赴周舍人之约","f":"七言律诗","c":["南武城头吹海螺，秋声不觉入离歌。","一尊酒尽闺人别，中秘书藏国士过。","向晚脱貂眠火炕，当风嘶马踏冰河。","内家宋锦装潢巧，戏写蛾眉价必多。"]},{"t":"题詹明府碧纱书厨","f":"七言律诗","c":["明府翻书兴不穷，一编编贮碧厨中。","未开屈戌牙签见，虽隔交疏腹笥通。","晒尽最宜高阁日，披来都是古人风。","与谁汎鉴流观意，绕屋扶疏树一丛。"]},{"t":"客馆秋夕","f":"七言律诗","c":["每日无憀此客居，吟过晚市息喧呼。","湿烟满灶随僮懒，高月黏墙怕影孤。","秋色当空看去淡，道心于物损来无。","曲肱便作家林梦，羞向城西伴夜乌。"]},{"t":"万事","f":"七言律诗","c":["万事推移万虑轻，此身卑贱此心平。","旧牙笏写雕龙句，残玉佩敲风马声。","泉布不私寻葛井，石田祈熟问端坑。","室中多半僧家具，长拟空空学净名。"]},{"t":"贻离患上人","f":"七言律诗","c":["市边为客忽经时，愁极偏能自放眉。","催换夏衣弹吉贝，待炊朝饭数蹲鸱。","人情冷暖逢方觉，物价低昂听不知。","欲访西郊旧禅侣，共看圆月浸秋池。"]},{"t":"陶苦子村居筑楼同元孝侄闭关秋日过之赋此","f":"七言律诗","c":["少小辛勤壮欲休，著书拌得是穷愁。","怀人屡阅经年札，借地新成对月楼。","烟渚棹过妨宿鹭，晚畬锄遍学归牛。","竹林聚会时当记，此处陶家菊正秋。"]},{"t":"龄儿学字诗以勉之","f":"七言律诗","c":["花下看儿学字初，本来文业肯生疏。","拈将斑竹枝常画，摘得□□叶亦书。","记诵料无廷硕并，呼名奢望曲江如。","山妻笑指同堂老，他日飞腾莫学渠。"]},{"t":"喜梁阜己初归同王大雁何皇图吴仪汉陶苦子离患上人分赋得乾字","f":"七言律诗","c":["风尘一拂慰心肝，君别春卿已岁寒。","过岭叶飞声总脆，负霜鸿下迹微乾。","京妆说与持家妇，野服归逢到邑官。","那肯揣摩聊曲就，高弦应得任君弹。"]},{"t":"同梁颙若归西山草堂留题二首 其一","f":"七言律诗","c":["都市行歌径有苔，游人方共主人回。","山连埤堄松遮断，池映阑干花倒开。","数卷缃编留载笔，一庭明月照持杯。","怀人欲揽重重翠，余又西樵归去来。"]},{"t":"同梁颙若归西山草堂留题二首 其二","f":"七言律诗","c":["通津深入小桥斜，城里青山即到家。","善读父书藏旧草，閒携儿戏玩晴花。","水松雨后全生韵，石壁亭西不厌遮。","仲叔自知无累邑，劳君樽酒对桑麻。"]},{"t":"寄陈伯玑兼怀药地禅师","f":"七言律诗","c":["灌婴城内想吾宗，远水将冰树近冬。","庐岳瀑飘常过雪，豫章风起忽无榕。","文期不朽身堪困，诗读平生面尽逢。","待访青原老开士，约君联榻道心胸。"]},{"t":"寄曹秋岳","f":"七言律诗","c":["别来犹见兴飞扬，雅事曾归布政堂。","亲入水岩寻子砚，自开山篓拣生香。","湖梅梦破多多蕊，代雁书稀一一行。","诗体更知无敌甚，戟门看试挽弓强。"]},{"t":"闻钟","f":"七言律诗","c":["钟叩三回三十六，正当七十二峰前。","声如步步渐出寺，我向僧僧同入禅。","数里秋林皆滴露，一江寒月欲浮烟。","此时响歇更何听，佛以一音醒大千。"]},{"t":"破寺","f":"七言律诗","c":["瀑水交流山路断，萧萧孤寺半峰藏。","瓦边红叶坠莲座，窗畔昏鸦投竹房。","饥虎习闻持戒语，湿萤分点坐禅香。","几人到此团圞久，为拨寒炉上石床。"]},{"t":"以诗索何旦兼竹杖何曾许觅一僮并及之","f":"七言律诗","c":["五十閒身老待扶，孤生筇竹笑人孤。","惊心自觉颠危极，回首相怜侍从俱。","便取一枝攀桂树，还添九节采菖蒲。","因君步步寻高岭，岭上仙童遇得无。"]},{"t":"少年行","f":"七言律诗","c":["一身出没总如龙，曾却通侯大邑封。","鹙毳叠飞金抹额，猫睛嵌满铁芙蓉。","旌心雪片能消泪，走地星芒要误烽。","犹自不忘儿女辈，母城阑入闹歌钟。"]},{"t":"美人","f":"七言律诗","c":["人间真见藐姑神，月状云容见敢真。","尚以半身凭保母，不知全态寤文人。","行宜处所朝朱凤，嫁必年时佩玉麟。","川上采珠何足算，生成的是掌中珍。"]},{"t":"古剑","f":"七言律诗","c":["无端宝气烛幽沈，掘得棱棱赤堇金。","土里开花原带血，石头磨水要明心。","奸邪必斩昭生色，王霸经提倚独吟。","出匣未能藏可惜，拌教飞去有人寻。"]},{"t":"水楼晓起寄邝无傲","f":"七言律诗","c":["楼头高卧此劳生，春倦浑如罢力耕。","百舌叫乾朝雨至，虾蟆跳出野塘清。","纱巾拂拭何曾戴，竹杖摩挲却少行。","有约西江先听取，贩鱼船踏水车声。"]},{"t":"罗旁山中","f":"七言律诗","c":["路入崎岖地可怜，土风人事总纷然。","穴中蛇死山猺手，担上鱼行水客肩。","漆树筒添侵露取，铁山炉热并人煎。","谁知宿在茅櫩者，学得残僧暂坐禅。"]},{"t":"寄许清漳","f":"七言律诗","c":["诗心不滓骨尤清，小许公呼作小名。","繁弱挽将才更健，駏驉骑著句还成。","酣歌要得姬人赏，朗咏常教俗客惊。","暂返僻村谁可语，绕园思迸豆花生。"]},{"t":"与药亭夜话","f":"七言律诗","c":["与君相得似婴儿，头白来城且共嬉。","红玉印章钤后玩，石楠书榻卧前移。","山衣日晒裁莲叶，井水宵寒浸荔支。","长此闭门书即著，转怜曾对俗人时。"]},{"t":"寄牧止弟","f":"七言律诗","c":["成名不逐众登天，学得玄门又学禅。","细巷引僧离水寺，阔衫随鹤过秋田。","楼尊大士骑狮相，经夹先皇篆凤笺。","城里不逢那足恨，诸郎新近把诗传。"]},{"t":"西来庵放生","f":"七言律诗","c":["来寻初地便如归，石藓苍苍著野晖。","向晚信心人早集，出笼梳翼鸟齐飞。","钱财少亦通慈念，功德多烦搭戒衣。","法事正完吟思发，微风生树月微微。"]},{"t":"七夕戏赠小男","f":"七言律诗","c":["稚子听人谈七夕，举头真欲尾星行。","催娘案上排生果，替姊笺头录乳名。","乱唱仙歌敲竹简，私斟圣水贮瓷罂。","虽然时节为儿戏，不觉能添老大情。"]},{"t":"赠陈美公","f":"七言律诗","c":["吾兄历宦兼中外，不肯悠悠负甲科。","诏拟汉唐閒体别，诗临吴楚处风多。","宫袍更绣狰狞豸，泉酒新斟翡翠螺。","家寄扬州书却寄，一秋秋思入绫罗。"]},{"t":"宴王氏宅","f":"七言律诗","c":["赵瑟秦筝未肯陈，闽歌视听一齐新。","切肴日本鱼肠剑，跽酒暹罗象背人。","袖领暗薰沈水片，采头高掷出山银。","欲从文士誇馀巧，书带盘旋讶舞身。"]},{"t":"送离公游罗浮","f":"七言律诗","c":["罗浮未得置茅庐，深羡吾师愿有馀。","欲往便辞监院事，临行犹接舍山书。","铁桥立已观空了，哑虎逢当答话初。","独笑离家在城客，眼看云影但踟蹰。"]},{"t":"江上吹笛","f":"七言律诗","c":["日夜龙吟人不知，因之截竹江间吹。","风呼一叶应高鸟，云裂四天敲冻凘。","谁复咿嚘塞蚁穴，直当演漾浮天池。","悄然终曲入怀袖，不见其人千古悲。"]},{"t":"寄慧公上人用前寄在犙禅师韵","f":"七言律诗","c":["袈裟西出雪峰寒，舍卫曾分一钵餐。","白马经惟童寿译，黄梅心自祖师安。","春江欲引回肠去，浊世宜将慧眼看。","居士辩才今善病，君来酬对未应难。"]},{"t":"盂兰盘日西来庵礼舍利","f":"七言律诗","c":["金作浮图藏舍利，师僧请出众人观。","生天直用时时切，消业回思世世难。","惊眼威神灯外转，彻心悲涕水中寒。","病身礼罢空行院，为指芭蕉在药栏。"]},{"t":"寄罗浮古鍊师","f":"七言律诗","c":["飞檐当岭绿烟蒙，玉敕真师住此中。","濯发尚存儿日黑，照颜偏向子时红。","灵蛇脑后挥奔电，玄牝门边答响风。","我独遨游在人世，从师还欲究参同。"]},{"t":"自赠","f":"七言律诗","c":["好处都非外物成，自看不解自心情。","谈诗舞著忘垂老，听梵悲来感宿生。","半口尚沾曾戒酒，终身拌别旧居城。","人家积谷尘皆满，独扫明窗花里明。"]},{"t":"赠把秀卿金吾太师","f":"七言律诗","c":["流落身曾冠羽林，殊方那识秺侯心。","从他屋破迷勋府，不为囊空恨赐金。","柳絮糁腰床上暖，蒲葵遮顶路旁阴。","官家旧事閒閒说，说与江干病客吟。"]},{"t":"过沈郎舟中题赠","f":"七言律诗","c":["平生禁里金吾卫，近住梧江木马船。","绝迹几时随浪尾，看山一路在床前。","烹蔬笑引抽关吏，载鹤閒分粜谷钱。","手把内家香一片，玉皇宫阙望烧烟。"]},{"t":"赠马太监","f":"七言律诗","c":["羁雌啼过定山春，零落先朝一内臣。","长忆九重天子事，还悲七尺丈夫身。","青宫伴久书因熟，红本批多字爱匀。","閒向教门随礼拜，白巾偏称尚衣人。"]},{"t":"秋夜同王说作梁器圃梁药亭作","f":"七言律诗","c":["危叶脱枝孤鸟出，两三人镇在虚堂。","霜天透彻中开卷，月地铺排处及床。","静极惯修陪鹤礼，吟成新得补心方。","不行行便寻溪寺，寒磬声西白藕香。"]},{"t":"中秋夜集詹竹殹宅","f":"七言律诗","c":["不知秋骨渐棱棱，月白闻招带病承。","浸地一庭清上酒，凉天四角白垂灯。","衣单怕倚禁霜树，坐缺思添住岳僧。","重把閒心看童子，累花为塔细分层。"]},{"t":"赠詹竹殹明府","f":"七言律诗","c":["南面居非旧县庭，西旁穿石竹常扃。","留贫客住分官俸，奉老亲欢诵佛经。","花下心开将自采，研头功大待谁铭。","参差年纪同生日，往往叨承倒玉瓶。"]},{"t":"秋钓","f":"七言律诗","c":["行至幽溪清见底，閒閒爱下一条丝。","湍中白小游无恙，石上红衫坐独危。","鹭立并将人影照，叶浮空有水纹知。","悠然网罟前时世，久厌荤腥伴老师。"]},{"t":"汪樽石生子诗以柬之","f":"七言律诗","c":["鹤攒丹顶雏方得，松结虬枝子正生。","鼎畔金银镌福字，房中父母协官名。","预知冬月初勤读，便返南阳晚足耕。","未晓红颜欢几许，东门飞鹊报西城。"]},{"t":"听叶山人弹琴","f":"七言律诗","c":["儿时操弄到于今，今日寥寥太古音。","弹到无声方得手，听来如语只呈心。","瓶花上蚁兼香堕，研水涵龙逗海吟。","近净耳根惟梵呗，即当携此就禅林。"]},{"t":"人日","f":"七言律诗","c":["旧官閒叟及愚民，此日从人唤甚人。","刻就玉章行别号，洗青桐树倚吟身。","妻儿过计多因谷，须发推尊略似银。","独往独留还复值，空园一片鸟声春。"]},{"t":"和陶苦子见示游濂泉之作","f":"七言律诗","c":["生世前身谁复认，多君本是住山僧。","无生法忍终应得，不朽诗篇久已能。","云阁外抛高树果，水帘中彻坏庵灯。","秋游新句还相示，愿證真空益有凭。"]},{"t":"寄赠泰和萧子","f":"七言律诗","c":["名家最是萧居士，往往名山衲子称。","压卷爱摹螭钮玺，包经多剪鹄文绫。","千奴收橘供徭役，五老登峰作近朋。","世好不曾逢道貌，自来文体识庐陵。"]},{"t":"谒南海神庙","f":"七言律诗","c":["从来祀典尊南渎，古庙森森肃海滨。","波影贴旗皆翠羽，日光浮瓦是鱼鳞。","廊搥铜鼓雌雄应，船指针盘子午亲。","身著短蓑来一拜，读碑犹识奉差人。"]},{"t":"梦兄文忠","f":"七言律诗","c":["堪悲堪仰事无穷，三十年来旧梦中。","见老岂因埋血久，呼兄不省易名同。","棠花寂寞开当夜，渚雁缡褷叫向风。","他日众看惟庙貌，壁灯犹闪半窗红。"]},{"t":"屈翁山归自雁门有赠","f":"七言律诗","c":["诗名重译处应闻，四十休嗟未策勋。","边草亦沾兰芷气，陇禽皆学凤凰文。","座擎匕首看豪客，车持流苏载细君。","归到陆生祠畔歇，开装飞出华山云。"]},{"t":"访李生池馆","f":"七言律诗","c":["桄榔里外薛萝阴，隔一溪居便自深。","书屋总抛蔬地置，诗人多过板桥寻。","閒书野事收山叶，偶唤家僮聚水禽。","多少名流空眼底，得无迂拙属知音。"]},{"t":"赠吴僧","f":"七言律诗","c":["时人一见讶多能，老僧争闻得未曾。","千手眼堪悬笔写，万由旬只振衣升。","移来天界千花满，推出湖头片月澄。","话到同门吾世好，欲因亲近作钦承。"]},{"t":"岭南牡丹","f":"七言律诗","c":["昔年花引人看去，今日人閒花却来。","芗泽乍从新雨长，茅堂仍作故家开。","翻呈脂粉于图肖，拟掘珍珠当土栽。","安得穷陬皆有此，普天无地著蒿莱。"]},{"t":"为屈翁山悼妻华姜王氏","f":"七言律诗","c":["朱弦弹罢凤凰飞，金缕空销蛱蝶衣。","芳佩一临湘水岸，仙魂终傍华山畿。","长悬戟府将军爱，却逐瑶台阿母归。","徒使文通对团扇，画成秦女是还非。"]},{"t":"送李乔令北游兼寄程周量","f":"七言律诗","c":["八千里远谁堪客，第五名高尔过人。","竹户闭曾因学道，金台到便不忧贫。","阵寻涿鹿棋无敌，店倚蜚龙药有神。","知向嘈嘈弦管里，细吟佳句属乡亲。"]},{"t":"种梅","f":"七言律诗","c":["古梅一株偃荒圃，移种高斋得所钦。","带土任他苔色上，当空仍此月光临。","人方敛气真能傲，诗要忘言正好吟。","忆得骑驴深雪里，只知香极不知寻。"]},{"t":"之青原访药地禅师留别诸子 其一","f":"七言律诗","c":["敢将孤寂动行尘，每念交游访夙因。","求性浪过知命岁，出门羞说在家人。","深灯闭院空山晓，寒树移舟远岸春。","独领众心前礼足，一时缁白劝行频。"]},{"t":"之青原访药地禅师留别诸子 其二","f":"七言律诗","c":["一岭分江乱石欹，半空飞霰下流澌。","名山兀兀看僧在，心地悬悬不自知。","手札到如经字读，头巾行即戒香披。","舟程一发欣相见，云际松寮月上时。"]},{"t":"弹子矶寄离公","f":"七言律诗","c":["尔缘白鹤峰留住，不及云门逐本师。","轮掌未收迎供地，幞头空报独行时。","船冲晚潦多逢雨，鸟置春巢不露枝。","壁立已令诸念削，向东犹是一相思。"]},{"t":"雄州赠陆孝山太守","f":"七言律诗","c":["当关剧郡是南雄，太守心将静者同。","黄绶上头纡相度，朱幡前面引宗风。","楼吞烟雨层阴积，岭吐梅花五处通。","独策疲驴向山寺，乘骓郊路思无穷。"]},{"t":"赠萧孟昉","f":"七言律诗","c":["心过虔江汩汩流，一峰晴处且夷犹。","名家彭蠡湖西著，姓氏梁皇寺里留。","园列村庄皆歇马，池分沙溆各眠鸥。","藏书自秘谁看得，闻说高僧共一楼。"]},{"t":"过丰城简陈元水","f":"七言律诗","c":["雨过江城赤日寒，此中知有草堂宽。","虬须似雪吟时撚，鸟迹和云篆处看。","乱后畏居宾客列，悲深难语弟兄欢。","陶公归去非常傲，故对閒人道下官。"]},{"t":"望庐山铁壁崖寄阿衍大师","f":"七言律诗","c":["父是法王身嗣法，无烦定省近堂头。","铜瓶久许腰将出，铁壁还应面不休。","松子敲庵嚇蝙蝠，藤梢黏果摘猕猴。","可令瀑布三千丈，下引鄱湖一小舟。"]},{"t":"自南安至南康晤廖昆湖太守","f":"七言律诗","c":["江头江尾极行行，一片心如江水横。","老树临流无积叶，夜鱼停月倍开睛。","休牵世态遮山色，任改乡音和橹声。","一见鄱阳贤太守，台关今接石头城。"]},{"t":"豆叶屏","f":"七言律诗","c":["庐山历访诸精舍，豆叶屏前启半扉。","窗眼放云先箧贮，盆头替米后僧归。","鬼神未得专奇事，狼虎何曾有杀机。","游罢殷勤为君说，此中泉石好相依。"]},{"t":"湖口书怀寄辅昙上人","f":"七言律诗","c":["自怜头白远栖栖，访旧沿洄楚水西。","忆别正看杨柳长，爱行那听鹧鸪啼。","心从章贡诸滩下，手待匡庐五老携。","谁似辅公年未艾，高高茅屋绝攀跻。"]},{"t":"入黄山谒檗庵和尚 其一","f":"七言律诗","c":["兹山如海亦如天，心有归依足倍前。","藜杖掷来猿忽引，松关开著虎常眠。","客装仅似头佗卸，乡贯多烦上座传。","信宿却看无所得，衣环初捧玉隆然。"]},{"t":"入黄山谒檗庵和尚 其二","f":"七言律诗","c":["四千里许恭参谒，一两日来那便辞。","欲去重看人世佛，本来教得自家师。","石松拱立如相送，涧竹扶行胜自持。","别后或蒙方丈念，古坛疏叶镇风吹。"]},{"t":"姚六康石埭署中醮会同张芑山秦又宛沈天士卢弗疑曹扶三张师仲堵雪怀分赋","f":"七言律诗","c":["子明坛上众香焚，法鼓仙音四境闻。","喧处会来皆静理，异乡名下即同群。","簿书乐得交情助，匕箸能将道味分。","陡见满堂浮动极，江南烟水岭南云。"]},{"t":"陵阳江馆送韦寅东访漆夫村居","f":"七言律诗","c":["安乐窝中惟自得，逍遥公后解相寻。","偶逢已是难忘处，独往方谐莫逆心。","僧过落棕思暂坐，蝉堆隔水益长吟。","空馀倦倚江楼客，数尽晴峰日又阴。"]},{"t":"池阳道中寄怀梁药亭","f":"七言律诗","c":["高梧窗远尚闻吟，不隔秋空迥隔林。","楼古试搜文选体，寺凉堪礼大悲心。","定因客住频修馆，可赖官遗得赎琴。","恒说齐云山窈窕，峰峰输尔尽情吟。"]},{"t":"毗陵重遇宋鸿生次韵","f":"七言律诗","c":["笑出高斋罢念离，不询行止只言奇。","凤衰终绝泥涂迹，松老始多霜雪姿。","搜匣且张临得画，借钱教刷梓成诗。","满瓶苦茗道情故，若问沈酣非所宜。"]},{"t":"宿朱吉人莲花庄是赵松雪故居","f":"七言律诗","c":["荻横枫落见莲花，谢绝时流此故家。","通水恰宜官路断，当山不任女墙遮。","疏篱次序编丛卉，小椀分张试洞茶。","见说高斋松雪是，可怜台柏剩霜华。"]},{"t":"吴兴舟过盛舍乡怀凌忠清","f":"七言律诗","c":["遂有芳名异代传，琐闱悽惨烈皇年。","致身只向龙髯上，埋血还争骥尾先。","绝笔可曾通紫极，评文犹见点丹铅。","谁知沧海閒游客，洒泪双流霅水边。"]},{"t":"罨画溪寄慎旃副宪","f":"七言律诗","c":["门当水郭隐湖湾，秋宪家林自爱閒。","偶出总经骚客地，端居能镇道场山。","座参奇石聆深语，酒对禅僧发静颜。","顿使岭南归思缓，刺船仍约画溪还。"]},{"t":"旅中同吴仲徵周彬野集庞君燕寓舍韩叔夜病不至次吴韵","f":"七言律诗","c":["客身浑欲托禅门，且莫寻僧度晓昏。","古道不孤山月鉴，清歌仍共院钟言。","瓷盘白剖霜梨大，石槛阴层露桂繁。","况值枚生才健甚，相如何事病梁园。"]},{"t":"客中自慰","f":"七言律诗","c":["松长阴崖只动梢，鹤凌秋汉不知巢。","无涯好境非难历，有数贤人定得交。","疏放肯拘诗里格，推移休卜易中爻。","随他问字殷勤应，欲采方言著解嘲。"]},{"t":"留别慎旃","f":"七言律诗","c":["更尽乌程酒一觞，赠言书取续篇章。","重华问去天俱远，三箬寻来派共长。","宪府开时偏脱略，宗门悟后好商量。","相期为觅书邮便，海客江帆集半塘。"]},{"t":"访曹秋岳侍郎","f":"七言律诗","c":["鸳鸯湖口橹声催，已见名园径尽开。","对月客心长水满，观涛诗兴广陵回。","曾于牧伯承清荫，自作樵夫信不才。","丝竹东山樽北海，岂期簦笠一趋陪。"]},{"t":"娄县赠孟传是明府","f":"七言律诗","c":["芳菲成佩自青春，海内名高献赋身。","五色羊边行橐旧，九皋禽际绾符新。","多将雅论延诸士，一话尚书忆丈人。","三十馀年交谊在，鸡坛重见岂无因。"]},{"t":"赠徐安士","f":"七言古诗","c":["最是君家人尽识，云间西问采花泾。","鹄当浴处心全白，松长寒时岁正青。","瓮底肯馀新熟酒，案头皆置旧横经。","□□□□□□□，□□□□□□□。"]},{"t":"云间遇皋旭有赠","f":"七言律诗","c":["鲈鱼江冷却归迟，客里陈山有所思。","万里心旌元为友，百年尸祝会看儿。","频来雁叠沙中迹，半折梅交岭北枝。","世故黄金难可必，此情聊与郭生知。"]},{"t":"夜集曹秋岳啬斋同俞右吉项嵋雪次韵","f":"七言律诗","c":["寒客未应无暖席，深斋烛影敛空寥。","衣边水气来三泖，园里山心忆二樵。","鸟倦预依营垒燕，草芳频接上盘椒。","劝酬总是平生侣，大隐偏能赋小招。"]},{"t":"赠张友声","f":"七言律诗","c":["白头重访鹉湖来，见尔那禁喜复哀。","尸祝后人寻畏垒，弦歌当日有澹台。","松筠节在终难折，桃李根深不厌培。","咫尺鲤趋成往事，周旋多谢出兰陔。"]},{"t":"访李灌溪先生","f":"七言律诗","c":["携来情愫满江航，宿昔平生欲并将。","才以属民过里闬，久因良友附门墙。","丛兰砌暖宜閒日，列柏台寒有旧霜。","闻说闭关浑谢客，狎鸥还喜步山塘。"]},{"t":"甘露庵访姚文初","f":"七言律诗","c":["晶晶甘露滴祇树，君向此中长乐饥。","纸帐日高眠起后，茶铛火绝客寻时。","先人交籍惟增感，近日科名总不知。","我亦禅门办归宿，虎丘云极岭南陲。"]},{"t":"索王勤中画菊","f":"七言律诗","c":["共僧摇策入阊门，借问先臣七叶孙。","道在即堪忘禄位，宅抛犹得住閒园。","帘前养鸟能通语，笔底为花觉有魂。","便欲恭求写秋菊，好移霜质傲篱根。"]},{"t":"过虞山忆钱牧斋先生","f":"七言律诗","c":["日淡寒皋雪树枯，若为千里进生刍。","绛雪楼笔求难再，黄牡丹诗赏遂孤。","他日藏山司马在，而今述古老彭无。","脊令原外悲鸣远，那答先生以弟呼。"]},{"t":"虎丘寄吴梅村学士","f":"七言律诗","c":["虎丘深雪闭楼时，一读娄东学士诗。","吟苦秖成江客事，名高翻略世人知。","湖船代榻看迁岸，园树增桥卧及池。","几度有怀犹未访，腊寒邻壁响参差。"]},{"t":"赠梅子初","f":"七言律诗","c":["梅生客住吴门久，枫叶霜吹鹤发稀。","隔岭月高长自照，离乡人见即如归。","故园果熟开书赏，废苑花深扫榻依。","为取山编藏好在，待予相伴隐灵威。"]},{"t":"赠叶汉客","f":"七言律诗","c":["岂择龙江与虎丘，飘然只是采真游。","自甘藜藿如僧戒，不戴芙蓉亦羽流。","千里烟波随放荡，一房花石共绸缪。","他年约尔频相见，来往三茅峰上头。"]},{"t":"吴门旅兴","f":"七言律诗","c":["浪迹吴门且暂休，几多抛掷几多收。","百金未买不龟手，一石尚看能点头。","断简故开眢井匣，寒梅新照面山楼。","木人独入丛花国，誇尽王孙春草游。"]},{"t":"呈灵岩继起和尚","f":"七言律诗","c":["总持翰墨兴堪阑，管领烟霞肯便安。","千地匡庐方筑址，半天黄海已垂竿。","谁将西子廊閒迹，都作南宗位下看。","今日灵岩前立雪，悄然身并老梅寒。"]},{"t":"顿修上人与予相聚吴门有诗见赠予从云閒槜李往返度岁而上人又入池阳未回因留此属和","f":"七言律诗","c":["吴苑秋风飘桂花，残僧羁客叙生涯。","投人诗博云间布，养母钱资庙后茶。","野寺寄泉飞尺牍，湖船摊被护袈裟。","隔年那觅团圞处，独拨松灰坐九华。"]},{"t":"泊舟白门寄赠胡星卿","f":"七言律诗","c":["大江飘泊见閒云，知属金陵旧世勋。","踪迹田间差可觅，姓名城内总无闻。","寻常身被麻衣色，方寸心镌铁券文。","莫怪盘桓无所适，孝陵旁拟表孤坟。"]},{"t":"归宗寺呈天然和尚","f":"七言律诗","c":["四十年前恨不同，高山忽仰客途中。","面当真处才云识，心待归时更叩空。","墨碣字彯池水净，雪房炉射殿灯红。","欣从两世师承地，况自昙摩海岸东。"]},{"t":"重入庐山归宗寺受天和尚戒答西堂角公见赠之作用韵","f":"七言律诗","c":["钵饭馀香著一身，竹房宜贮客囊贫。","诗篇或许超名辈，道行多惭让别人。","石窦纳风泉响细，金轮承日塔光新。","归宗旧地归心属，一见同门即甚亲。"]},{"t":"南州访黎博庵","f":"七言律诗","c":["师表身将高士同，异时犹著起衰功。","五羊交臂惟馀我，两浙文心总属公。","春色生于微雨外，远情归自大江东。","滕王阁畔非贪住，不那频年梦寐通。"]},{"t":"哭药地和尚","f":"七言律诗","c":["青原山色皖江湄，不道来寻是别时。","世出世间双泪尽，吾师吾友一心悲。","难趋觉路呼元伯，谬以音声见子期。","从此无生的须学，净名仍要药王医。"]},{"t":"鹤","f":"七言律诗","c":["无穷山泽炼臞形，几许行藏见性灵。","明月四垂天宇辟，秋钟初扣石堂扃。","閒于竹下愁何事，白彻心中梦自醒。","只合超然绝云影，任人遥指一星星。"]},{"t":"懒","f":"七言律诗","c":["少著经营便不禁，颓然诸念总无心。","閒阶日影黏人驻，高树蝉声到耳沈。","强读只随风展卷，醒眠犹对鼠行琴。","有时早起缘斋沐，散发当头瀑水斟。"]},{"t":"井","f":"七言律诗","c":["清凉消却几家烟，亦向飞流岳顶悬。","导得江河原伏地，贮来涓滴尽通天。","藻垂四面簪瓶满，月下中心叠镜圆。","且就桐阴默然坐，已胜云液注丹田。"]},{"t":"灯","f":"七言律诗","c":["休烧华烛列铜盘，小竹檠新剔起看。","偶结红花如自笑，但留青燄益人寒。","油边鼠迹时三过，卷里萤尸近半乾。","愿托光明通般若，夜深惟见戒僧坛。"]},{"t":"钱","f":"七言律诗","c":["藕心榆荚不知秋，初把铜山一一搜。","共出红炉添火热，散行尘世学泉流。","金边界得天应裂，宝字排成鬼亦愁。","莫讶远方金铸面，贵人偏肯破颜求。"]},{"t":"尘","f":"七言律诗","c":["填满虚空君不见，见飞檐隙日光中。","为心祇怪纷纷细，有色多呈漠漠红。","叶尽清秋山雾别，车流平野海波同。","谁能洒落独离此，入定僧临竹院风。"]},{"t":"乞药","f":"七言律诗","c":["曾经九死得馀生，不意人前唤老成。","秋雨滴亲孤榻卧，古藤扶作两枝行。","心酸实被阴阳患，口苦因吟草木名。","今日向君聊乞药，空斋炉臼十分清。"]},{"t":"典琴","f":"七言律诗","c":["觅遍床头金已尽，殷勤却倩古桐材。","斲从西蜀知无价，弹得南薰不阜财。","曲牖一声饥雀下，前山半死冻梅开。","锦囊在抱朱弦痹，烦为知音一往来。"]},{"t":"寄母族诸表兄弟","f":"七言律诗","c":["每怜栖息大洲时，看尽鱼苗喂小池。","暑气夜消眠听雨，凉飔朝在起吟诗。","颓年不觉周花甲，秃鬓徒然戴竹皮。","惟向外家留一宅，几株残菊弄秋姿。"]},{"t":"任公祀名宦祠","f":"七言律诗","c":["异朝犹仰大夫贤，往昔曾闻父老传。","风宪直能戡日本，外台偏肯挫中涓。","开藩预有三槐兆，带印兼为五穗仙。","今日孙曾修俎豆，海南新荐大鱼鲜。"]},{"t":"山子禅师还宝峰经佛山为众说法作诗纪事","f":"七言律诗","c":["龙象高高幸得攀，法筵开在水云閒。","好教大众为禅侣，方许兹乡号佛山。","一马自天无不踏，五羊馀石亦非顽。","谁能洗发摩尼色，供与吾师系衲还。"]},{"t":"春日登粤王台","f":"七言律诗","c":["飘零回望故园空，纵入芳菲似梦中。","草接尘沙青不得，云离烟火白无穷。","岂因万马惊归燕，愁向千家数废宫。","寂寂古台南武迹，肯容山褐振春风。"]},{"t":"偶成书壁","f":"七言律诗","c":["拱手仙城谢故庐，挨身来卜佛山居。","开门或有新朋至，编户还将旧秩书。","杂遝商船分水路，轰腾神火走雷车。","傥然现出毗耶室，何似乌衣洒扫初。"]},{"t":"送旷圆大师结夏罗浮次见赠韵","f":"七言律诗","c":["此去无烦遇葛洪，欲移灵鹫峙南中。","藏身自会神龙变，开口当令哑虎通。","泉喜独探过夏伏，衲留人补待秋风。","飞云绝顶劳相寄，昏黑擎将晓日红。"]},{"t":"喜天然和尚自庐山归雷峰","f":"七言律诗","c":["四十年中泥望云，三年前谒又萍分。","何期耶舍寺中语，还向雷峰钟后闻。","满地豺狼难塞路，一天龙象肯离群。","乡园幸附匡山侣，羞号青莲与右军。"]},{"t":"效杜樊川体","f":"七言律诗","c":["南金收尽九州馀，魍魉逢人鼎象虚。","自有掘尸从楚望，可无翘足待商于。","羊头乍烂称开国，马角频生命副车。","未必苍苍非正色，绿沈红黦竟何如。"]},{"t":"怀远","f":"七言律诗","c":["秋风入户一萧骚，隔岁离群梦倍劳。","江阁卧看枫叶尽，楚天吟过雁声高。","传闻已觉生欢畅，未见那能免郁陶。","料得飞飞鸿雁羽，尽将云汉覆蓬蒿。"]},{"t":"早雁","f":"七言律诗","c":["此心元与朔方暌，为探风沙羽翼齐。","新起渚田聊且下，旧开云路不曾迷。","天连衡岳青居半，水极潇湘白自西。","近日穹庐徙无所，好音先得报秋闺。"]},{"t":"虎贲将军","f":"七言律诗","c":["不谓丹心热欲焚，星光炯炯烛黄云。","从来草泽堪龙见，转忆花田葬虎贲。","去垒燕犹飞旧社，交锋人亦拜高坟。","秦家督责田横在，未必韩彭独策勋。"]},{"t":"凌海将军","f":"七言律诗","c":["满城人看将军死，绛履宽衣慷慨行。","戈折肯辜回日志，印留堪对伏波名。","毡裘近血甘当溅，魑魅逢魂必尽惊。","一木不支诚足恨，凌烟高阁后人成。"]},{"t":"阁夜","f":"七言律诗","c":["寸土不污星宿在，四天如梦户庭高。","飞腾鸾凤皆云气，变幻鱼龙自海涛。","世乱微躯珍晚节，尘空老眼极秋毫。","露虫风叶听沈尽，大块于今正怒号。"]},{"t":"至日","f":"七言古诗","c":["至日不寒晴更好，岂惟茅屋坐欣欣。","风纡翠辇纤离马，日炙红旗太乙军。","待旦独眠愁辗转，将除人事笑纷纭。","烽烟已觉临三岁，□□□□□□□。"]},{"t":"咏怀古迹五首 其一 苍梧","f":"七言律诗","c":["忆昔光天共帝臣，翠华西狩复南巡。","百蛮奔走千秋事，五岭蹉跎万死身。","兵甲渐加成战地，乡关才出尚比邻。","从来发轫骚人兴，野旷云流望转新。"]},{"t":"咏怀古迹五首 其二 台岭","f":"七言律诗","c":["辛壬癸甲出关回，行路虽难歌莫哀。","敝舍亦劳千里望，中原只透一门开。","伤心逆旅通行李，屈指将军有姓梅。","风度楼前融朔雪，大唐今数曲江才。"]},{"t":"咏怀古迹五首 其三 铜柱","f":"七言律诗","c":["分茅岭下寻铜柱，薄海人思汉伏波。","列阵不难招象马，为梁真欲架鼋鼍。","山川据险将无敌，金石铭功在不磨。","莫道南征犹缓计，凌烟他日看巍峨。"]},{"t":"咏怀古迹五首 其四 桂阳","f":"七言律诗","c":["广郡延袤古桂阳，郡人不省是维桑。","换盐忽漫逢宾客，食藕因思制楚裳。","天下几州真刺史，我来一度旧刘郎。","而今不作看花恨，消息王孙草尽芳。"]},{"t":"咏怀古迹五首 其五 蓝关","f":"七言律诗","c":["韩公谪宦叹崎岖，我亦曾游恨有馀。","催老祇缘千嶂雪，罢朝非为一封书。","晚年好佛心方切，中路逢仙事也虚。","能使世间魑魅息，不烦容徙恶溪鱼。"]},{"t":"集唐 其一","f":"七言律诗","c":["一生自是悠悠者，遽落丹霄起爱憎。","岭树重遮千里目，雪山愁送五溪僧。","窗临绝涧闻流水，叶尽孤村见夜灯。","不为困穷宁有此，曲栏愁绝每长凭。"]},{"t":"集唐 其二","f":"七言律诗","c":["此心期与故人同，独把一杯山馆中。","古往今来只如此，谗言巧佞傥无穷。","孤云独鸟川光暮，九点秋烟黛色空。","欲吊灵均能赋否，楚魂吟去月朦胧。"]},{"t":"送远集古","f":"七言律诗","c":["艰危须仗济时才，儒术于我何有哉。","万里只携孤剑去，群心能捧大明来。","忽蒙汉诏还冠冕，更取峰霞入酒杯。","期向金陵醉江树，东山朝日翠屏开。"]},{"t":"立春日社集学小庾体限韵","f":"五言古诗","c":["览岁玑衡政，陈书钟鼎文。","囊锥休踢嬲，杯酒且殷勤。","金门牛马走，丹穴凤鸾群。","海观卑测蠡，雷声辨聚蚊。","山形迷七圣，涛气溢三军。","柳枝低艳曲，桃花入舞裙。","文豹藏深雾，斑骓蹴白云。","花风殊缱绻，灯月又纷纭。","蒸民思帝力，詹尹溯皇坟。","立春观笑语，行年务见闻。","不教荆璞刖，谁令鲁璧焚。","此时同越祝，今日便逢君。"]},{"t":"西阁书壁三十六韵","f":"五言古诗","c":["嘉名占地木，曾觉豫章生。","橘自淮南种，桐犹爨下声。","精神少微曲，生小广州城。","问业金闺□，随官竹马行。","东湖闻吏事，西苑览神京。","江夏无双誉，何郎第五名。","少年罗雀谢，公子钓鱼成。","白鹄非常浴，丹鸡讵泛盟。","立谈知倜傥，为说近纵横。","自有雌雄剑，非因黑白枰。","得枭甘注瓦，促柱忌弹筝。","竹实全栖凤，蒲牢易振鲸。","黄钟无琐碎，墨翟远咸韺。","气与穹苍近，羞为坚白鸣。","射稽推筑板，驺衍说环瀛。","器有瓠樽用，工非荆棘程。","相如綦组秘，季子揣摩明。","跃马秦中相，驱车甘上卿。","不难同朔荐，方欲请终缨。","拾芥徒云易，怀芳奈不呈。","一朝花扫地，三刖玉埋荆。","宋药金相失，燕台骏自更。","固穷休郁郁，负下莫茕茕。","适意从怀褐，消愁且酌觥。","高歌陵白石，幽曲启朱樱。","锦袖分骄蹇，香奁会品评。","臂留钗股印，眼注烛心檠。","爱客殊无剑，飞仙自有笙。","泽兰香宋玉，台柳系韩翃。","激沼怜鱼宠，为园重女贞。","有时开后閤，未事已先庚。","秋干心能结，春城笑肯倾。","卫生师七发，学道斩三彭。","且尽夔蚿说，宁随鼠璞争。","白华垂粲粲，芳草对怦怦。","画上龙还在，应怜未点睛。"]},{"t":"赠李调甫程乡","f":"五言古诗","c":["花满移新县，源高发远流。","风开山起伏，泉濯土刚柔。","境内驯胎鹤，庭前过目牛。","招来近者悦，出仕学而优。","练武兵抟兕，斑文杖祝鸠。","岁寒重相结，一掖点狐裘。"]},{"t":"下篷辣滩望阴那山","f":"五言古诗","c":["梅州行李出，雁渚钓鱼过。","偃蹇一身小，裴徊九面多。","滩声迅篷辣，山色暗阴那。","篙打鱼虾国，松摇猿狖窝。","沧浪看逝者，白石唱来罗。","是处僧煨芋，前溪鹭食荷。","市稀粮少宿，风健酒虚酡。","岁暮游还远，将如杖履何。"]},{"t":"倡妇思","f":"五言古诗","c":["日照凤城鸦，贱妾是倡家。","单衣八蚕茧，双带四莲花。","青楼盛垂柳，玉井蔓甘瓜。","柱雁移丝足，门兽启铜牙。","东平紫骝马，西陵油壁车。","愿君长似玉，令妾亦无瑕。"]},{"t":"和恼公","f":"五言古诗","c":["卓女眉方敛，何郎粉乍红。","春生清涧曲，家在紫烟丛。","桂魄无非满，桃蹊总是秾。","鱼书新约素，象簟旧韬筒。","闭户看天棘，开窗对水荭。","芳龄推宝凤，短羽拂华虫。","五味调鸡舌，双鬟进鹿茸。","夜依兰烬静，春向柳丝融。","莫指王孙草，聊分少女风。","门楣牵荇菜，殿脚近芙蓉。","虚牝秋传籁，羁雌月作笼。","魂萦因饵茧，意涸为巢蜂。","素绠双瓶挈，朱珰复帐蒙。","春城扶海丱，雾縠借巴賨。","验诀亲飞燕，披图忆有熊。","方诸怀小镜，繁弱惯柔弓。","飙毂驱停隼，星绸靡屈虹。","陪游应馺娑，下拜即崆峒。","莲子抛垂幔，橦花点细封。","里儿贪射鸟，国主识游龙。","子午山心铁，阴阳露掌铜。","超瑕休矫驾，践董实殊踪。","羃历流苏结，团圞织苣烘。","同袍青似草，横佩玉如葱。","鹅管抽湘竹，鹍弦落楚枫。","并肩衔绣褥，反舌唤高墉。","甲观摛文倦，蠡杯把醴浓。","人家箫史玉，姓异霍家冯。","鼎熟淮王药，峰寒白帝桐。","茑萝身久托，凫藻目先从。","蓝帕舒香麝，苍琅振绮栊。","姝颜专小史，卿号叠安丰。","磬折伤秋藿，盘餐惜晚菘。","剑门高蜀弹，梁父侈齐僮。","拭泪窥黄靥，回肠引素总。","幽居防保母，浅立拟昭容。","涉水携交甫，登山代子充。","大兄谭稷下，幼妇读盘中。","锦袭仓庚羽，丝缠叱拨騣。","白团娇建业，绿绮动临邛。","砌净枭壶利，纱明琐语通。","雀飞秦妇恋，骓发陆郎慵。","翠盖轻舟举，金丸大道逢。","绦鹰难忿速，铃犬易怔忡。","碧玉甘颠倒，苕华报吉凶。","珠惊如意袖，花媚细腰宫。","带笑嘲房老，忘机学海翁。","弋绨中隐起，襻带两边缝。","修渚移河鼓，繁霜警曙钟。","蜡光彤管秘，翻讶玉台空。"]},{"t":"手录新诗因成十四韵寄呈业师欧先生","f":"五言古诗","c":["伊昔操柔翰，何期逐转蓬。","克家辜旧德，报国竟无功。","不朽高前训，所思维古风。","愁增青琐秩，赋在明光宫。","几度哀时命，微吟守固穷。","幸生惭散木，不觉复雕虫。","秘想开丹枕，幽思放八鸿。","青山尝独寤，白社向谁同。","夫子步趋远，烟村花木中。","吟边贫是乐，静外气弥充。","今日前闻在，一言千古衷。","俗情不厌拙，文字若为工。","何以循三省，新篇寄一通。","高秋吟望尽，搔首更书空。"]},{"t":"中洲草堂新成","f":"五言古诗","c":["去国徒为尔，为家今在兹。","门庭环牡蛎，花竹閒蹲鸱。","皓月尊前汎，青山牖内窥。","五株彭泽柳，四海习家池。","云物非怀土，乾坤有立锥。","祇应与亲串，晨夕重心期。"]},{"t":"缑山月夜闻王子晋吹笙","f":"五言古诗","c":["此夜山中月，当年鹤上人。","众情无不总，吹断洛城尘。","问子游何远，而今曲尚新。","秋光皆逼汉，箫韵异调秦。","世隔钧天乐，云移放浪身。","愿追馀响去，抗手揖群真。"]},{"t":"秋夜书怀呈知己","f":"五言古诗","c":["生平难重说，良夜感摧颓。","老与时艰至，贫从世胄来。","千人虚郢曲，一饭愧韩才。","偶贷河侯粟，时倾地主杯。","秋空天水合，肠转女牛回。","不是君心鉴，沈忧那自开。"]},{"t":"次韵寄答某","f":"五言古诗","c":["有怀秋色里，西望极乡关。","人远三湘水，天开独秀山。","图书森宪府，牙戟换仙班。","儒行惟尊宋，诗名恰类颜。","虞章披豸合，汉贝劳师颁。","挥斥风云际，绥宁楚粤间。","辕门邀七萃，妆阁侍双鬟。","子月阳方进，臣年鬓未斑。","建陵飞檄出，临武凯歌还。","招隐承相念，衰迟敢浪攀。","掞天雄笔丽，照日大旗殷。","秖觉西江注，能浮钓艇閒。"]},{"t":"长兴陈高祖陵下作","f":"五言古诗","c":["陈祖奋南朝，长兴此丰沛。","清溪派绵邈，圣井源汪濊。","云气铸黄屋，树阴团翠盖。","公卿汉匪惭，侧陋虞亦太。","九五既登庸，子弟阙归会。","革命行虎变，陟遐返龙蜕。","历世莽荆榛，邻寺森松桧。","徒聆故老谭，遂发王孙嘅。","微生信迍贱，远系讵茫昧。","缅从韶石至，一取椒浆酹。"]},{"t":"奉送方孩未先生巡抚粤西十二韵","f":"七言古诗","c":["当今注意新开府，夫子能言旧直臣。","日影虎符明远色，海波龙户洒先尘。","八公山气充函夏，五岭花香拱寿春。","已引祥鸾鸣足足，全褫猛犬吠狺狺。","深观南极张形势，急讯天潢慎齿唇。","山海转输须有力，阴阳调护讵非神。","抑奸量使西门豹，移檄悬奔东郭㕙。","座极长风通浡潏，旗盈高角动嶙峋。","躔星欲借三台近，捷羽因推百粤频。","挥手蜃烟销旦夕，披心蛮部固尊亲。","独扬周代歌元老，已靖唐边信大人。","铜柱直堪依日月，玉堂应创画麒麟。"]},{"t":"四时诗","f":"五言绝句","c":["子春振琴响，卜夏擅诗家。","还邀奕秋戏，一路款冬花。"]},{"t":"柳波曲 其一","f":"五言绝句","c":["烟锁池塘柳，灯垂锦槛波。","回波初试舞，折柳即闻歌。"]},{"t":"续作锁柳销鸿之曲","f":"五言绝句","c":["烟锁池塘柳，烽销极塞鸿。","东枝罢春水，南翼怨秋风。"]},{"t":"又续锁柳沈灯引","f":"五言绝句","c":["烟锁池塘柳，钟沈台榭灯。","灯心红缕密，柳眼绿波澄。"]},{"t":"元夜咏灯影","f":"五言绝句","c":["珠映千门月，花生四壁春。","还因相见处，得倚可怜人。"]},{"t":"怀欧大之康州","f":"五言绝句","c":["君向西江去，西江春水深。","回看升斗水，犹苦涸鱼心。"]},{"t":"上元夜不得傅二同席","f":"五言绝句","c":["春灯合形影，却被春灯隔。","今夜烛光残，绝缨何处客。"]},{"t":"歌者文鸾曾为岑公子使免于难岑心感之与予别二十年江村重遇索予昼扇因援笔以慰之","f":"五言绝句","c":["曾排公子难，会是美人恩。","偏馀歌舞意，潇洒叩柴门。"]},{"t":"口号讯黄公","f":"五言绝句","c":["宫阙崔嵬尽，间关洒扫多。","嗟君追骏足，西去近如何。"]},{"t":"示家僮","f":"五言绝句","c":["翟尉方罗雀，任公尚钓鱼。","行藏吾若此，君意定焉如。"]},{"t":"家僮答","f":"五言绝句","c":["世才无八斗，君橐少千金。","欲审低昂处，空伤去住心。"]},{"t":"明君怨","f":"五言绝句","c":["单于出何所，燕支山上猎。","当日此山名，谁知便呼妾。"]},{"t":"长门怨","f":"五言绝句","c":["毾㲪铺淡色，屈戍动虚声。","不是君恩重，谁堪问长卿。"]},{"t":"飞燕咏","f":"五言绝句","c":["射鸟还来凤，君王总不知。","承恩看合德，玉面发赪时。"]},{"t":"玉阶草","f":"五言绝句","c":["敛袖出屏香，摇綦历阶草。","三十六宫中，自守青苔老。"]},{"t":"杨白花","f":"五言绝句","c":["可怜杨白花，飞似海青鸟。","鸟衔花不来，空见他花嬲。"]},{"t":"客居五咏 其一 竹","f":"五言绝句","c":["屋后藏深竹，情知欲避人。","钓鱼向东海，难折一竿春。"]},{"t":"客居五咏 其二 梧桐","f":"五言绝句","c":["斲琴小自足，栖凤对相求。","今年逢叶落，又似去年秋。"]},{"t":"客居五咏 其三 梨","f":"五言绝句","c":["茅墙数间屋，梨树一园枝。","欲问春风早，其如客思迟。"]},{"t":"客居五咏 其四 枯梅","f":"五言绝句","c":["急忆家园里，梅花满东亩。","等閒看便过，不得诗一首。"]},{"t":"客居五咏 其五 菜","f":"五言绝句","c":["荒畦老妇锄，数日菜根舒。","悬思三千客，只望孟尝鱼。"]},{"t":"犀簪","f":"五言绝句","c":["犀簪长可怜，有如美人发。","细直隐鬉纹，真心应在骨。"]},{"t":"题画为汪伊远","f":"五言绝句","c":["烟树半村墟，青山日将暮。","看山尚不归，期尔孤舟渡。"]},{"t":"马蹄清夜月","f":"五言绝句","c":["马蹄清夜月，人影玉楼春。","朝来池水皱，定有赋风臣。"]},{"t":"古结交行","f":"五言绝句","c":["识尽四方人，身经万里道。","今日归山中，倾心与君好。"]},{"t":"峡山早秋","f":"五言绝句","c":["天上河如带，盈盈落翠微。","可怜中宿月，空照白猿归。"]},{"t":"古别离","f":"五言绝句","c":["紫燕去若飞，君今竟何之。","妾返红闺中，从今夜夜思。"]},{"t":"菩提树","f":"五言绝句","c":["人见菩提树，亦有菩提想。","此树无人时，飕飕千叶响。"]},{"t":"三堂诗 其一 文章经济之堂","f":"五言绝句","c":["迥异凌云构，惟衔昔日恩。","文章与经济，何以副王言。"]},{"t":"三堂诗 其二","f":"五言绝句","c":["文章聊复尔，经济亦何为。","谁识小堂上，高高天语垂。"]},{"t":"三堂诗 其三 中洲草堂","f":"五言绝句","c":["夷犹君莫问，栖息草堂深。","自有卢鸿业，非同泽畔心。"]},{"t":"三堂诗 其四","f":"五言绝句","c":["群山环四面，独立江中屿。","天际有归舟，遥遥日延伫。"]},{"t":"三堂诗 其五 五老山堂","f":"五言绝句","c":["阿五皤然老，尝游五老峰。","归来环堵内，高卧对云松。"]},{"t":"三堂诗 其六","f":"五言绝句","c":["五老攒一峰，五峰尊一老。","奚必商山翁，穷岩拾芝草。"]},{"t":"为孝廉弟牧止咏心性堂 其一","f":"五言绝句","c":["欲以居心性，当从心性居。","伐柯则不远，堂构想规模。"]},{"t":"为孝廉弟牧止咏心性堂 其二","f":"五言绝句","c":["先臣命堂额，质朴有深意。","莫漫说经纶，君看心性字。"]},{"t":"草有雁来红者又名老来红戏题","f":"五言绝句","c":["咄咄欲书空，低徊视草丛。","白头吟莫苦，当是老来红。"]},{"t":"双鹤吟","f":"五言绝句","c":["双鹤桃根啄，三杯棣萼酬。","参差人事异，空忆帝京游。"]},{"t":"水诗","f":"五言绝句","c":["濯波激浮湍，湛澹泛清浔。","鸂鶒溯鸿渚，沅湘波浪深。"]},{"t":"附集王辋川句","f":"五言绝句","c":["之子去何之，愚公谷正愚。","遥知远林际，青霭入看无。"]},{"t":"弹琴","f":"七言绝句","c":["漆暗雕琴象古人，弹琴谁者葛天民。","正襟忽见山头月，凉露微风下角巾。"]},{"t":"望圭峰","f":"七言绝句","c":["圭峰历历树灯残，回首冈洲落照寒。","欲上峰头散愁思，厓门东下水漫漫。"]},{"t":"韩公桥歌","f":"七言绝句","c":["船系连环石两头，一头盐饷接官邮。","一头刺史登临处，清镜寒潭映北流。"]},{"t":"铁马","f":"七言绝句","c":["紫燕桃花舞并旋，高台轻骨响连钱。","人间不少关山恨，绝迹依风也可怜。"]},{"t":"自五羊至河源得二十绝句 其一","f":"七言绝句","c":["帐借江风盖借云，离情倚剑帖龙文。","楼船更倩戈船护，初学乘槎谒圣君。"]},{"t":"自五羊至河源得二十绝句 其二","f":"七言绝句","c":["行李参差两路尘，行人行矣送归人。","风前尽醉林婆酒，白鹤晴峰无那春。"]},{"t":"自五羊至河源得二十绝句 其三","f":"七言绝句","c":["木棉临水烂红霞，躞蹀何之白鼻騧。","傍岸每嗔童子上，插瓶渠为采山茶。"]},{"t":"自五羊至河源得二十绝句 其四","f":"七言绝句","c":["抹额成群锦缆牵，分明旗号亦喧阗。","带牛佩犊非儿戏，待辟吾皇九有田。"]},{"t":"自五羊至河源得二十绝句 其五","f":"七言绝句","c":["带马春沙暂牧场，今朝春水没中央。","水接房星天上厩，分明匹匹肖鸳鸯。"]},{"t":"自五羊至河源得二十绝句 其六","f":"七言绝句","c":["烟起山坳有竹庐，篷窗一半对风虚。","青衣急走奚奴马，红嘴深窥翡翠鱼。"]},{"t":"自五羊至河源得二十绝句 其七","f":"七言绝句","c":["围山周匝倚高墩，多少经营近水村。","世乱深居寻不得，那知山顶是桃源。"]},{"t":"自五羊至河源得二十绝句 其八","f":"七言绝句","c":["不见人家冷却春，青松山上立如人。","招来试语神仙事，背指桑田拂袖尘。"]},{"t":"瓶梅","f":"七言绝句","c":["何郎徙倚不成诗，却月凌风折一枝。","好比禅心共清净，澹然冰雪供军持。"]},{"t":"自先上人偶以诃林绿瓦作枕予亦效之","f":"七言绝句","c":["曾从浩劫忆萧梁，瓴甋休誇汉未央。","试为阇黎留一枕，迦陵身倚绿鸳鸯。"]},{"t":"潘菶伯善弹琵琶比且废置聊此戏之","f":"七言绝句","c":["回窗无语堕风花，玉匣纤尘闭月华。","已识琵琶流怨久，何须今日怨琵琶。"]},{"t":"山中七夕","f":"七言绝句","c":["不知天阙复山庭，欲近银河鹊驾停。","几处离忧逢七夕，孤臣不寐看双星。"]},{"t":"七夕寄容舍人","f":"七言绝句","c":["青山秋澹月初明，羽服临风望玉京。","乌鹊桥前今夕酒，凤凰池上故人情。"]},{"t":"秦淮曲","f":"七言绝句","c":["十二楼昏千斛醪，梦中和语拨檀槽。","秦淮一夕秋风起，百尺帆樯海气高。"]},{"t":"素馨花","f":"七言绝句","c":["宴罢红云拥素馨，紫宫回梦酒初醒。","香风皎月横陈处，不许诸嫔出后屏。"]},{"t":"题自公房","f":"七言绝句","c":["尚白只今成白法，披缁从不染缁尘。","何须四百八十寺，始作东西南北人。"]},{"t":"闻雁","f":"七言绝句","c":["雁翅城南南雁声，朔风无尽夜凄清。","悬知万里阙河黑，欲下方塘一片明。"]},{"t":"送人","f":"七言绝句","c":["庄蹻滇南路不迷，相如拥传汉宫西。","而今帝业驱铜马，莫遣儒生辨碧鸡。"]},{"t":"寄无可上人","f":"七言绝句","c":["疏烟不断远钟鸣，枫叶殷红江水清。","试望江南秋色里，一僧挥麈石头城。"]},{"t":"题故园龙眼树","f":"七言绝句","c":["故园龙眼实初垂，三径荒芜鸟雀欺。","借问交亲情几许，风前消息荔奴知。"]},{"t":"送屈修古游闽中","f":"七言绝句","c":["八闽一半海侵城，万里波涛一叶轻。","边塞中原今莫问，鹧鸪声里送君行。"]},{"t":"寄周四 其一","f":"七言绝句","c":["闽越烟波未阻修，春宫歌舞倚钩辀。","遥知高宴鹏山上，笑问仙城旧贵游。"]},{"t":"寄周四 其二","f":"七言绝句","c":["早将词赋答雄风，贵戚元推第一功。","遍操南音新顾曲，周郎何必在吴中。"]},{"t":"送谭说剑","f":"七言绝句","c":["也为无车出每迟，蒯缑何处合雄雌。","闽中公子深相忆，珠履行行蹑武夷。"]},{"t":"客馆呈主人 其一","f":"七言绝句","c":["五亩方塘一亩宫，满林花叶笑飘蓬。","何当归作灞陵隐，感激裁书报伯通。"]},{"t":"客馆呈主人 其二","f":"七言绝句","c":["王粲当年托景升，登楼犹自意难胜。","莫教邺下留清宴，月照秦川一水澄。"]},{"t":"题中洲水楼","f":"七言绝句","c":["高楼矗矗起方塘，跨作飞桥宛转长。","虽有荆州楼可赋，秦川元是仲宣乡。"]},{"t":"舍侄买驴因戏之","f":"七言绝句","c":["犹子移家策蹇驴，定穿山径入街衢。","悬知日日逢京兆，可得诗如贾岛无。"]},{"t":"晓题楼上","f":"七言绝句","c":["年来踪迹太东西，归卧高楼思转悽。","睡醒五更闻百舌，朝朝都在一枝啼。"]},{"t":"戏画并题","f":"七言绝句","c":["碧涧深深一线天，薜萝空冷石根悬。","老僧独在涧中过，不识往来何处禅。"]},{"t":"昆腔绝句 其一","f":"七言绝句","c":["九节琅玕作洞箫，九宫腔板阿侬调。","千人石上听秋月，万斛愁心也总销。"]},{"t":"昆腔绝句 其二","f":"七言绝句","c":["苏州字眼唱昆腔，任是他州总要降。","含著幽兰辞未吐，不知香艳发珠江。"]},{"t":"昆腔绝句 其三","f":"七言绝句","c":["青藤玉茗浪填词，馀子纷纷俚且卑。","我爱吴侬号荀鸭，异香偷出送歌儿。"]},{"t":"昆腔绝句 其四","f":"七言绝句","c":["游戏当年拜老郎，水磨清曲厌排场。","而今总付东流去，剩取潮音满忏堂。"]},{"t":"读白沙先生诗","f":"七言绝句","c":["虫垂虚室一条丝，炉上孤烟四壁知。","歇下苦吟抽卷看，呼儿抄出白沙诗。"]},{"t":"遥题药地禅师青原新得瀑泉 其一","f":"七言绝句","c":["远公却住青原寺，三叠泉流七祖山。","才向虎狼边振锡，晴虹飞下翠微间。"]},{"t":"遥题药地禅师青原新得瀑泉 其二","f":"七言绝句","c":["混混曹溪水有源，青原一派号山门。","不见大师传祖意，三条冰挂一峰尊。"]},{"t":"遥题药地禅师青原新得瀑泉 其三","f":"七言绝句","c":["官长樵苏尽欢喜，旧山忽见新泉水。","师将一口吸西江，谁共解者愚山子。"]},{"t":"遥题药地禅师青原新得瀑泉 其四","f":"七言绝句","c":["不肯常升讲法台，只应随意把山开。","为怜旧友相如渴，片札将泉过岭来。"]},{"t":"拜水词","f":"七言绝句","c":["炎风吹日熨秋禾，拜水呼天咽浊河。","无计可令沟洫满，千人迸泪作滂沱。"]},{"t":"丹阳道士浇花歌","f":"七言绝句","c":["丹阳丹室牡丹台，台下鸡冠花独开。","未到明年春烂漫，可知丹在道人胎。"]},{"t":"谣俗 其一","f":"七言绝句","c":["行乐乡中羡佛山，肯将螺髻换云鬟。","优场亦摆香花供，唱出清词菩萨蛮。"]},{"t":"谣俗 其二","f":"七言绝句","c":["玉漏无声宝镜开，笙箫细细度云来。","如何竞赏中秋月，打鼓鸣钲响似雷。"]},{"t":"山子和尚索水岩研赠之系以诗","f":"七言绝句","c":["文字因缘未脱离，参禅欲转宝峰机。","虽然不解东坡带，也为山门赠研归。"]},{"t":"法曲","f":"七言绝句","c":["翻歌换舞逐千春，求旧方能变得新。","不见汉宫传髻样，白头梳教及笄人。"]},{"t":"葩经体川流四章","f":"古风","c":["川流浮浮，我今斯居。","不遑朝餔，吁嗟乎权舆。","川流㶁㶁，我今斯息。","不遑朝食，吁嗟乎宿昔。","园中何有，有薪有蔬。","吁嗟权舆，胡食而鱼。","不遑朝餔，曰犹徐矣。","薪蔬惟棘，莫之敷矣。","园中何有，有荼有藿。","吁嗟宿昔，胡食而鲽。","不遑朝食，曰犹绎矣。","荼藿骚骚，莫之藉矣。"]},{"t":"送黎遂球公车北上","f":"七言律诗","c":["南地犹思北地寒，今春当作来春看。","上林始信成名易，芳草无忧行路难。","黄雀野田时一见，青骢到处欲为欢。","只今愁煞离弦笛，还望青云整羽翰。"]}]};